import {readFileSync} from 'node:fs';
const curriculum=JSON.parse(readFileSync(new URL('../blueprint/curriculum.json',import.meta.url),'utf8'));
const B=(en,zh)=>({en,zh});
const sources={
 complex:{title:'MIT — Complex Variables with Applications',url:'https://ocw.mit.edu/courses/18-04-complex-variables-with-applications-spring-2018/'},
 topology:{title:'MIT — Introduction to Topology',url:'https://ocw.mit.edu/courses/18-901-introduction-to-topology-fall-2004/'},
 optimization:{title:'Boyd and Vandenberghe — Convex Optimization',url:'https://web.stanford.edu/~boyd/cvxbook/'},
 algebra:{title:'OpenStax — Algebra and Trigonometry',url:'https://openstax.org/books/algebra-and-trigonometry-2e/pages/preface'},
 calculus:{title:'OpenStax — Calculus',url:'https://openstax.org/books/calculus-volume-1/pages/preface'},
 linear:{title:'MIT — Linear Algebra',url:'https://ocw.mit.edu/courses/18-06-linear-algebra-spring-2010/'},
 discrete:{title:'MIT — Mathematics for Computer Science',url:'https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/'},
 abstract:{title:'MIT — Algebra I',url:'https://ocw.mit.edu/courses/18-701-algebra-i-fall-2010/'},
 analysis:{title:'MIT — Real Analysis',url:'https://ocw.mit.edu/courses/18-100a-real-analysis-fall-2020/'},
 geometry:{title:'MIT — Differential Geometry',url:'https://ocw.mit.edu/courses/18-950-differential-geometry-fall-2008/'},
 units:{title:'BIPM — SI Brochure',url:'https://www.bipm.org/en/publications/si-brochure'},
 stats:{title:'OpenStax — Introductory Statistics',url:'https://openstax.org/books/introductory-statistics-2e/pages/preface'}
};
export const lessons=[];
export const outlines={};
export const titles={};
const N=(en,zh,a,ex,exzh)=>[en,zh,a,'Identify the quantities and apply the stated rule step by step.','明确各量，逐步使用本节规则。',ex,exzh];
const frameworks={};
// Source content is original, with mathematical-reference links and editorial review pending.
function F(course,en,zh,source='algebra'){frameworks[course]={body:[en,zh],source};}
function D(id,zh,terms,def,ex,trap,q1,q2){const f=frameworks[id.split('.')[0]];add(id,zh,terms,def,f.body,ex,trap,q1,q2,f.source);}
const starts={F01:[],F02:['module.F01.04'],F03:['module.F01.05'],F04:[],M01:['module.F01.06'],M02:['module.M01.02'],M03:['module.F02.02'],M04:['module.M01.02'],M05:['module.M01.03','module.M02.02'],M06:['module.M01.01'],M07:['module.M01.05','module.M06.06'],M08:['module.M07.06'],M09:['module.M04.03'],M10:['module.M09.06'],M11:['module.M08.02','module.M09.04'],M12:['module.M08.03'],M13:['module.M08.06','module.F02.06'],M14:['module.F02.06'],M15:['module.M14.06','module.M09.06'],M16:['module.F02.06'],M17:['module.F02.04'],M18:['module.M17.04'],M19:['module.M17.03'],M20:['module.M19.06','module.M08.04'],M21:['module.M01.01'],M22:['module.M16.06','module.M17.06','module.M03.06','module.M21.06'],M23:['module.M05.02','module.M11.06','module.M13.05'],M24:['module.M13.06'],M25:['module.M11.06'],M26:['module.M09.06','module.M07.06']};
function add(id,zh,concepts,definition,mechanism,example,trap,q1,q2,source='algebra'){
 const courseId=id.split('.')[0], mod=curriculum.courses.find(c=>c.id===courseId).modules.find(m=>m.id===id);
 const pair=x=>B(x[0],x[1]);
 const exercises=[q1,q2].map((q,i)=>({id:`module.${id}.${i+1}`,type:'numeric',prompt:pair(q),answer:q[2],tolerance:1e-8,hints:[B(q[3],q[4])],explanation:B(q[5],q[6])}));
 const num=Number(id.split('.')[1]);
 const prerequisite=num===1?(starts[courseId]||[]):[`module.${courseId}.${String(num-1).padStart(2,'0')}`];
 const title=B(mod.title.en,zh);titles[id]=title;
 const cs=concepts.map(pair);
 outlines[id]={concepts:cs,check:B(q1[0],q1[1])};
 lessons.push({id:`module.${id}`,courseId,moduleId:id,title,summary:pair(definition),prerequisites:prerequisite,minutes:25,objectives:[B(`Explain ${concepts[0][0]} and its conditions.`,`解释${concepts[0][1]}及其适用条件。`),B(`Use ${concepts[1][0]} in a worked solution.`,`在解题中使用${concepts[1][1]}。`)],sections:[{type:'concept',title:B('Definitions and notation','定义与记号'),body:pair(definition)},{type:'concept',title:B('Why the method works','方法为什么成立'),body:pair(mechanism)},{type:'example',title:B('A worked example','逐步例题'),body:pair(example)},{type:'pitfall',title:B('Conditions and common mistakes','条件与常见错误'),body:pair(trap)}],exercises,sources:[sources[source]],visual:null,contentStatus:'original-module-first-pass',editorialReview:'pending',coverageNote:B('Core module lesson; further proof problems, transfer practice, and independent subject review remain part of curriculum development.','本课讲授模块核心内容；拓展证明、迁移练习与独立学科审校仍需继续完善。')});
}

add('F01.01','数、分数与比',[['place value','位值'],['equivalent fractions','等值分数'],['unit rate','单位比率']],
['A whole number counts objects. In base ten, each place is ten times the place to its right. A fraction a/b means a copies of one b-th of a whole, with b nonzero. A ratio compares two quantities in a stated order.','整数用来计数；十进制中，每一位的值是右边一位的十倍。分数 a/b 表示 a 个“整体的 b 分之一”，b 不能为零。比按照指定顺序比较两个量。'],
['Multiplying both numerator and denominator by the same nonzero number preserves a fraction because it multiplies by one. Addition requires equal-sized parts: convert to a common denominator first. A unit rate divides the first quantity by the second; its units explain what the result measures.','分子分母同乘一个非零数相当于乘一，因此数值不变。分数相加必须先把份的大小统一，也就是通分。单位比率用前一个量除以后一个量，结果的单位说明它衡量什么。'],
['To add 1/2 and 1/3, split the whole into sixths: 1/2 = 3/6 and 1/3 = 2/6, so the sum is 5/6. If three notebooks cost 12 yuan, the unit price is 12/3 = 4 yuan per notebook. Five such notebooks therefore cost 20 yuan.','计算 1/2 + 1/3 时，把整体分成六份：分别为 3/6 和 2/6，和为 5/6。三本笔记本共 12 元，每本价格为 12÷3=4 元；五本就是 20 元。'],
['Do not add denominators: 1/2 + 1/2 is one whole, not 2/4. A ratio depends on order: distance/time is speed, while time/distance is not speed. Always name the whole for a fraction; half of a large cake need not equal half of a small cake.','不能把分母直接相加：两个二分之一合成一整个，而不是四分之二。距离除以时间是速度，反过来不是。分数必须说明所指整体，大蛋糕的一半不一定等于小蛋糕的一半。'],
['What is 3/4 + 1/8?','3/4 + 1/8 等于多少？',0.875,'Use eighths.','通分为八分之一。','3/4 = 6/8, so the sum is 7/8.','3/4=6/8，和为7/8。'],['Six items cost 42 yuan. What is the unit price?','六件物品共42元，单价多少元？',7,'Divide cost by count.','总价除以数量。','42/6 = 7 yuan per item.','42÷6=7元/件。']);
add('F01.02','代数记号与表达式',[['variable','变量'],['expression','表达式'],['distributive law','分配律']],
['A variable is a symbol whose value can vary or is temporarily unknown. An expression describes a value; an equation asserts that two expressions have equal values. In 3x + 2, x is a variable, 3 its coefficient, and 2 a constant term.','变量是值可以变化或暂时未知的符号。表达式表示数值；等式断言两个表达式的值相等。3x+2中，x是变量，3是系数，2是常数项。'],
['The distributive law a(b+c)=ab+ac follows by combining equal groups. Parentheses determine what is grouped. Substitute by replacing every occurrence of a variable consistently, then perform powers, multiplication and division, and finally addition and subtraction.','分配律a(b+c)=ab+ac来自等量分组。括号规定分组方式。代入时，同一变量的每次出现都要一致替换，再依次计算乘方、乘除、加减。'],
['If x=4, then 2(x+3)=2×7=14. Expanding first gives 2x+6=8+6=14, the same result. To simplify 3x+2x+5, combine coefficients of the same variable: (3+2)x+5=5x+5.','x=4时，2(x+3)=2×7=14；先展开则得到2x+6=8+6=14。化简3x+2x+5时，只合并同类项，得到5x+5。'],
['An equals sign is a claim of equality, not an instruction meaning “and then.” The terms x and x² are not like terms. Write parentheses around negative substitutions: x² at x=−3 is (−3)²=9, whereas −3² conventionally means −9.','等号表示相等，不表示“然后”。x与x²不是同类项。代入负数应加括号：x=−3时，x²=(−3)²=9，而−3²通常表示−9。'],
['Evaluate 4x−1 at x=3.','x=3时，4x−1等于多少？',11,'Replace x by 3.','把x换成3。','4×3−1=11.','4×3−1=11。'],['What is the coefficient of x in 2(x+1)+3x?','2(x+1)+3x中x的系数是多少？',5,'Expand before combining.','先展开再合并。','2x+2+3x=5x+2.','2x+2+3x=5x+2。']);
add('F01.03','集合、函数与映射',[['membership','属于关系'],['domain and codomain','定义域与陪域'],['image and preimage','像与原像']],
['A set is a collection with definite membership; order and repetition do not matter. A function f:A→B assigns exactly one element of B to each element of A. A is its domain, B its codomain, and the attained outputs form its image.','集合是成员资格明确的对象集，顺序与重复不影响集合。函数f:A→B为A中每个元素指定B中唯一一个元素。A是定义域，B是陪域，实际取得的输出构成像集。'],
['Intersection keeps elements belonging to both sets; union keeps elements belonging to either. A function is injective if different inputs never share an output, and surjective if every codomain element is reached. These properties depend on the declared sets as well as the formula.','交集保留同时属于两个集合的元素，并集保留至少属于一个集合的元素。单射要求不同输入的输出不同；满射要求陪域每个元素都有原像。这些性质既取决于公式，也取决于指定的集合。'],
['For A={−1,0,1} and f(x)=x² into B={0,1,2}, the image is {0,1}. The preimage of 1 is {−1,1}. Thus f is neither injective nor surjective: two inputs collide, and 2 is missed.','A={−1,0,1}，f(x)=x²，陪域B={0,1,2}时，像集是{0,1}，1的原像是{−1,1}。它既非单射也非满射：输入有碰撞，且2未被取到。'],
['A formula alone does not always define a function on the proposed domain: 1/x has no real value at zero. An inverse function exists on the full codomain only for a bijection. Several inputs sharing one output is allowed; one input having several outputs is not.','只给公式未必能在指定定义域上定义函数：1/x在零处没有实数值。只有双射才有定义在整个陪域上的反函数。多个输入对应同一输出允许，一个输入对应多个输出则不允许。'],
['How many elements are in {1,1,2,3}?','集合{1,1,2,3}有几个元素？',3,'Repeated entries count once.','重复元素只算一次。','The set is {1,2,3}, with three elements.','该集合就是{1,2,3}，共三个元素。'],['How many real preimages does 4 have under x↦x²?','实函数x↦x²中，4有几个原像？',2,'Solve x²=4.','解x²=4。','The two preimages are −2 and 2.','原像为−2与2。'],'discrete');
add('F01.04','逻辑、量词与否定',[['implication','蕴含'],['universal quantifier','全称量词'],['existential quantifier','存在量词']],
['A proposition has a truth value. “For every x” is universal, written ∀x; “there exists x” is existential, written ∃x. The implication P⇒Q fails exactly when P is true and Q is false. It does not claim that Q causes P.','命题具有真假值。“对每个x”记为∀x，是全称量词；“存在x”记为∃x，是存在量词。P⇒Q仅在P真而Q假时为假，也不说明Q导致P。'],
['Negating a quantified statement switches its quantifier and negates its predicate. Thus not every object is red means some object is not red. Quantifier order matters: a single shared choice is stronger than allowing a different choice for each input.','否定带量词命题时，要交换量词并否定内部条件。“并非所有物体都红”就是“存在不红的物体”。量词顺序很重要：一个统一选择比为每个输入分别选择更强。'],
['Over the integers, ∀x∃y(y>x) is true: choose y=x+1. In contrast, ∃y∀x(y>x) is false because x=y already contradicts the condition. The same symbols in a different order express a different mathematical claim.','在整数中，∀x∃y(y>x)为真，可取y=x+1。∃y∀x(y>x)则为假，因为取x=y就矛盾。符号顺序不同，数学断言也不同。'],
['The converse Q⇒P need not follow from P⇒Q. “Divisible by four implies even” is true, but two is a counterexample to the converse. When negating an inequality, include equality correctly: the negation of x>3 is x≤3.','P⇒Q不能推出逆命题Q⇒P。“被4整除则为偶数”正确，但2反驳其逆命题。否定不等式要正确处理等号：x>3的否定为x≤3。'],
['Among integers 1 through 6, how many disprove “every integer here is even”?','整数1到6中，有几个反驳“这里每个整数都是偶数”？',3,'Find the odd integers.','找奇数。','1,3,5 each make the predicate false.','1、3、5都使条件为假。'],['For x=12, give y=x+1 witnessing y>x.','x=12时，按y=x+1给出满足y>x的见证。',13,'Apply the construction.','使用构造。','12+1=13, which exceeds 12.','12+1=13，大于12。'],'discrete');
add('F01.05','图像、尺度与估算',[['axis scale','坐标轴尺度'],['order of magnitude','数量级'],['interpolation','内插']],
['A graph assigns position to data using named axes and units. A linear axis uses equal distances for equal differences. A logarithmic axis uses equal distances for equal ratios. An estimate is a deliberately approximate value whose useful precision matches the information available.','图像借助带名称与单位的坐标轴把数据变成位置。线性轴以等距表示等差，对数轴以等距表示等比。估算是有意采用的近似，其精度应与已知信息匹配。'],
['Read the origin and tick spacing before comparing slopes. Slope is change in vertical quantity divided by change in horizontal quantity, so its units are a ratio. Interpolation estimates between observations; extrapolation extends beyond them and requires stronger assumptions about the pattern.','比较斜率前先读原点与刻度。斜率是纵向变化除以横向变化，因此单位是两个量的单位之比。内插估计观测之间的值；外推超出观测范围，需要更强的规律假设。'],
['A journey graph contains (2 h,120 km) and (5 h,300 km). The average rate between them is (300−120)/(5−2)=60 km/h. Estimating 198×51 as 200×50 gives about 10000, a quick scale check before exact multiplication gives 10098.','行程图含(2小时,120千米)与(5小时,300千米)，区间平均速度为180÷3=60千米/时。198×51可估为200×50≈10000，再与精确值10098核对数量级。'],
['A truncated vertical axis can visually exaggerate a difference. A straight line on logarithmic axes need not represent a linear relationship in the original quantities. Do not infer unmeasured fine detail from a coarse graph or report more significant digits than the input supports.','截断纵轴会夸大视觉差异。对数坐标上的直线未必对应原量之间的线性关系。粗略图像不能支持未测量的细节，也不能支持超过输入精度的有效数字。'],
['A quantity rises from 8 to 20 in 4 seconds. What is its average rate?','某量在4秒内从8增至20，平均变化率是多少？',3,'Use change divided by time.','变化量除以时间。','(20−8)/4=3 per second.','(20−8)/4=3每秒。'],['Estimate 49×202 by 50×200.','用50×200估算49×202。',10000,'Multiply the rounded values.','乘两个取整值。','50×200=10000.','50×200=10000。']);
add('F01.06','数学表达',[['defined symbols','符号定义'],['equivalent transformations','等价变形'],['conclusion with domain','附定义域的结论']],
['A mathematical explanation names its objects, states assumptions, connects justified steps, and identifies the conclusion. Symbols compress meaning only after their meaning is defined. An equation chain asserts that every listed expression has the same value.','数学说明要命名对象、写明假设、连接有依据的步骤并指出结论。符号只有定义后才能有效压缩意义；连等式断言其中每个表达式都相等。'],
['Separate a reason from a calculation. To solve an equation, perform reversible operations where possible and state restrictions before dividing or taking roots. A complete answer includes the permitted domain, because an algebraic candidate may be forbidden in the original problem.','应把推理依据与计算分清。解方程尽量用可逆操作，除法或开方前说明限制。完整答案包括允许的定义域，因为代数候选值可能不满足原题。'],
['Solve (x²−1)/(x−1)=3 over the reals. First exclude x=1. Factor the numerator as (x−1)(x+1), cancel only because x≠1, then obtain x+1=3 and x=2. Substituting into the original expression gives 3, confirming the admissible solution.','解(x²−1)/(x−1)=3时，先排除x=1。分解分子为(x−1)(x+1)，因x≠1才能约去，得到x+1=3，即x=2。代回原式等于3，确认解合法。'],
['Do not hide a missing argument behind “obviously.” A diagram suggests relationships but does not prove exact equality unless the assumptions guarantee it. Use = for equality, ≈ for approximation, and ⇒ for a logical consequence; these symbols have different jobs.','不要用“显然”掩盖缺失论证。图形能提示关系，却不能单独证明精确相等。等号表示相等，≈表示近似，⇒表示逻辑推出，三者作用不同。'],
['Solve (x²−4)/(x−2)=7, with x≠2.','解(x²−4)/(x−2)=7，已知x≠2。',5,'Factor x²−4.','分解平方差。','Cancel x−2 to get x+2=7, so x=5; it is allowed.','约去x−2得x+2=7，故x=5，且满足限制。'],['How many real solutions does x²=9 have?','x²=9有几个实数解？',2,'Check both signs.','检查正负两种符号。','x=3 and x=−3 both satisfy the original equation.','x=3与x=−3都满足原方程。']);

F('F02','A proof explains why a statement must hold for every object satisfying its assumptions. Start by translating the definitions into usable equations or conditions. Every inference must preserve the scope of the variables: a conveniently chosen example cannot represent an arbitrary object unless its choice was unrestricted. Search for a counterexample before investing in a proof. In a finished argument, name the assumptions, justify the transition to the conclusion, and then check boundary cases independently. Computation can suggest a theorem, but no finite list of examples proves an unrestricted claim.','证明解释为什么所有满足假设的对象都必然满足结论。先把定义翻译成可使用的方程或条件；每一步推理都必须保持变量的范围。除非对象的选择不受限制，否则一个方便的例子不能代表任意对象。投入证明前先寻找反例。完整论证应说明假设、解释如何推出结论，并独立检查边界情况。计算能够提示定理，但有限个例子不能证明无限范围的断言。','discrete');
D('F02.01','命题、定义与反例',[['definition','定义'],['universal claim','全称命题'],['counterexample','反例']],['A definition fixes meaning; a theorem needs proof. One counterexample disproves a universal claim, provided it satisfies every hypothesis.','定义规定意义，定理需要证明。反例必须满足全部假设；一个合格反例就能推翻全称命题。'],['“Every prime is odd” fails at 2: it has exactly two positive divisors, 1 and 2, yet is even. The corrected statement excludes this case.','“每个素数都是奇数”在2处失败：2恰有正因数1和2，却是偶数。修正命题须排除这个情况。'],['An example outside the assumptions is irrelevant. A definition is not proved by listing examples.','不满足假设的例子无关；列举例子也不能证明一个定义。'],N('What is the smallest even prime?','最小的偶素数是多少？',2,'Only 2 is both prime and even.','只有2既是素数又是偶数。'),N('How many positive divisors does a prime have?','素数有几个正因数？',2,'Its divisors are 1 and itself.','正因数为1与自身。'));
D('F02.02','直接证明与等价',[['direct proof','直接证明'],['biconditional','充要条件'],['two directions','两个方向']],['To prove P⇒Q, assume P and derive Q. To prove P⇔Q, establish both implications; one direction is insufficient.','证明P⇒Q要假设P并推出Q；证明P⇔Q必须完成两个方向。'],['If a=2r and b=2s are even integers, a+b=2(r+s). Because r+s is an integer, their sum is even by definition.','若a=2r、b=2s是偶数，则a+b=2(r+s)。r+s为整数，因此和按定义为偶数。'],['Do not assume the conclusion during a forward proof. Reversible algebra can prove equivalence only when all domain restrictions remain valid.','直接证明中不能预设结论；代数变形可逆且定义域条件都保留时，才能证明等价。'],N('For even numbers 14 and 22, find k with 14+22=2k.','14+22=2k，求k。',18,'The sum is 36, which is twice 18.','和为36，即2×18。'),N('How many implication directions are required for an equivalence?','证明等价需要几个蕴含方向？',2,'Prove each statement from the other.','须分别证明两边互相推出。'));
D('F02.03','逆否与反证',[['contrapositive','逆否命题'],['contradiction','矛盾'],['negated conclusion','结论的否定']],['P⇒Q is equivalent to not Q⇒not P. A contradiction proof assumes the hypotheses and the negation of the conclusion, then derives an impossibility.','P⇒Q等价于非Q⇒非P。反证法在假设下再假设结论不成立，推出矛盾。'],['To show n² odd implies n odd, prove the contrapositive: if n=2k, then n²=4k²=2(2k²) is even. This handles every even integer at once.','证明n²为奇数则n为奇数，可证逆否：若n=2k，则n²=4k²=2(2k²)为偶数，一次覆盖所有偶整数。'],['The converse and contrapositive differ. A contradiction must follow from valid steps, not from dividing by zero or making an unrelated false assertion.','逆命题不同于逆否命题；矛盾必须由合法步骤推出，不能靠除零或无关的错误断言。'],N('If n=8, what integer k satisfies n²=2k?','n=8时，n²=2k中的k是多少？',32,'64=2×32.','64=2×32。'),N('How many of 1,2,3,4 have odd squares?','1、2、3、4中有几个数的平方为奇数？',2,'Exactly the odd inputs 1 and 3.','恰为奇数输入1与3。'));
D('F02.04','数学归纳法',[['base case','基础情形'],['inductive hypothesis','归纳假设'],['inductive step','归纳步骤']],['Induction proves a statement indexed by integers: establish the first case, then show each valid case implies the next. Strong induction may use all preceding cases.','归纳法证明整数编号的命题：先证起点，再证当前成立能够推出下一项。强归纳法可使用所有之前的情况。'],['For 1+…+n=n(n+1)/2, the case n=1 holds. Assuming the formula at k, add k+1: k(k+1)/2+(k+1)=(k+1)(k+2)/2.','证明1+…+n=n(n+1)/2：n=1成立；假设k时成立，加k+1得k(k+1)/2+(k+1)=(k+1)(k+2)/2。'],['The induction hypothesis is a temporary assumption, not the theorem for all indices. A step without a base case proves no starting instance.','归纳假设只是临时假设，不是全部命题已成立；没有起点的归纳步骤不能保证任何实例。'],N('Using the formula, find 1+…+20.','用公式计算1+…+20。',210,'20×21/2=210.','20×21÷2=210。'),N('If the statement starts at n=3, which index is the base case?','命题从n=3开始，基础情形的下标是多少？',3,'The first permitted index must be established.','应验证第一个允许的下标3。'));
D('F02.05','不变量与极值方法',[['invariant','不变量'],['monovariant','单调量'],['extremal object','极值对象']],['An invariant stays unchanged under every legal move. A monovariant changes in only one direction. An extremal argument selects a smallest or largest object to restrict what can happen.','不变量在每次合法操作下保持不变；单调量只朝一个方向变化；极值论证选择最小或最大对象来限制可能情况。'],['Changing an integer by +2 or −2 preserves its parity. Starting at 3 therefore never reaches 10. The invariant is the remainder modulo 2, not the magnitude.','每次加2或减2保持奇偶性，因此从3不可能到10。不变量是模2余数，而不是数的大小。'],['An invariant must be checked for every allowed operation. Being unable to find a path does not itself prove impossibility.','必须对每一种允许操作检查不变量；没找到路径本身并不证明不可能。'],N('Starting at 7 and repeatedly adding 4, what is the remainder modulo 4?','从7开始反复加4，模4余数是多少？',3,'Adding 4 preserves the initial remainder 3.','加4保持初始余数3。'),N('A nonnegative integer decreases by at least 1 each step from 9. What is the maximum step count?','非负整数从9开始每步至少减1，最多几步？',9,'After at most nine decreases it reaches zero.','最多减九次就到零。'));
D('F02.06','写作与检查证明',[['hypothesis audit','假设检查'],['boundary cases','边界情形'],['logical gap','逻辑缺口']],['A proof audit checks definitions, quantifiers, domains, and each implication separately. State what is being proved before introducing auxiliary objects.','检查证明要分别核对定义、量词、定义域和每个蕴含；引入辅助对象之前先说明目标。'],['The argument x²=x, divide by x, hence x=1 loses x=0. Repair it by factoring x(x−1)=0 and using the zero-product property, obtaining both 0 and 1.','x²=x直接除以x得到x=1会漏掉x=0。修复方法是分解为x(x−1)=0，利用零乘积性质得到0与1。'],['A correct final answer cannot repair an invalid inference. For numerical evidence, distinguish an observed pattern from a universally established result.','正确答案不能修复非法推理；数值证据中，要区分观察到的规律与已证明的普遍结论。'],N('How many real solutions satisfy x²=4x?','x²=4x有几个实数解？',2,'x(x−4)=0 gives 0 and 4.','x(x−4)=0，解为0与4。'),N('What solution is lost by dividing x²=4x by x?','x²=4x直接除以x会漏掉哪个解？',0,'Division excludes zero, although it solves the original equation.','除法排除了零，但零满足原式。'));
F('F03','A measurement connects an observation to a defined quantity, unit, and procedure. Keep raw observations separate from processed values so another person can repeat the calculation. A model is a deliberately simplified description: name what it ignores before comparing it with data. Agreement with one observation is evidence, not a proof that the model is uniquely correct. Repeated measurements reveal some random variation; they do not automatically reveal a shared calibration error. Report the uncertainty relevant to the conclusion and investigate large residuals instead of deleting inconvenient observations.','测量把观察与明确的量、单位和过程联系起来。原始观察应与处理后的数值分开，便于复算。模型是有意简化的描述，比较数据前应说明忽略了什么。与一次观察吻合是证据，不证明模型唯一正确。重复测量能揭示部分随机波动，却不一定揭示共同的校准偏差。应报告与结论相关的不确定度，并调查较大的残差，不能随意删除不合意数据。','units');
D('F03.01','SI单位与量纲分析',[['base unit','基本单位'],['derived unit','导出单位'],['dimension','量纲']],['A unit supplies a reference size; dimension records the kind of quantity. Speed has dimension length/time and SI unit metre per second.','单位提供参照大小，量纲说明量的种类。速度的量纲是长度/时间，SI单位是米每秒。'],['Convert 72 km/h by multiplying 1000 m/km and dividing 3600 s/h: 72×1000/3600=20 m/s. Conversion factors equal one, so the physical quantity is unchanged.','72千米/时乘1000米/千米，再除3600秒/时，得到20米/秒。换算因子等于一，不改变物理量。'],['You may add only quantities of the same dimension. Dimensional consistency is necessary but cannot determine a missing numerical factor such as one half.','只有同量纲的量才能相加；量纲一致是必要条件，却不能确定二分之一之类的数值系数。'],N('Convert 36 km/h to m/s.','36千米/时等于多少米/秒？',10,'36×1000/3600=10.','36×1000÷3600=10。'),N('An area is 2 m². How many cm² is it?','2平方米等于多少平方厘米？',20000,'Each metre contributes a factor 100; square the conversion.','每个长度因子乘100，因此面积乘10000。'));
D('F03.02','测量与不确定度',[['resolution','分辨率'],['random error','随机误差'],['systematic error','系统误差']],['Resolution is the smallest distinguishable change. Random variation changes between trials; systematic error shifts results in a consistent way. Uncertainty describes a range of plausible values under stated assumptions.','分辨率是可区分的最小变化；随机波动在试验间变化，系统误差一致地偏移结果。不确定度在明确假设下描述合理值范围。'],['Measurements 9.8,10.0,10.2 mm average to 10.0 mm. Their spread does not prove the ruler is calibrated. If every reading is 0.5 mm high, averaging preserves that bias.','9.8、10.0、10.2毫米的平均值为10.0毫米；离散程度不能证明尺子校准正确。若每次都高0.5毫米，平均仍保留偏差。'],['Do not confuse accuracy with repeatability. Writing extra decimal places does not improve an instrument. Specify whether a reported uncertainty is a bound or a statistical interval.','准确不等于重复性好；多写小数位不能改善仪器。应说明不确定度是界限还是统计区间。'],N('Find the mean of 4.9,5.0,5.1.','4.9、5.0、5.1的均值是多少？',5,'Their sum is 15; divide by three.','和为15，除以3。'),N('A 20 mm reading is known to be 2 mm too high. What is the corrected value?','20毫米读数已知偏高2毫米，校正值是多少？',18,'Subtract the known positive bias.','减去已知正偏差2。'));
D('F03.03','图表与数据解释',[['scatter plot','散点图'],['slope units','斜率单位'],['association','关联']],['A scatter plot shows paired observations. Trend, spread, and outliers describe different features. Association means quantities vary together; it does not specify a causal mechanism.','散点图展示成对观察。趋势、离散与离群值描述不同特征。关联表示共同变化，不指定因果机制。'],['For time 1,2,3 s and position 2,4,6 m, the points fit position=2×time. The slope is 2 m/s. A position of 9 m at 3 s would leave a residual of 3 m.','时间1、2、3秒对应位置2、4、6米，符合位置=2×时间，斜率为2米/秒。若3秒测得9米，残差为3米。'],['Join points only when interpolation is meaningful. Bar-chart categories do not necessarily form a continuous variable, and visual correlation does not remove confounding.','只有内插有意义时才连接点；柱状图类别未必连续，视觉相关也不能排除混杂因素。'],N('Between (2 s,5 m) and (6 s,17 m), what is the slope in m/s?','(2秒,5米)到(6秒,17米)的斜率是多少米/秒？',3,'(17−5)/(6−2)=3.','(17−5)/(6−2)=3。'),N('Observed value is 11, prediction is 8. What is observed minus predicted?','观察值11，预测值8，观察减预测是多少？',3,'11−8=3.','11−8=3。'));
D('F03.04','假设、对照与混杂',[['testable hypothesis','可检验假设'],['control group','对照组'],['confounder','混杂变量']],['A hypothesis predicts an observable difference. A control provides a comparison. A confounder affects both exposure and outcome, offering an alternative explanation for association.','假设预测可观察差异；对照提供比较；混杂变量同时影响处理与结果，给关联提供其他解释。'],['To test fertilizer, randomly assign similar plants to treated and untreated groups, give equal light and water, and compare growth. Different window positions could otherwise explain a difference.','测试肥料时，把相似植物随机分到处理与未处理组，保持光照和水分一致，比较生长。不同窗位否则可能解释差异。'],['Changing several factors together prevents identifying which caused an effect. Randomization reduces systematic allocation bias; it does not guarantee identical groups in a small trial.','同时改变多个因素会妨碍辨认原因；随机分配减轻系统分配偏差，但不保证小样本两组完全相同。'],N('A trial has 24 plants equally divided into two groups. How many per group?','24株植物均分两组，每组几株？',12,'24/2=12.','24÷2=12。'),N('Treatment growth averages 8 cm; control averages 5 cm. What is the observed difference?','处理组平均长8厘米，对照组5厘米，观察差是多少？',3,'8−5=3 cm; causality still depends on design.','8−5=3厘米；因果解释仍取决于设计。'));
D('F03.05','模型、拟合与残差',[['prediction','预测'],['residual','残差'],['overfitting','过拟合']],['A fitted model chooses parameters using data. A residual equals observation minus prediction. Systematic residual patterns suggest missing structure; small training errors alone do not establish predictive reliability.','拟合模型用数据选择参数；残差等于观察减预测。系统性残差图案提示遗漏结构，训练误差小并不能保证预测可靠。'],['For y=2x+1, x=3 predicts 7. If the observation is 8, its residual is 1 and squared residual is 1. Least squares minimizes the total squared residuals over all observations.','模型y=2x+1在x=3时预测7；观测8的残差为1，平方残差为1。最小二乘使所有平方残差的总和最小。'],['A model with enough parameters may memorize noise. Check held-out data and the physical meaning of parameters; extrapolation can fail even when interpolation is excellent.','参数太多可能记住噪声；应检查留出数据与参数的物理含义。内插优秀也不保证外推有效。'],N('For y=3x+2, what is the prediction at x=4?','y=3x+2在x=4时预测多少？',14,'3×4+2=14.','3×4+2=14。'),N('Residuals are −2,1,2. What is their squared sum?','残差为−2、1、2，平方和是多少？',9,'4+1+4=9.','4+1+4=9。'));
D('F03.06','可复现的实验记录',[['raw data','原始数据'],['provenance','来源记录'],['reproducible procedure','可复现流程']],['A laboratory record preserves date, apparatus, settings, units, raw observations, transformations, and unexpected events. Reproducibility requires enough detail for another person to repeat the analysis.','实验记录保存日期、设备、设置、单位、原始观察、处理过程和异常事件；可复现要求他人能据此重复分析。'],['Record masses 12.1,12.3,12.2 g before storing their mean 12.2 g. Keep the calculation and any calibration correction alongside them, rather than replacing the originals with rounded averages.','先记录12.1、12.3、12.2克，再保存均值12.2克；把计算与校准修正附在旁边，不要用四舍五入的平均值替换原记录。'],['An unexplained deleted outlier breaks the evidence trail. Keep exclusions with reasons, distinguish observations from interpretations, and label illustrative or simulated data explicitly.','无解释地删除离群值会破坏证据链；排除值须保留理由，观察与解释分开，模拟或示意数据须明确标注。'],N('Find the mean of 12.1,12.3,12.2 g.','12.1、12.3、12.2克的均值是多少？',12.2,'The sum 36.6 divided by three is 12.2.','36.6÷3=12.2。'),N('A record has 5 trials and excludes 1 with a documented reason. How many remain?','5次试验中有1次记录原因后排除，剩几次？',4,'Five minus one leaves four; preserve all raw records.','5−1=4，仍应保留全部原始记录。'));
F('F04','Learning is stronger when you can reconstruct an idea without seeing the explanation and then use it in a changed situation. First identify the concept, its conditions, and a representative example. Close the source and explain why each step works; reopen it to correct omissions. Keep the distinction between recognition and independent performance explicit. Schedule later attempts and mix related problem types after their individual methods are understood. A useful record captures what changed in your reasoning, rather than merely how long you studied or how familiar a page looked.','能够不看说明重建概念，并在改变的情境中使用它，才表明理解更稳固。先找出概念、适用条件和代表例子，再合上材料解释每一步的理由，最后核对遗漏。应区分看懂与独立完成。理解各方法后，安排延迟练习并混合相关题型。记录应捕捉推理发生了什么改变，而不只是学习时长或页面熟悉程度。','discrete');
D('F04.01','提取练习与自我解释',[['retrieval','提取'],['self-explanation','自我解释'],['delayed check','延迟检查']],['Retrieval means producing an answer from memory before consulting it. Self-explanation asks why a step is valid and how it connects to prior ideas.','提取是查答案之前从记忆生成答案；自我解释追问步骤为什么成立以及与旧知识如何联系。'],['After studying fraction addition, cover the example and solve 1/3+1/6. Explain that common sixths permit adding counts: 2/6+1/6=3/6=1/2.','学习分数加法后盖住例题，计算1/3+1/6，并解释通分为六分之一后才能相加：2/6+1/6=1/2。'],['Immediate recognition can feel easier than retrieval while revealing less about independent recall. Correct errors after attempting, not after repeatedly copying the answer.','立即认出答案可能比提取容易，却较少揭示独立回忆能力。应先尝试再纠错，不是反复照抄答案。'],N('Reconstruct 1/3+1/6 without the example.','不看例题重建1/3+1/6。',0.5,'2/6+1/6=3/6=1/2.','2/6+1/6=3/6=1/2。'),N('A learner independently answers 7 of 10 prompts. How many need another attempt?','10个提示独立答对7个，几个需要再练？',3,'10−7=3, while correct items still benefit from later review.','10−7=3，正确项之后也宜复习。'));
D('F04.02','例题与刻意练习',[['worked example','例题'],['faded support','逐步撤除支架'],['transfer','迁移']],['A worked example makes decisions visible. Fading support means completing increasingly larger missing portions until the whole solution can be produced independently.','例题展示决策过程；逐步撤除支架是让学习者填补越来越多步骤，直到独立完成。'],['For 3x+2=14, an example subtracts 2 then divides by 3, giving x=4. Next solve 5x+3=18 with only the first hint, then explain both operations unaided.','3x+2=14的例题先减2再除3，得x=4。随后仅给首步提示解5x+3=18，再无提示解释两步。'],['Repeating a memorized surface pattern can hide missing understanding. Change numbers, representations, and which quantity is unknown while preserving the underlying principle.','重复熟记的表面形式可能掩盖理解缺失；应改变数值、表示方式和未知量，但保留底层原理。'],N('Solve 5x+3=18.','解5x+3=18。',3,'Subtract 3 to obtain 5x=15, then divide by 5.','减3得5x=15，再除5。'),N('Solve 4x−7=13.','解4x−7=13。',5,'Add 7, then divide 20 by 4.','先加7，再将20除4。'));
D('F04.03','错题记录与复习',[['error category','错误类别'],['repair','修复'],['retest','重测']],['An error log records the original reasoning, its first invalid step, the corrected principle, and a fresh test. Categorize conceptual, algebraic, reading, and checking errors separately.','错题记录包括原推理、第一个错误步骤、修正原则和新测题；概念、计算、读题与检查错误应分开。'],['If −2x<6 was changed to x<−3, the failure is not dividing correctly: division by a negative reverses order. The repair is x>−3; test x=0 in the original inequality.','若−2x<6被改为x<−3，错误在负数除法要反向。正确为x>−3；取x=0代原式即可检验。'],['An error log is useful only if revisited with new attempts. Copying a polished solution does not show that the original misconception has changed.','错题本需通过新尝试反复检查才有用；抄写漂亮答案不能表明旧误解已改变。'],N('What boundary value solves −2x=6?','−2x=6的边界值是多少？',-3,'Divide both sides by −2.','两边除以−2。'),N('Three of 8 errors were conceptual; how many were other types?','8个错误中3个为概念错误，其他类几个？',5,'8−3=5; categories guide the repair strategy.','8−3=5；分类帮助选择修复方法。'));
D('F04.04','阅读科学文本',[['claim','断言'],['evidence','证据'],['assumption','假设']],['Read a technical paragraph by identifying what is defined, what is asserted, what supports it, and under which assumptions it holds. Translate notation into a sentence.','读技术段落时，区分定义、断言、证据及成立假设，并把符号翻译成句子。'],['The formula d=vt applies to constant speed along a path when d is distance. If speed varies, one fixed v must be an appropriate average, or the distance requires accumulation over time.','d=vt在v为恒定速率、d为路程时适用。速率变化时，v须为恰当平均值，或者需要沿时间累积路程。'],['A familiar formula can have unfamiliar assumptions. Mark undefined terms and resolve them before treating a passage as understood.','熟悉公式也可能带有陌生假设；应标记未定义术语并解决，而不是把认得符号当作理解。'],N('At constant speed 3 m/s for 7 s, what distance is traveled?','以3米/秒匀速运动7秒，路程多少米？',21,'d=vt=3×7=21 m.','d=vt=3×7=21米。'),N('A paragraph names 6 terms; 2 are unfamiliar. How many are already understood?','段落有6个术语，2个不熟悉，已理解几个？',4,'6−2=4, and the two gaps should be resolved.','6−2=4，剩下两个需补足。'));
D('F04.05','双语术语与记号',[['term equivalence','术语对应'],['notation convention','记号约定'],['meaning in context','语境意义']],['A bilingual glossary should connect definitions, not merely translate isolated words. A mathematical symbol may use different conventions across fields, so record its meaning in the current context.','双语词表要连接定义，不只是翻译孤立单词。符号在不同学科可能遵循不同约定，应记录当前语境中的意义。'],['“Function” corresponds to 函数: each permitted input has exactly one output. “Image” here means 像, the attained outputs, not a photograph. In f(2)=5, the parentheses denote function evaluation.','Function对应函数：每个允许输入有唯一输出。Image在此为像，即实际输出，而非照片。f(2)=5的括号表示函数求值。'],['Do not translate a technical term by its everyday sense without checking the definition. Consistent symbols matter more than matching a particular alphabet.','不可未经定义核对就采用日常含义翻译术语；符号一致性比使用某种字母更重要。'],N('For f(x)=2x+1, what does f(3) equal?','f(x)=2x+1时，f(3)是多少？',7,'Function evaluation gives 2×3+1=7.','函数求值得2×3+1=7。'),N('How many outputs may a function assign to one input?','函数对一个输入必须指定几个输出？',1,'Exactly one, by definition.','按定义恰为一个。'));
D('F04.06','规划与展示探究',[['research question','研究问题'],['method','方法'],['qualified conclusion','有限定的结论']],['An investigation plan states a focused question, measurable variables, a procedure, comparison criteria, and limitations. A presentation links the conclusion to evidence with enough detail to check the reasoning.','探究计划应有明确问题、可测变量、过程、比较标准和限制。展示应把结论与证据联系起来，使推理可检查。'],['To compare paper bridges, hold span and paper mass fixed, vary fold shape, and measure failure load over repeated trials. Report every trial and summarize the pattern before interpreting why it occurred.','比较纸桥时固定跨度和纸质量，改变折叠形状，多次测量破坏载荷。先报告各次试验并总结规律，再解释原因。'],['A neat presentation does not compensate for an uncontrolled comparison. State what the experiment cannot establish, especially when samples or tested conditions are narrow.','漂亮展示不能弥补缺乏控制的比较；样本或条件有限时，应说明实验无法确立哪些结论。'],N('Three designs tested four times each require how many trials?','三种设计各测四次，共几次？',12,'3×4=12 trials.','3×4=12次。'),N('Loads 8,10,12 have what mean?','载荷8、10、12的均值是多少？',10,'Their total 30 divided by three is 10.','总和30除3为10。'));
F('M01','Algebraic manipulation is useful because equality is preserved when the same reversible operation is applied to both sides. A function adds the idea that each allowed input has a unique output, so formulas must be read together with their domains. When solving, first identify forbidden inputs; next transform the expression; finally substitute candidates into the original condition. Factoring exposes zeros, completing the square exposes a quadratic vertex, and logarithms undo positive exponential relationships. A graph provides an independent qualitative check: intercepts, signs, turning points, and long-run behavior should agree with the algebra.','代数变形的依据是：等式两边施行相同可逆操作保持等价。函数还要求每个允许输入有唯一输出，因此公式必须连同定义域理解。解题先排除非法输入，再变形，最后代回原条件检验。分解因式揭示零点，配方揭示二次函数顶点，对数还原正的指数关系。图像提供独立的定性检查：截距、符号、转折和远处趋势都应与代数结果一致。');
D('M01.01','表达式、方程与不等式',[['solution set','解集'],['factoring','因式分解'],['order reversal','不等号反向']],['An equation asks where two expressions agree. An inequality asks where their order holds. Multiplication or division by a negative number reverses order.','方程求两个表达式相等的位置，不等式求大小关系成立的位置。乘除负数须反向。'],['Solve 2(x−1)≤6: expand or divide by 2 to get x−1≤3, then x≤4. The endpoint is included because equality was allowed.','解2(x−1)≤6，两边除2得x−1≤3，再得x≤4；允许等号，所以端点包含。'],['Squaring can add solutions and division can lose them. Record restrictions and test candidates in the original statement.','平方可能增加解，除法可能丢失解；要记录限制并代回检验。'],N('Solve 3x+4=19.','解3x+4=19。',5,'Subtract 4 then divide 15 by 3.','减4后15除3。'),N('What is the upper endpoint of 2x−3≤7?','2x−3≤7的上端点是多少？',5,'2x≤10 gives x≤5.','2x≤10得到x≤5。'));
D('M01.02','一次与二次函数',[['slope','斜率'],['vertex','顶点'],['discriminant','判别式']],['A linear function mx+b has constant rate m. A quadratic ax²+bx+c with a≠0 has vertex x=−b/(2a); b²−4ac determines its number of real roots.','一次函数mx+b的变化率恒为m。二次函数a≠0时顶点横坐标为−b/(2a)，判别式b²−4ac决定实根个数。'],['Rewrite x²−6x+5 as (x−3)²−4. Its minimum is −4 at x=3, and factoring (x−1)(x−5) gives roots 1 and 5.','x²−6x+5配方为(x−3)²−4，最小值−4在x=3取得；因式分解得根1与5。'],['The graph opens downward when a<0, so the vertex is then a maximum. A zero discriminant means one distinct repeated root.','a<0时开口向下，顶点对应最大值；判别式为零表示一个相异的重根。'],N('Find the vertex x-coordinate of x²−8x+3.','x²−8x+3的顶点横坐标是多少？',4,'−b/(2a)=8/2=4.','−b/(2a)=8/2=4。'),N('What is the slope of 5−2x?','5−2x的斜率是多少？',-2,'The coefficient of x is the slope.','x的系数就是斜率。'));
D('M01.03','多项式与有理函数',[['polynomial degree','多项式次数'],['factor theorem','因式定理'],['pole and hole','极点与空点']],['A polynomial uses nonnegative integer powers of its variable. A rational function is a quotient of polynomials where the denominator is nonzero. A factor x−r corresponds to a root r.','多项式使用变量的非负整数次幂；有理函数是多项式之比，分母不得为零。因子x−r对应根r。'],['For (x²−4)/(x−2), factoring gives x+2 only when x≠2. The graph is a line with a missing point at (2,4), not a function defined everywhere.','(x²−4)/(x−2)仅在x≠2时化为x+2；图像是在(2,4)缺一个点的直线，并非处处有定义。'],['Cancel factors, not summands. A simplified formula can hide excluded inputs; retain the original domain.','只能约去因子，不能约去加项；简化公式可能隐藏被排除输入，必须保留原定义域。'],N('Evaluate (x²−9)/(x−3) at x=5.','x=5时，(x²−9)/(x−3)是多少？',8,'Factor to x+3, allowed at 5.','分解约去得x+3，5是合法输入。'),N('What is the degree of 2x⁴−x+7?','2x⁴−x+7的次数是多少？',4,'The largest nonzero exponent is 4.','非零项最高指数为4。'));
D('M01.04','指数与对数函数',[['exponential growth','指数增长'],['logarithm','对数'],['change of base','换底']],['For a>0 and a≠1, log_a y is the exponent x satisfying a^x=y, requiring y>0. Exponential change multiplies by a fixed factor over equal input intervals.','a>0且a≠1时，log_a y是满足a^x=y的指数x，要求y>0。指数变化在等长输入区间乘固定倍数。'],['Starting with 80 cells and doubling three times gives 80×2³=640. To find how many doublings multiply a population by 8, solve 2^t=8, obtaining t=3.','80个细胞倍增三次为80×2³=640；要知道增长8倍需几次倍增，解2^t=8得t=3。'],['log(x+y) does not equal log x+log y. The product rule log(xy)=log x+log y requires positive real arguments.','log(x+y)不等于log x+log y；实数乘积法则要求真数为正。'],N('What is log₂32?','log₂32是多少？',5,'2⁵=32.','2⁵=32。'),N('100 grows by factor 1.1 twice. What is the result?','100连续两次乘1.1，结果多少？',121,'100×1.1²=121.','100×1.1²=121。'));
D('M01.05','复合与反函数',[['composition','复合'],['inverse','反函数'],['domain restriction','定义域限制']],['Composition (f∘g)(x)=f(g(x)) applies g first. An inverse reverses a bijection; its domain is the original image. Restricting a function can make it invertible.','复合(f∘g)(x)=f(g(x))先作用g。反函数逆转双射，其定义域是原像集；限制定义域可使函数可逆。'],['If f(x)=2x+3, solve y=2x+3 for x: x=(y−3)/2. Hence f⁻¹(y)=(y−3)/2 and f⁻¹(f(4))=4.','f(x)=2x+3时，由y=2x+3解出x=(y−3)/2，故反函数为(y−3)/2，复合回去恢复4。'],['Composition is generally not commutative. The symbol f⁻¹ denotes an inverse function, not the reciprocal 1/f.','复合通常不可交换；f⁻¹表示反函数，不是倒数1/f。'],N('f(x)=x+1,g(x)=3x. Find f(g(2)).','f(x)=x+1，g(x)=3x，求f(g(2))。',7,'g(2)=6, then f(6)=7.','先得g(2)=6，再得f(6)=7。'),N('For f(x)=4x−5, find f⁻¹(7).','f(x)=4x−5，求f⁻¹(7)。',3,'Solve 4x−5=7 to obtain x=3.','解4x−5=7得3。'));
D('M01.06','参数与函数建模',[['parameter','参数'],['calibration','参数确定'],['model domain','模型适用域']],['A variable describes changing input; a parameter specifies one member of a family of models. Parameters must be estimated or stated, with units and permitted ranges.','变量描述变化输入，参数指定模型族中的一个模型。参数必须给出或估计，并说明单位与范围。'],['A taxi model C(d)=b+rd uses initial fare b and per-distance rate r. Costs 11 at d=2 and 20 at d=5 imply 3r=9, so r=3 and b=5.','出租车模型C(d)=b+rd中，b是起步费，r是单位路程费。d=2价11，d=5价20，故3r=9，r=3，b=5。'],['Fitting two observations exactly does not prove linearity outside that range. Minimum fares or tiered pricing require a piecewise model.','恰好拟合两个观察不能证明范围外也线性；最低收费或阶梯价格需要分段模型。'],N('For C(d)=5+3d, find C(4).','C(d)=5+3d时，C(4)是多少？',17,'5+3×4=17.','5+3×4=17。'),N('A line through (1,4),(3,10) has what slope?','过(1,4)、(3,10)的直线斜率多少？',3,'(10−4)/(3−1)=3.','(10−4)/(3−1)=3。'));
F('M02','Trigonometry translates between angles and coordinate ratios. Draw a unit circle or a labeled triangle before choosing a formula. On the circle, an angle determines a point whose horizontal and vertical coordinates are cosine and sine, so signs come from the quadrant. Similar triangles explain why ratios depend on angle rather than triangle size. Radians measure arc length divided by radius and are the natural unit for calculus. Identities hold wherever both sides are defined; equations ask only which angles make a particular equality true. Periodicity requires considering all permitted rotations, not just one calculator output.','三角学把角与坐标比联系起来。选择公式前先画单位圆或标注三角形。单位圆上点的横纵坐标分别是余弦与正弦，符号由象限决定。相似三角形解释比值为何依角而不依大小。弧度等于弧长除半径，是微积分的自然角单位。恒等式在两边有定义处成立；方程只求特定相等关系成立的角。周期性要求考虑允许的全部转数，不能只取计算器的一个输出。');
D('M02.01','角、弧度与单位圆',[['radian','弧度'],['arc length','弧长'],['oriented angle','有向角']],['An angle θ in radians equals arc length s divided by radius r. One full turn is 2π radians, corresponding to 360 degrees.','弧度角θ等于弧长s除半径r。一周为2π弧度，也就是360度。'],['On radius 3, a 2-radian angle cuts arc length s=rθ=6. A half-turn has angle π, so its arc length is 3π.','半径3上，2弧度截得弧长s=rθ=6；半周角为π，弧长3π。'],['The formula s=rθ requires radians. Degrees cannot be inserted without converting by π/180.','s=rθ要求弧度，角度值须先乘π/180换算。'],N('Radius is 5 and angle 0.4 radians. Find arc length.','半径5，角0.4弧度，求弧长。',2,'5×0.4=2.','5×0.4=2。'),N('How many degrees are in a quarter-turn?','四分之一周有多少度？',90,'360/4=90.','360÷4=90。'));
D('M02.02','正弦、余弦与正切',[['unit-circle coordinates','单位圆坐标'],['opposite and adjacent','对边与邻边'],['tangent ratio','正切比']],['On a unit circle, (cos θ,sin θ) locates the point. Tangent is sin θ/cos θ when cosine is nonzero. In a right triangle these become side-length ratios.','单位圆点为(cos θ,sin θ)；余弦非零时tan θ=sin θ/cos θ。直角三角形中它们成为边长之比。'],['For a right triangle with legs 3 and 4 and hypotenuse 5, the angle opposite 3 has sine 3/5, cosine 4/5, and tangent 3/4.','两直角边3、4，斜边5时，3所对角的正弦为3/5，余弦4/5，正切3/4。'],['The hypotenuse is opposite the right angle. Sine and cosine remain meaningful outside acute triangles through the circle definition.','斜边正对直角；单位圆定义使正弦余弦也适用于非锐角。'],N('Find sine of the angle opposite side 5 in a 5-12-13 triangle.','5-12-13直角三角形中，5所对角的正弦多少？',5/13,'Opposite divided by hypotenuse gives 5/13.','对边除斜边为5/13。'),N('What is cos 0?','cos 0是多少？',1,'The unit-circle point is (1,0).','单位圆上对应点为(1,0)。'));
D('M02.03','恒等式与变换',[['Pythagorean identity','平方和恒等式'],['addition formula','和角公式'],['phase shift','相位平移']],['The unit circle gives sin²θ+cos²θ=1. Addition formulas express trigonometric values of a sum; for example sin(a+b)=sin a cos b+cos a sin b.','单位圆给出sin²θ+cos²θ=1；和角公式如sin(a+b)=sin a cos b+cos a sin b。'],['If an acute angle has sine 3/5, cosine is the positive square root of 1−9/25, namely 4/5. Its double-angle sine is 2(3/5)(4/5)=24/25.','锐角正弦3/5时，余弦取√(1−9/25)的正值4/5，二倍角正弦为24/25。'],['Taking a square root loses sign information; the quadrant selects the sign. In general sin(a+b) is not sin a+sin b.','开平方丢失符号信息，须由象限选择；一般sin(a+b)不等于sin a+sin b。'],N('For acute θ with sin θ=0.6, find cos θ.','锐角θ满足sin θ=0.6，求cos θ。',0.8,'√(1−0.36)=0.8.','√(1−0.36)=0.8。'),N('What is sin²θ+cos²θ?','sin²θ+cos²θ是多少？',1,'It is the unit-circle equation.','这是单位圆方程。'));
D('M02.04','三角方程',[['principal solution','主值解'],['periodic family','周期解族'],['restricted interval','限定区间']],['Solving a trigonometric equation requires a reference angle, quadrant signs, and the requested interval. Periodicity usually creates infinitely many real solutions.','解三角方程需要参考角、象限符号和指定区间；周期性通常产生无限多个实数解。'],['sin θ=1/2 on [0,2π) has θ=π/6 and 5π/6. On the entire real line, add 2kπ to each family for any integer k.','sin θ=1/2在[0,2π)上解为π/6和5π/6；全实数范围内两族各加2kπ，k为任意整数。'],['Inverse sine returns only its principal value. Dividing by a trigonometric factor can discard zeros of that factor.','反正弦只返回主值；除以三角因子会丢掉该因子为零的情况。'],N('How many solutions does sin θ=0 have on [0,2π)?','sin θ=0在[0,2π)中有几个解？',2,'The solutions are 0 and π; 2π is excluded.','解为0与π，2π不包含。'),N('How many solutions does cos θ=1 have on [0,2π)?','cos θ=1在[0,2π)中有几个解？',1,'Only θ=0 lies in the interval.','只有θ=0在区间内。'));
D('M02.05','三角形定理与应用',[['sine law','正弦定理'],['cosine law','余弦定理'],['included angle','夹角']],['For opposite sides and angles, a/sin A=b/sin B=c/sin C. The cosine law c²=a²+b²−2ab cos C uses the included angle C.','对应边角满足a/sin A=b/sin B=c/sin C；余弦定理c²=a²+b²−2ab cos C中C为夹角。'],['Sides 3 and 4 enclose a right angle, so c²=9+16−0=25 and c=5. With included angle 60 degrees, c² instead equals 25−12=13.','边3、4夹直角时，c²=9+16=25，c=5；夹60度时c²=25−12=13。'],['Two sides and a nonincluded angle may specify zero, one, or two triangles. A calculator principal angle can miss the second possibility.','两边与非夹角可能确定零、一个或两个三角形，计算器主值角可能漏掉第二种。'],N('Find the third side for perpendicular sides 6 and 8.','两垂直边长6与8，第三边多少？',10,'√(36+64)=10.','√(36+64)=10。'),N('Two sides 5 and 5 include 60 degrees. Find the third side.','两边5、5夹60度，第三边多少？',5,'c²=25+25−50×1/2=25.','c²=25+25−50×1/2=25。'));
D('M02.06','振荡与反三角函数',[['amplitude','振幅'],['period','周期'],['inverse range','反函数值域']],['In y=A sin(ωt+φ)+D, |A| is amplitude, 2π/|ω| is period for ω≠0, and D is the midline. Inverse trigonometric functions restrict domains to obtain uniqueness.','y=A sin(ωt+φ)+D中，|A|是振幅，ω≠0时周期为2π/|ω|，D是中线。反三角函数通过限制原定义域获得唯一性。'],['For y=3sin(2t)+1, values range from −2 to 4 and one cycle lasts π. The displacement 1 shifts the center without changing the amplitude.','y=3sin(2t)+1的范围为−2到4，周期π；加1只移动中心，不改变振幅。'],['Frequency and angular frequency differ by 2π. arcsin(sin θ)=θ only when θ lies in the principal interval [−π/2,π/2].','频率与角频率差2π倍；arcsin(sin θ)=θ只在主值区间[−π/2,π/2]成立。'],N('Find the maximum of 4sin t−2.','4sin t−2的最大值多少？',2,'4×1−2=2.','4×1−2=2。'),N('Find the amplitude of −7cos(3t)+5.','−7cos(3t)+5的振幅多少？',7,'Amplitude is the absolute coefficient, 7.','振幅取系数绝对值7。'));
F('M03','Euclidean geometry reasons from explicit assumptions about points, lines, distances, and angles. Congruence preserves lengths and angles; similarity preserves angles and ratios of corresponding lengths. Mark which statements come from the problem and which require proof. Auxiliary lines can create triangles with known angle or side relations, but they must be defined precisely. Area can be calculated in different ways to expose ratios. A diagram helps choose a strategy, yet apparent perpendicularity or equal length is not evidence unless justified. Degenerate configurations, such as collinear triangle vertices, must be excluded when a theorem requires a genuine triangle.','欧氏几何从点、线、距离与角的明确假设出发。全等保持长度与角，相似保持角与对应长度比。应区分题设与待证结论；辅助线可创造已知边角关系，但要精确定义。用不同方式计算面积可揭示比值。图形帮助选择策略，却不能仅凭外观看出垂直或等长。定理要求真正三角形时，应排除顶点共线等退化情形。');
D('M03.01','公理、全等与相似',[['SSS congruence','边边边全等'],['AA similarity','角角相似'],['scale factor','相似比']],['Three corresponding equal sides imply triangle congruence. Two corresponding equal angles imply similarity; lengths scale by k and areas by k².','三组对应边相等推出三角形全等；两组角相等推出相似，长度乘k，面积乘k²。'],['Triangles with sides 3,4,5 and 6,8,10 have scale factor 2. Their perimeters have ratio 2 and their areas ratio 4.','边长3、4、5与6、8、10的三角形相似比2，周长比2，面积比4。'],['Equal angles do not imply equal sizes. Match corresponding vertices consistently before forming ratios.','等角不代表大小相等；列比值前要正确匹配顶点。'],N('A similar triangle scales length by 3. What is its area factor?','相似长度扩大3倍，面积扩大几倍？',9,'Area scales as 3²=9.','面积按3²=9倍变化。'),N('A side 7 scales by 2.5. Find its corresponding length.','边长7按2.5倍放大，对应边多少？',17.5,'7×2.5=17.5.','7×2.5=17.5。'));
D('M03.02','三角形与特殊中心',[['centroid','重心'],['circumcenter','外心'],['incenter','内心']],['Medians meet at the centroid, perpendicular bisectors at the circumcenter, and angle bisectors at the incenter. Each center is defined by a different geometric condition.','中线交于重心，垂直平分线交于外心，角平分线交于内心；各中心对应不同几何条件。'],['The centroid divides every median in a 2:1 ratio measured from the vertex. A median of length 12 therefore has vertex-to-centroid length 8 and remaining length 4.','重心从顶点起按2:1分中线；中线长12时，顶点到重心长8，另一段长4。'],['The circumcenter can lie outside an obtuse triangle. The incenter is equidistant from sides, not generally from vertices.','钝角三角形外心可在外部；内心到边等距，不是通常到顶点等距。'],N('A median is 15. Find the vertex-to-centroid distance.','中线长15，顶点到重心多少？',10,'Take 2/3 of 15.','取15的2/3。'),N('An equilateral triangle has angle sum 180 degrees. Find each angle.','等边三角形角和180度，每角多少度？',60,'Equal angles divide 180 into three equal parts.','三等角均分180。'));
D('M03.03','圆与圆内接四边形',[['inscribed angle','圆周角'],['cyclic quadrilateral','圆内接四边形'],['power of a point','点的幂']],['An inscribed angle is half the central angle subtending the same arc. Opposite angles of a cyclic quadrilateral sum to 180 degrees. Intersecting chord segment products are equal.','同弧圆周角为圆心角一半；圆内接四边形对角和180度；相交弦分段乘积相等。'],['Chords through an interior point have segment lengths 3,8 and 4,x. Power of a point gives 3×8=4x, hence x=6.','两弦在圆内交，分段为3、8与4、x。由点的幂，3×8=4x，得x=6。'],['The angles must subtend the same arc. For tangent-secant power, use the whole secant length, not only its interior segment.','必须对应同一段弧；切割线定理使用整条割线段，而不只是圆内部分。'],N('A cyclic quadrilateral has one angle 73 degrees. Find its opposite angle.','圆内接四边形一个角73度，对角多少度？',107,'180−73=107.','180−73=107。'),N('A central angle is 100 degrees. Find an inscribed angle on the same arc.','同弧圆心角100度，圆周角多少度？',50,'The inscribed angle is half.','圆周角为一半。'));
D('M03.04','面积、比与几何不等式',[['shared altitude','同高'],['area ratio','面积比'],['triangle inequality','三角不等式']],['Triangle area is half base times perpendicular height. Triangles sharing an altitude have areas proportional to bases. Genuine triangle sides satisfy each side less than the sum of the other two.','三角形面积为底乘垂直高的一半；同高三角形面积比等于底比。非退化三角形任一边小于另外两边和。'],['Split a base into lengths 2 and 3 and join the division point to the opposite vertex. The two areas have ratio 2:3 because their heights agree.','把底边分为2与3并连到对顶点，两三角形同高，面积比为2:3。'],['A slanted side is not the height unless perpendicular to the base. Equality in a triangle inequality gives a degenerate straight configuration.','斜边不是高，除非垂直底边；三角不等式取等会退化成直线。'],N('Find the area of base 8 and height 5.','底8、高5的三角形面积多少？',20,'8×5/2=20.','8×5÷2=20。'),N('A total area 30 is divided in ratio 2:3. Find the smaller area.','总面积30按2:3分，小块面积多少？',12,'Two of five equal shares gives 30×2/5=12.','五份取二，30×2/5=12。'));
D('M03.05','变换与作图',[['reflection','反射'],['rotation','旋转'],['perpendicular bisector','垂直平分线']],['Translations, rotations, and reflections preserve distances. A compass-and-straightedge construction must use permitted operations and justify why the resulting point meets the requested conditions.','平移、旋转、反射保持距离。尺规作图须使用允许操作，并解释构造点为什么满足条件。'],['Equal-radius circles centered at A and B meet at P,Q. Both intersection points are equidistant from A and B, so line PQ is their perpendicular bisector.','以A、B为心作等半径圆交于P、Q，两交点到A、B等距，因此PQ为AB的垂直平分线。'],['A dilation changes distances by its scale factor, so it is generally not an isometry. A drawing alone does not establish constructibility.','位似按比例改变距离，一般不保距；画得出来并不能证明可尺规作出。'],N('Reflect (3,−2) across the y-axis. What is the new x-coordinate?','(3,−2)关于y轴反射，新x坐标多少？',-3,'Reflection changes x to −x.','反射把x变为−x。'),N('A length 4 is dilated by 3. Find the image length.','长4按3倍位似，像长多少？',12,'4×3=12.','4×3=12。'));
D('M03.06','立体几何与空间推理',[['cross-section','截面'],['surface area','表面积'],['volume scaling','体积缩放']],['A solid can be studied through cross-sections and projections. Similar solids scale area by k² and volume by k³. Perpendicularity must be checked in space, not inferred from a flat sketch.','立体可通过截面和投影研究；相似立体面积按k²、体积按k³变化。空间垂直不能只从平面草图判断。'],['A cuboid with edges 2,3,6 has volume 36 and space diagonal √(4+9+36)=7. The diagonal formula applies the Pythagorean theorem twice.','边长2、3、6的长方体体积36，体对角线√(4+9+36)=7，来自两次勾股定理。'],['Volume and surface area use different powers and units. Skew lines are neither intersecting nor parallel, a possibility absent in one plane.','体积与表面积使用不同幂次和单位；异面直线既不相交也不平行，是平面中没有的情况。'],N('A cube side is 4. Find its volume.','边长4的立方体体积多少？',64,'4³=64.','4³=64。'),N('All lengths double. What is the volume factor?','全部长度加倍，体积扩大几倍？',8,'2³=8.','2³=8。'));
F('M04','Coordinates convert geometric conditions into equations. Choose axes and an origin that simplify the objects, while remembering that distances and angles describe geometry rather than the coordinate labels themselves. A vector records displacement, so translating its starting point does not change it. Dot products turn angle and perpendicularity questions into algebra; cross products in three dimensions encode oriented area. Solve intersections by requiring the same point to satisfy both descriptions. After an algebraic calculation, reconstruct the geometry: verify dimensions, directions, and whether the calculated point lies on the intended line, segment, ray, or curve.','坐标把几何条件化为方程。应选择使对象简单的轴与原点，同时记住距离和角描述几何本身，而不依坐标标签。向量记录位移，平移起点不改变向量。点积把角与垂直问题化为代数，三维叉积编码有向面积。求交点就是让同一点同时满足两种描述。计算后须还原几何，检查量纲、方向以及点是否位于指定直线、线段、射线或曲线上。');
D('M04.01','直角坐标与距离',[['ordered coordinates','有序坐标'],['distance formula','距离公式'],['midpoint','中点']],['Coordinates are signed distances along perpendicular axes. The distance between (x₁,y₁),(x₂,y₂) is √((x₂−x₁)²+(y₂−y₁)²). The midpoint averages coordinates.','坐标为沿垂直轴的有向位置；两点距离为坐标差平方和开方，中点取各坐标平均。'],['From (−1,2) to (2,6), displacement is (3,4), giving distance 5 and midpoint (0.5,4).','从(−1,2)到(2,6)，位移为(3,4)，距离5，中点(0.5,4)。'],['Coordinates depend on the chosen frame. Subtract endpoints in a consistent order when direction matters.','坐标依参照系而定；涉及方向时，端点相减顺序须一致。'],N('Find the distance from (0,0) to (8,15).','原点到(8,15)距离多少？',17,'√(64+225)=17.','√(64+225)=17。'),N('Find the midpoint x-coordinate of (2,1),(8,9).','(2,1)、(8,9)中点的x坐标多少？',5,'(2+8)/2=5.','(2+8)/2=5。'));
D('M04.02','直线、平面与交点',[['normal vector','法向量'],['line equation','直线方程'],['simultaneous equations','联立方程']],['A line ax+by=c has normal (a,b). In space, ax+by+cz=d defines a plane when the normal is nonzero. Intersections satisfy all relevant equations.','直线ax+by=c的法向量是(a,b)；空间中非零法向量下ax+by+cz=d定义平面。交点满足全部相关方程。'],['Intersect y=2x+1 with y=−x+7: equate right sides to obtain 3x=6, so x=2 and y=5.','联立y=2x+1与y=−x+7，得3x=6，因此x=2、y=5。'],['Vertical lines have no finite slope but have a valid equation x=c. Parallel distinct lines have no intersection.','竖直线没有有限斜率，但可写x=c；相异平行线没有交点。'],N('Find x at the intersection y=x+2 and y=3x.','y=x+2与y=3x交点的x是多少？',1,'x+2=3x gives x=1.','x+2=3x得1。'),N('For plane x+2y+z=8 with x=1,y=2, find z.','平面x+2y+z=8中x=1、y=2，求z。',3,'z=8−1−4=3.','z=8−1−4=3。'));
D('M04.03','向量加法与数量积',[['linear combination','线性组合'],['dot product','点积'],['orthogonality','正交']],['Vectors add componentwise. The dot product u·v equals the sum of coordinate products and also |u||v|cos θ. Nonzero perpendicular vectors have zero dot product.','向量逐坐标相加；点积为坐标乘积之和，也等于|u||v|cos θ。非零垂直向量点积为零。'],['For u=(2,1),v=(−1,2), u·v=−2+2=0, so they are perpendicular. Their sum is (1,3), which represents consecutive displacements.','u=(2,1)、v=(−1,2)时点积−2+2=0，因此垂直；和为(1,3)，表示连续位移。'],['The dot product is a scalar, not a vector. The zero vector has zero dot product with all vectors but has no defined direction angle.','点积是标量而非向量；零向量与所有向量点积为零，但没有确定方向角。'],N('Compute (3,4)·(1,2).','计算(3,4)·(1,2)。',11,'3×1+4×2=11.','3×1+4×2=11。'),N('Find the length of (6,8).','向量(6,8)的长度多少？',10,'√(36+64)=10.','√(36+64)=10。'));
D('M04.04','圆锥曲线',[['ellipse','椭圆'],['hyperbola','双曲线'],['parabola','抛物线']],['Conics are plane sections of a cone. Standard equations reveal their symmetry: an ellipse has x²/a²+y²/b²=1, while a hyperbola changes one plus sign to minus.','圆锥曲线来自平面截圆锥；标准方程揭示对称性。椭圆为x²/a²+y²/b²=1，双曲线把一个加号改为减号。'],['For x²/25+y²/9=1, the semiaxes are 5 and 3. At x=0, y=±3; at y=0, x=±5.','x²/25+y²/9=1的半轴为5与3；x=0时y=±3，y=0时x=±5。'],['Denominators are squared semiaxes, not semiaxes themselves. A translated conic requires completing squares before identifying its center.','分母是半轴的平方；平移后的曲线应先配方再找中心。'],N('Find the horizontal semiaxis of x²/16+y²/4=1.','x²/16+y²/4=1的水平半轴多少？',4,'√16=4.','√16=4。'),N('For y=x²/4, find y at x=6.','y=x²/4中x=6，y多少？',9,'36/4=9.','36/4=9。'));
D('M04.05','参数与极坐标表示',[['parameter','参数'],['polar radius','极径'],['coordinate conversion','坐标转换']],['A parametric curve gives coordinates as functions of t. Polar coordinates use x=r cos θ,y=r sin θ, allowing a point to have multiple angle representations.','参数曲线把坐标写成t的函数；极坐标用x=r cos θ、y=r sin θ，同一点可有多个角表示。'],['x=2t+1,y=3t−2 gives (5,4) at t=2. Eliminating t gives y=1.5x−3.5, but the permitted t interval still controls which part of the line is traced.','x=2t+1、y=3t−2在t=2时为(5,4)；消参得y=1.5x−3.5，但t的范围仍决定轨迹是哪一段。'],['Eliminating a parameter can lose direction and domain information. Polar angle alone does not determine distance from the origin.','消参可能丢失方向和范围信息；只有极角不能确定距原点多远。'],N('For x=3t−1, find x at t=4.','x=3t−1，t=4时x多少？',11,'3×4−1=11.','3×4−1=11。'),N('Polar r=5,θ=0. Find x.','极坐标r=5、θ=0，x多少？',5,'x=5cos0=5.','x=5cos0=5。'));
D('M04.06','三维向量与叉积',[['cross product','叉积'],['oriented area','有向面积'],['scalar triple product','数量三重积']],['In three dimensions u×v is perpendicular to both vectors and has magnitude |u||v|sin θ. Its orientation follows the right-hand rule. A scalar triple product gives signed volume.','三维叉积u×v垂直两向量，大小为|u||v|sin θ，方向遵循右手定则；数量三重积给有向体积。'],['For u=(2,0,0),v=(0,3,0), u×v=(0,0,6). The parallelogram area is 6, while the triangle formed by those sides has area 3.','u=(2,0,0)、v=(0,3,0)的叉积为(0,0,6)；平行四边形面积6，对应三角形面积3。'],['Swapping operands reverses the cross product. Parallel vectors yield zero, so zero cannot define a unique plane normal.','交换顺序使叉积反向；平行向量叉积为零，不能用它确定唯一法向量。'],N('Find |(4,0,0)×(0,5,0)|.','求|(4,0,0)×(0,5,0)|。',20,'Perpendicular lengths multiply to 20.','垂直边长相乘为20。'),N('Find volume of the parallelepiped along axes with lengths 2,3,4.','沿三轴边长2、3、4的平行六面体体积多少？',24,'The scalar triple product is 2×3×4=24.','数量三重积为2×3×4=24。'));
function R(id,zh,te,tz,de,dz,ee,ez,pe,pz,q1,q2){const terms=te.split(';').map((s,i)=>[s,tz.split(';')[i]]);D(id,zh,terms,[de,dz],[ee,ez],[pe,pz],N(q1[0],q1[1],q1[2],q1[3]||ee,q1[4]||ez),N(q2[0],q2[1],q2[2],q2[3]||ee,q2[4]||ez));}
F('M05','Complex numbers extend the real numbers by introducing i with i²=−1. Every complex number has real and imaginary coordinates, so an algebraic expression can also describe a point or displacement in a plane. Addition combines coordinates; multiplication combines scale and angle. Polynomial identities remain algebraic statements valid at every permitted input, while root equations identify special inputs. Division, factoring, and coefficient comparison provide complementary views of the same polynomial. Keep multiplicity separate from the count of distinct roots, and distinguish a polynomial from a rational expression with excluded denominator zeros. Geometric interpretations must agree with the corresponding algebra.','复数引入满足i²=−1的i，把实数扩展为平面坐标。加法逐坐标结合，乘法同时结合缩放和转角。多项式恒等式对所有允许输入成立，根方程寻找特殊输入。除法、分解和比较系数给出互补视角。须区分重数与相异根个数，也须区分多项式与排除分母零点的有理式；几何解释应与代数一致。');
R('M05.01','复数运算与平面','real part;conjugate;modulus','实部;共轭;模','Write z=a+bi; its conjugate is a−bi and |z|=√(a²+b²).','写z=a+bi，共轭为a−bi，模为√(a²+b²)。','(2+3i)(1−i)=5+i by expansion and i²=−1. Also (3+4i)(3−4i)=25.','展开并用i²=−1，得(2+3i)(1−i)=5+i；(3+4i)(3−4i)=25。','Complex numbers have no order compatible with all ordered-field rules.','复数不能配备满足全部有序域规则的大小顺序。',['Find the real part of (2+3i)(1−i).','求(2+3i)(1−i)实部。',5],['Find |3+4i|.','求|3+4i|。',5,'The modulus is √25=5.','模为√25=5。']);
R('M05.02','极形式与单位根','argument;De Moivre;roots of unity','辐角;棣莫弗公式;单位根','Polar form z=r(cosθ+i sinθ) turns multiplication into multiplying radii and adding angles.','极形式z=r(cosθ+i sinθ)使乘法变成模相乘、角相加。','The fourth roots of 1 are 1,i,−1,−i, separated by π/2. Squaring i gives −1 and i⁴=1.','1的四次单位根为1、i、−1、−i，角相差π/2；i²=−1，i⁴=1。','Arguments differ by multiples of 2π; root extraction must include all angle branches.','辐角相差2π整数倍；开根必须包含全部角分支。',['How many fourth roots of 1 exist?','1有几个四次方根？',4],['What is i⁴?','i⁴是多少？',1]);
R('M05.03','多项式除法与分解','division algorithm;remainder;factor theorem','除法算法;余数;因式定理','For nonzero D, P=DQ+R with degree R below degree D. Dividing by x−a leaves remainder P(a).','D非零时P=DQ+R，余式次数小于D；除x−a的余数为P(a)。','x²−3x+2=(x−1)(x−2), so dividing by x−1 leaves zero remainder and quotient x−2.','x²−3x+2=(x−1)(x−2)，除x−1余数零，商为x−2。','The coefficient field matters: a polynomial may factor over complex but not real numbers.','系数域很重要：多项式可能在复数域可分解而实数域不行。',['Find the remainder of x²−3x+2 divided by x−1.','x²−3x+2除x−1余数多少？',0],['Evaluate that polynomial at x=3.','该多项式在x=3的值多少？',2,'9−9+2=2.','9−9+2=2。']);
R('M05.04','韦达关系与根结构','root sum;root product;multiplicity','根和;根积;重数','For ax²+bx+c, roots counted with multiplicity have sum −b/a and product c/a.','ax²+bx+c的根按重数计，其和为−b/a，积为c/a。','x²−7x+12=(x−3)(x−4): the roots sum to 7 and multiply to 12, matching coefficients.','x²−7x+12=(x−3)(x−4)，根和7、根积12，与系数一致。','A repeated root counts repeatedly in coefficient relations.','系数关系中重根须按重数重复计入。',['Find the sum of roots of x²−7x+12.','x²−7x+12的根和多少？',7],['Find their product.','根积多少？',12]);
R('M05.05','插值与多项式恒等式','interpolation;distinct nodes;root bound','插值;互异节点;根数界','A polynomial of degree at most n is uniquely determined by n+1 distinct input-value pairs.','次数至多n的多项式由n+1个互异输入上的值唯一确定。','The line through (0,1),(2,5) is P(x)=2x+1. If two degree-one polynomials agree at both nodes, their difference has two roots and must vanish.','过(0,1)、(2,5)的直线为2x+1；两个一次多项式若两点相同，其差有两根，必恒为零。','Repeated input nodes do not supply independent value conditions. High-degree interpolation may oscillate.','重复节点不提供独立值条件；高次插值可能振荡。',['For that interpolating line, find P(3).','该插值直线的P(3)是多少？',7,'2×3+1=7.','2×3+1=7。'],['How many distinct values determine a polynomial of degree at most 3?','至多三次多项式需几个互异节点值唯一确定？',4,'n+1=4.','n+1=4。']);
R('M05.06','复数几何','rotation;distance;perpendicularity','旋转;距离;垂直','Multiplication by a unit complex number rotates the plane. Distance between z,w is |z−w|.','乘单位复数对应平面旋转，z与w间距离为|z−w|。','Multiplying 3+4i by i gives −4+3i: a quarter-turn counterclockwise. Its modulus remains 5 because the multiplier has modulus 1.','(3+4i)i=−4+3i，是逆时针四分之一转；乘数模为1，所以模仍为5。','Translation requires addition, not multiplication; a zero multiplier collapses all points.','平移用加法不是乘法；乘零把所有点压到一点。',['After multiplying 3+4i by i, find the real coordinate.','3+4i乘i后的实坐标多少？',-4],['What is its distance from the origin?','它离原点多远？',5]);
F('M06','A sequence is a function whose inputs are integer indices. An explicit formula gives a term directly, while a recurrence relates it to earlier terms and therefore needs initial values. To justify a proposed formula, check both the initial conditions and the recurrence; matching the first few terms alone is insufficient. Summation often becomes simpler by pairing terms, subtracting shifted copies, or arranging cancellation. Generating functions encode an entire sequence as coefficients of a formal power series. Growth comparisons concern eventual behavior, so finite early terms and multiplicative constants must be distinguished from the asymptotic scale.','数列是以整数下标为输入的函数。通项直接给出项，递推联系之前各项，因此需要初值。验证公式须同时检查初值与递推，前几项吻合还不够。配对、移位相减和抵消能简化求和。生成函数把整个数列编码为形式幂级数系数。增长比较研究最终行为，须区分有限前项、常数倍与渐近尺度。');
R('M06.01','等差与等比数列','common difference;common ratio;finite sum','公差;公比;有限和','An arithmetic sequence adds fixed d; a geometric sequence multiplies fixed r. Their nth terms are a₁+(n−1)d and a₁r^(n−1).','等差每次加d，等比每次乘r；第n项分别为a₁+(n−1)d、a₁r^(n−1)。','Starting at 3 with difference 4 gives 3,7,11,15. Starting at 2 with ratio 3 gives 2,6,18,54.','首项3公差4得到3、7、11、15；首项2公比3得到2、6、18、54。','Index conventions matter: a sequence starting at index zero uses different exponents.','起始下标重要：从零编号时指数形式会改变。',['Find the fourth arithmetic term in the example.','例中等差数列第四项多少？',15],['Find the fourth geometric term.','例中等比数列第四项多少？',54]);
R('M06.02','求和与裂项','sigma notation;telescoping;partial sum','求和符号;裂项;部分和','A telescoping sum contains terms that cancel after adjacent expressions are expanded. Keep the surviving endpoints.','裂项和在展开相邻表达式后大量抵消，须保留未抵消端点。','Because 1/[k(k+1)]=1/k−1/(k+1), summing k=1 through 4 gives 1−1/5=4/5.','由1/[k(k+1)]=1/k−1/(k+1)，k从1到4求和得1−1/5=4/5。','Cancellation works across addition only after an exact decomposition, not by deleting arbitrary factors.','抵消须先作准确分解，不能随意删除因子。',['Find Σ from k=1 to 4 of 1/[k(k+1)].','求k=1到4的1/[k(k+1)]之和。',0.8],['Find the same sum through k=9.','同样求和到k=9是多少？',0.9,'The endpoints give 1−1/10=0.9.','端点给出1−1/10=0.9。']);
R('M06.03','一阶递推','initial condition;fixed point;iteration','初值;不动点;迭代','A first-order recurrence uses the previous term. For a_(n+1)=ra_n+b, subtract a fixed point L satisfying L=rL+b when r≠1.','一阶递推用前一项；a_(n+1)=ra_n+b中，r≠1时可减去满足L=rL+b的不动点。','For a_(n+1)=a_n/2+3, L=6. Starting at a₀=2 gives a₁=4,a₂=5 and a_n−6=−4/2^n.','a_(n+1)=a_n/2+3的不动点6；a₀=2时a₁=4、a₂=5，且a_n−6=−4/2^n。','A fixed point need not attract: attraction here requires |r|<1.','不动点不一定吸引，线性情形需|r|<1。',['Find the fixed point of a↦a/2+3.','a↦a/2+3的不动点多少？',6],['From a₀=2, find a₂.','a₀=2时a₂多少？',5]);
R('M06.04','线性递推与特征根','characteristic equation;repeated root;initial values','特征方程;重根;初值','Trying a_n=r^n converts a homogeneous constant-coefficient recurrence into a polynomial equation for r. Repeated roots introduce polynomial factors in n.','令a_n=r^n把常系数齐次递推化为关于r的多项式方程；重根对应n的多项式因子。','For a_n=3a_(n−1)−2a_(n−2), r²−3r+2=0 has roots 1,2. Thus a_n=A+B2^n; a₀=1,a₁=3 gives A=−1,B=2.','递推a_n=3a_(n−1)−2a_(n−2)特征根1、2；a_n=A+B2^n。初值1、3给A=−1、B=2。','The recurrence alone does not determine the coefficients; enough initial values are essential.','递推本身不确定系数，必须提供足够初值。',['With a₀=1,a₁=3, find a₂.','a₀=1、a₁=3时a₂多少？',7,'3×3−2×1=7.','3×3−2×1=7。'],['Find the larger characteristic root.','较大特征根多少？',2]);
R('M06.05','生成函数入门','formal series;coefficient extraction;convolution','形式级数;系数提取;卷积','The ordinary generating function is A(x)=Σa_nx^n. Multiplication combines coefficients by convolution, keeping every pair of indices summing to the target.','普通生成函数为A(x)=Σa_nx^n；乘法通过卷积组合系数，遍历下标和等于目标的配对。','(1+x+x²+… )² has coefficient n+1 at x^n: choose the first exponent from 0 through n. Thus the x³ coefficient is 4.','(1+x+x²+…)²中x^n系数为n+1，因为第一个指数可从0取到n；x³系数为4。','Formal manipulations concern coefficients; analytic convergence is a separate question.','形式运算关注系数，解析收敛是另一个问题。',['Find the x³ coefficient of 1/(1−x)².','1/(1−x)²的x³系数多少？',4],['Find its x⁵ coefficient.','其x⁵系数多少？',6,'The coefficient is n+1=6.','系数为n+1=6。']);
R('M06.06','界与渐近增长','big O;little o;dominant term','大O;小o;主导项','f=O(g) means |f| is eventually bounded by a constant multiple of |g|. f=o(g) means f/g tends to zero where defined.','f=O(g)表示最终|f|被|g|的常数倍控制；f=o(g)表示比值趋零。','For n≥1, 3n²+2n+1≤6n², so it is O(n²). Dividing by n² gives 3+2/n+1/n²→3.','n≥1时3n²+2n+1≤6n²，故为O(n²)；除n²得3+2/n+1/n²→3。','Big O is an upper bound, not necessarily a tight classification. It does not imply equal values.','大O是上界，不必紧确，也不表示数值相等。',['What is the limit of (3n²+2n+1)/n²?','(3n²+2n+1)/n²的极限多少？',3],['For n=1, evaluate 3n²+2n+1.','n=1时代入3n²+2n+1。',6]);
F('M07','Differential calculus studies local change by comparing nearby function values. A limit describes a value approached, not necessarily a value attained. A derivative is a limit of difference quotients and therefore requires the relevant limit to exist. Algebraic rules speed calculations only after differentiability and domains are checked. Geometrically, the derivative gives tangent slope; physically, differentiating position with respect to time gives instantaneous velocity. Use signs to study increasing and decreasing behavior, but check endpoints and nondifferentiable points separately when optimizing. A local linear approximation is accurate only over a range justified by how the derivative itself changes.','微分研究邻近函数值的局部变化。极限描述趋近值，不必等于实际取值。导数是差商极限，必须先存在。求导规则能加速计算，但要先检查可导性和定义域。几何上导数给切线斜率，物理上位置对时间求导给瞬时速度。导数符号可研究增减，优化还须检查端点和不可导点；线性近似的适用范围由导数自身变化控制。','calculus');
R('M07.01','极限与连续','limit;continuity;one-sided limit','极限;连续;单侧极限','Continuity at a means the limit as x approaches a equals f(a). Both one-sided limits must agree at an interior point.','a处连续要求x趋a时极限等于f(a)；内点两侧极限须一致。','For x≠1, (x²−1)/(x−1)=x+1, so its limit at 1 is 2 although the original expression is undefined there.','x≠1时(x²−1)/(x−1)=x+1，故在1处极限为2，虽然原式无定义。','Substituting into an undefined quotient is not evaluating a limit.','向无定义分式代入不等于求极限。',['Find lim as x→1 of (x²−1)/(x−1).','求x趋1时(x²−1)/(x−1)极限。',2],['What value fills the hole continuously?','补上哪个函数值可使它连续？',2]);
R('M07.02','导数作为局部变化率','difference quotient;instantaneous rate;tangent','差商;瞬时变化率;切线','f′(a)=lim[h→0](f(a+h)−f(a))/h. The quotient is an average rate before taking the limit.','f′(a)=lim[h→0](f(a+h)−f(a))/h；取极限前商是平均变化率。','For f(x)=x², the quotient is (2ah+h²)/h=2a+h, so f′(a)=2a. At a=3 the tangent slope is 6.','f(x)=x²的差商为2a+h，极限2a；a=3时切线斜率6。','A sharp corner can have unequal one-sided slopes even when the function is continuous.','尖角即使连续，也可能左右斜率不同而不可导。',['Find the derivative of x² at x=3.','x²在x=3处导数多少？',6],['Find it at x=−2.','x=−2处呢？',-4,'2(−2)=−4.','2(−2)=−4。']);
R('M07.03','求导法则','product rule;quotient rule;chain rule','乘积法则;商法则;链式法则','The chain rule differentiates f(g(x)) as f′(g(x))g′(x). Products require u′v+uv′.','链式法则为f′(g(x))g′(x)；乘积需u′v+uv′。','For y=(3x+1)², chain rule gives y′=2(3x+1)×3. At x=1 this is 24.','y=(3x+1)²求导得2(3x+1)×3，x=1时为24。','Trigonometric derivative rules require radians. A quotient rule requires a nonzero denominator.','三角求导规则要求弧度，商法则要求分母非零。',['Find y′ at x=1 for y=(3x+1)².','y=(3x+1)²在x=1处导数多少？',24],['Find it at x=0.','x=0处呢？',6,'2×1×3=6.','2×1×3=6。']);
R('M07.04','中值定理与形状','mean value theorem;monotonicity;concavity','中值定理;单调性;凹凸性','A continuous function on [a,b], differentiable inside, has some tangent slope equal to its secant slope. The second derivative describes changing slope.','闭区间连续且内部可导的函数，某处切线斜率等于割线斜率；二阶导数描述斜率变化。','For x² on [1,3], secant slope=(9−1)/2=4. Since f′(x)=2x, the matching point is x=2.','x²在[1,3]割线斜率4；导数2x，因此匹配点x=2。','A zero derivative alone does not prove an extremum; x³ has one at zero without turning.','导数为零不必是极值，x³在零处不会转向。',['Find the secant slope for x² on [1,3].','x²在[1,3]的割线斜率多少？',4],['Find the matching interior point.','匹配的内部点是多少？',2]);
R('M07.05','最优化与相关变化率','critical point;constraint;implicit differentiation','临界点;约束;隐式求导','Optimization compares critical points and boundary values. Related rates differentiate an equation connecting quantities changing with time.','优化须比较临界点与边界；相关变化率对随时间变化量之间的关系式求导。','A rectangle with perimeter 20 has area A=x(10−x). A′=10−2x vanishes at x=5, giving maximum area 25.','周长20的矩形面积为x(10−x)，导数10−2x在5为零，最大面积25。','State the physical domain: here 0≤x≤10. A stationary point outside it is irrelevant.','须说明实际定义域，此处0≤x≤10，范围外驻点无关。',['Find the maximizing x.','使面积最大时x多少？',5],['Find that maximum area.','最大面积多少？',25]);
R('M07.06','局部近似与误差','linearization;differential;error order','线性化;微分;误差阶','Near a, f(a+h)≈f(a)+f′(a)h. A bounded second derivative provides an error bound proportional to h².','a附近f(a+h)≈f(a)+f′(a)h；二阶导数有界时误差可由常数乘h²控制。','For √x near 4, f(4)=2 and f′(4)=1/4. Thus √4.04≈2+0.04/4=2.01.','√x在4附近，函数值2、导数1/4，所以√4.04≈2.01。','Approximation is not equality. Moving far from the expansion point may destroy accuracy.','近似不是相等，离展开点太远可能失准。',['Give the linear estimate of √4.04.','给出√4.04的线性估计。',2.01],['Give the linear estimate of √3.96.','给出√3.96的线性估计。',1.99,'2−0.04/4=1.99.','2−0.04/4=1.99。']);
F('M08','Integral calculus accumulates continuously varying quantities. A definite integral is a limit of weighted sums over a specified interval; it has units equal to the integrand units multiplied by the variable units. Signed area differs from total geometric area when the function is negative. The fundamental theorem connects accumulation to differentiation, but its hypotheses must be checked at discontinuities or unbounded endpoints. Antiderivatives differ by constants, while definite integrals give numbers. Infinite sums and improper integrals introduce another limit problem: terms must be combined through a defined limiting process, not manipulated as though infinitely many finite operations were automatically justified.','积分累积连续变化量。定积分是指定区间上加权和的极限，单位为被积函数单位乘变量单位。函数为负时，有向面积不同于几何总面积。微积分基本定理连接累积与求导，但在不连续或无界端点须检查条件。原函数相差常数，定积分给数值。无穷和与反常积分还引入极限问题，不能未经论证把无限操作当作有限代数。','calculus');
R('M08.01','黎曼和与定积分','partition;Riemann sum;signed area','分割;黎曼和;有向面积','A Riemann sum adds function height times interval width. Riemann integrability requires a common limit as the partition mesh tends to zero.','黎曼和累加函数高度乘小段宽度；黎曼可积要求分割网格趋零时有共同极限。','For f(x)=x on [0,2], triangular area is base 2 times height 2 divided by 2, giving integral 2.','f(x)=x在[0,2]下方为底2高2的三角形，积分为2。','Finite left and right sums are usually approximations.','有限左右和通常是近似。',['Find ∫₀² x dx.','求∫₀² x dx。',2],['Find ∫₀² 3 dx.','求∫₀² 3 dx。',6,'Constant height 3 times width 2 gives 6.','高3宽2的矩形面积6。']);
R('M08.02','微积分基本定理','accumulation;antiderivative;endpoint evaluation','累积;原函数;端点求值','For continuous f, F(x)=∫ₐˣf(t)dt has derivative f(x). If G′=f, then ∫ₐᵇf=G(b)−G(a).','f连续时F(x)=∫ₐˣf(t)dt满足F′=f；G′=f时定积分等于G(b)−G(a)。','An antiderivative of 2x is x². Therefore ∫₁³2x dx=9−1=8.','2x的原函数为x²，所以∫₁³2x dx=9−1=8。','Differentiate your proposed antiderivative before using the endpoint formula.','使用端点公式前先求导检验原函数。',['Find ∫₁³2x dx.','求∫₁³2x dx。',8],['For F(x)=∫₀ˣ2t dt, find F′(4).','F(x)=∫₀ˣ2t dt，求F′(4)。',8,'The derivative is 2x, giving 8.','导数为2x，代入得8。']);
R('M08.03','积分技巧','substitution;integration by parts;partial fractions','换元;分部积分;部分分式','Substitution reverses the chain rule. Integration by parts reverses the product rule: ∫u dv=uv−∫v du.','换元逆用链式法则；分部积分逆用乘积法则：∫u dv=uv−∫v du。','In ∫₀¹2x(x²+1)dx, set u=x²+1, du=2x dx. Bounds become 1,2, giving [u²/2]₁²=3/2.','∫₀¹2x(x²+1)dx令u=x²+1，du=2x dx，界限1、2，结果3/2。','Change bounds or return fully to the original variable; never mix both systems.','须变界限或完整换回原变量，不能混用。',['Evaluate the worked integral.','计算例中的积分。',1.5],['What u-bound corresponds to x=1?','x=1对应u上界多少？',2]);
R('M08.04','反常积分与应用','improper endpoint;convergence;comparison','反常端点;收敛;比较','An improper integral is defined by a limit at infinity or a singularity. Both sides of an interior singularity must converge separately.','反常积分用无穷或奇点处极限定义；内部奇点两侧须分别收敛。','∫₁ᴿx⁻²dx=1−1/R tends to 1. In contrast ∫₁ᴿ1/x dx=log R grows without bound.','∫₁ᴿx⁻²dx=1−1/R趋1，而∫₁ᴿ1/x dx=log R无界。','Cancellation across a singularity is not ordinary improper convergence.','奇点两边相消不等于普通反常积分收敛。',['Find ∫₁∞x⁻²dx.','求∫₁∞x⁻²dx。',1],['Find ∫₁²x⁻²dx.','求∫₁²x⁻²dx。',0.5,'1−1/2=1/2.','1−1/2=1/2。']);
R('M08.05','无穷级数与收敛','partial sums;geometric series;convergence tests','部分和;等比级数;收敛判别','A series converges when its partial sums converge. Terms tending to zero are necessary but insufficient; the harmonic series is a counterexample.','级数收敛指部分和收敛；通项趋零必要但不充分，调和级数是反例。','For |r|<1, (1−r^(n+1))/(1−r) tends to 1/(1−r). Thus 1+1/2+1/4+…=2.','|r|<1时有限等比和趋1/(1−r)，所以1+1/2+1/4+…=2。','The ratio test is inconclusive when its limiting ratio is 1.','比值判别极限为1时无法判断。',['Find Σ from n=0 of (1/2)^n.','求n从0开始的(1/2)^n无穷和。',2],['What if the sum starts at n=1?','从n=1开始呢？',1,'Remove the first term 1.','减去首项1。']);
R('M08.06','幂级数与泰勒近似','Taylor coefficient;radius;remainder','泰勒系数;收敛半径;余项','Taylor coefficients are f^(n)(a)/n!. Equality to an infinite Taylor series also requires the remainder to tend to zero.','泰勒系数为f^(n)(a)/n!；等于无穷泰勒级数还要求余项趋零。','The quadratic approximation to e^x at zero is 1+x+x²/2. At x=0.1 it gives 1.105, with nonzero higher-order error.','e^x在零的二次近似1+x+x²/2，在0.1处给1.105，仍有高阶误差。','Check convergence at boundary points separately.','收敛区间端点须单独检查。',['Give the quadratic estimate of e^0.1.','给e^0.1的二次估计。',1.105],['What is the x² coefficient?','x²系数多少？',0.5]);
F('M09','Linear algebra studies combinations formed by adding vectors and multiplying them by scalars. A linear map preserves these two operations, so knowing its action on a basis determines it everywhere. Matrices describe such maps after bases are chosen; changing a basis changes coordinates without changing the underlying map. Elimination exposes consistency, free variables, and pivot columns. Dimension counts independent directions, while determinants describe signed volume scaling for square maps. Eigenvectors identify directions that the map only scales. Always state the ambient vector space and scalar field, and distinguish the matrix shape from properties that require a square matrix.','线性代数研究向量相加和数乘组成的组合。线性映射保持这两种运算，因此知道基上的作用便确定全部作用。矩阵依选定的基描述映射，换基改变坐标却不改变映射本身。消元揭示相容性、自由变量和主元列。维数计独立方向，行列式描述方阵的有向体积缩放，特征向量给只被缩放的方向。须说明向量空间、数域和矩阵形状，方阵性质不能随意用于矩形矩阵。','linear');
R('M09.01','线性方程组与消元','row operation;pivot;free variable','行变换;主元;自由变量','Elementary row operations preserve the solution set: swap equations, scale by a nonzero number, or add a multiple of another equation.','交换方程、非零数乘方程或加另一方程倍数，都保持解集。','From x+y=5 and x−y=1, addition gives 2x=6, hence x=3 and y=2.','x+y=5与x−y=1相加得2x=6，所以x=3、y=2。','A row 0=1 signals inconsistency; a zero row alone does not imply a unique solution.','0=1表示不相容，零行本身不表示唯一解。',['Find x in the worked system.','求例中方程组x。',3],['Find y.','求y。',2]);
R('M09.02','向量、张成与无关性','span;linear dependence;homogeneous system','张成;线性相关;齐次方程组','A span is all linear combinations. Vectors are independent when the zero combination forces every coefficient to zero.','张成是全部线性组合；零组合只有全零系数时，向量组线性无关。','(1,0),(0,1) span the plane: (3,4)=3(1,0)+4(0,1). But (2,0) adds no new direction to (1,0).','(1,0)、(0,1)张成平面，(3,4)=3(1,0)+4(0,1)；(2,0)不增加新方向。','Independence concerns the whole collection, not merely unequal vector values.','无关性针对整个向量组，不是向量两两不相等。',['What coefficient multiplies (1,0) to represent (3,4)?','表示(3,4)时(1,0)系数多少？',3],['What is the dimension of span{(1,0),(2,0)}?','span{(1,0),(2,0)}维数多少？',1,'Both lie on the same one-dimensional axis.','二者都在同一条一维轴上。']);
R('M09.03','向量空间、基与维数','subspace;basis;dimension','子空间;基;维数','A subspace contains zero and is closed under addition and scalar multiplication. A basis is an independent spanning set; dimension is its size.','子空间含零且对加法数乘封闭。基是无关的生成集，维数为基的个数。','Polynomials of degree at most two have basis 1,x,x². A polynomial 2−3x+5x² has coordinates (2,−3,5) and the space has dimension 3.','至多二次多项式以1、x、x²为基；2−3x+5x²的坐标为(2,−3,5)，空间维数3。','Polynomials of exactly degree two do not form a subspace: zero is excluded.','恰好二次多项式不构成子空间，因为不含零。',['What is the dimension of polynomials of degree at most 2?','至多二次多项式空间维数多少？',3],['What is the x coefficient of 2−3x+5x²?','2−3x+5x²中x系数多少？',-3]);
R('M09.04','线性映射与矩阵','linearity;matrix columns;composition','线性;矩阵列;复合','A map is linear if T(au+bv)=aT(u)+bT(v). Matrix columns are images of the input basis vectors.','T(au+bv)=aT(u)+bT(v)定义线性；矩阵列就是输入基向量的像。','The diagonal matrix diag(2,3) maps (4,5) to (8,15). It stretches coordinate directions independently.','对角矩阵diag(2,3)把(4,5)映到(8,15)，分别拉伸两个坐标方向。','Adding a nonzero translation makes a map affine, not linear, because zero no longer maps to zero.','加非零平移会变为仿射而非线性，因为零不再映到零。',['Find the first coordinate of diag(2,3)(4,5).','diag(2,3)(4,5)首坐标多少？',8],['Find the second coordinate.','第二坐标多少？',15]);
R('M09.05','行列式与可逆性','determinant;inverse;volume scaling','行列式;逆;体积缩放','For a 2×2 matrix, determinant is ad−bc. A square matrix is invertible exactly when its determinant is nonzero.','二阶行列式为ad−bc；方阵当且仅当行列式非零时可逆。','For rows (2,1),(1,3), determinant is 6−1=5. Its inverse is (1/5) times the matrix with rows (3,−1),(−1,2).','矩阵行(2,1)、(1,3)的行列式为5，逆为1/5乘行(3,−1)、(−1,2)的矩阵。','Determinant zero means some direction collapses; it does not mean every matrix entry is zero.','行列式零表示某方向塌缩，不表示每个元素为零。',['Find that determinant.','求该行列式。',5],['Find the determinant of diag(2,4,3).','diag(2,4,3)行列式多少？',24,'Multiply diagonal entries: 2×4×3=24.','对角元相乘2×4×3=24。']);
R('M09.06','特征值与对角化','eigenvector;eigenvalue;diagonalization','特征向量;特征值;对角化','Av=λv with v nonzero defines an eigenpair. A matrix is diagonalizable when an entire basis consists of eigenvectors.','Av=λv且v非零定义特征对；存在特征向量基时矩阵可对角化。','diag(2,5) scales the first axis by 2 and second by 5. Its third power is diag(8,125).','diag(2,5)把第一轴放大2倍，第二轴5倍；三次幂为diag(8,125)。','Repeated eigenvalues may lack enough independent eigenvectors; diagonalization is not automatic.','重特征值可能没有足够无关特征向量，不能自动对角化。',['Find the smaller eigenvalue of diag(2,5).','diag(2,5)较小特征值多少？',2],['Find the second diagonal entry of its cube.','其三次幂第二对角元多少？',125]);
F('M10','Once a vector space has an inner product, lengths and angles allow approximation problems to be formulated geometrically. Orthogonality separates independent contributions to squared length. Projection finds the nearest vector in a subspace by requiring the residual to be orthogonal to that subspace. Spectral decompositions reveal how a map stretches special directions, while singular values extend that idea to rectangular maps. Coordinate transformations can simplify a quadratic form without changing its geometric meaning. Distinguish exact algebraic rank from numerical rank estimated using a tolerance, since tiny singular values can magnify data errors even when a formal inverse exists.','赋予内积后，向量空间具有长度与角，近似问题可几何化。正交使平方长度分解；投影要求残差垂直子空间，从而找最近向量。谱分解揭示特殊方向的拉伸，奇异值将它扩展到矩形矩阵。换坐标可简化二次型而不改变几何意义。精确代数秩与按容差估计的数值秩须区分：即使形式上可逆，极小奇异值也会放大数据误差。','linear');
R('M10.01','内积与正交','inner product;norm;Gram-Schmidt','内积;范数;施密特正交化','An inner product defines squared length ⟨v,v⟩. Gram-Schmidt subtracts projections onto earlier orthonormal directions.','内积给平方长度⟨v,v⟩；施密特过程减去前面正交归一方向上的投影。','From (1,0),(1,1), normalize the first vector, subtract its projection from the second, and obtain (0,1).','从(1,0)、(1,1)出发，先归一第一向量，再从第二向量减去投影，得到(0,1)。','An inner product must be positive definite; an arbitrary bilinear expression may not be one.','内积必须正定，任意双线性表达式未必是内积。',['Find (1,0)·(0,1).','求(1,0)·(0,1)。',0],['Find the norm of (0,1).','(0,1)范数多少？',1]);
R('M10.02','最小二乘与投影','normal equations;residual;orthogonal projection','正规方程;残差;正交投影','Least squares minimizes ||Ax−b||². Its residual is orthogonal to the column space, giving AᵀAx=Aᵀb.','最小二乘最小化||Ax−b||²；残差垂直列空间，因此AᵀAx=Aᵀb。','Project b=(3,4) onto the x-axis: the closest point is (3,0), residual (0,4), squared error 16.','把(3,4)投影到x轴，最近点(3,0)，残差(0,4)，平方误差16。','Normal equations can worsen numerical conditioning; QR or SVD is often preferable computationally.','正规方程可能恶化数值条件，计算常优先QR或SVD。',['Find the projection x-coordinate.','投影的x坐标多少？',3],['Find squared residual length.','残差平方长度多少？',16]);
R('M10.03','谱定理','symmetric matrix;orthogonal eigenbasis;real spectrum','对称矩阵;正交特征基;实谱','Every real symmetric matrix admits an orthonormal eigenbasis and real eigenvalues: A=QΛQᵀ.','实对称矩阵有正交归一特征基和实特征值，A=QΛQᵀ。','The matrix with rows (2,1),(1,2) has eigenvectors (1,1),(1,−1), with eigenvalues 3 and 1. Normalizing divides each vector by √2.','行(2,1)、(1,2)的矩阵对(1,1)、(1,−1)特征值为3、1，各除√2即可归一。','The real symmetric hypothesis matters; arbitrary real matrices may have complex eigenvalues.','实对称条件重要，一般实矩阵可能有复特征值。',['Find the larger eigenvalue.','较大特征值多少？',3],['Find the smaller eigenvalue.','较小特征值多少？',1]);
R('M10.04','奇异值分解','singular value;left vectors;rank approximation','奇异值;左奇异向量;低秩近似','SVD writes A=UΣVᵀ with orthonormal direction systems. Singular values are nonnegative square roots of eigenvalues of AᵀA.','SVD为A=UΣVᵀ，方向系正交归一；奇异值为AᵀA特征值的非负平方根。','For diag(3,−2), AᵀA=diag(9,4), so singular values are 3 and 2; signs are absorbed by direction vectors.','diag(3,−2)的AᵀA为diag(9,4)，奇异值3与2，符号由方向向量吸收。','Singular values are not generally eigenvalues; they remain meaningful for rectangular matrices.','奇异值通常不等于特征值，矩形矩阵也有奇异值。',['Find the largest singular value of diag(3,−2).','diag(3,−2)最大奇异值多少？',3],['Find the smallest.','最小奇异值多少？',2]);
R('M10.05','二次型与正定性','quadratic form;positive definite;Hessian','二次型;正定;海森矩阵','A symmetric quadratic form xᵀAx is positive definite when it is positive for every nonzero x, equivalently all eigenvalues are positive.','对称二次型xᵀAx对所有非零x为正时正定，等价于所有特征值正。','For A=diag(2,5), q(x,y)=2x²+5y². At (1,2), q=2+20=22, and every nonzero pair gives a positive result.','A=diag(2,5)时q=2x²+5y²，在(1,2)为22，任何非零对都为正。','Positive diagonal entries alone do not ensure positive definiteness when off-diagonal terms exist.','有非对角项时，仅对角元为正不能保证正定。',['Evaluate q at (1,2).','求q(1,2)。',22],['What is the minimum eigenvalue of this A?','此A最小特征值多少？',2]);
R('M10.06','标准形与应用','similarity;Jordan block;minimal polynomial','相似;约旦块;最小多项式','Similarity P⁻¹AP changes basis. Over the complex numbers, Jordan form records eigenvalues and any failure of diagonalizability through blocks.','相似变换P⁻¹AP表示换基；复数域上的约旦形用块记录特征值及不可对角化程度。','J=[[2,1],[0,2]]=2I+N with N²=0. Thus J²=4I+4N=[[4,4],[0,4]], despite having only one independent eigenvector.','J=[[2,1],[0,2]]=2I+N且N²=0，所以J²=[[4,4],[0,4]]，它仅有一个独立特征向量。','Similarity preserves eigenvalues but is different from changing a bilinear form by congruence.','相似保持特征值，但不同于二次型的合同变换。',['Find the upper-right entry of J².','J²右上元多少？',4],['How many independent eigenvectors does J have?','J有几个独立特征向量？',1]);
F('M11','Multivariable calculus distinguishes changing one coordinate from moving in an arbitrary direction. The derivative, when it exists, is a linear map that approximates the full change; partial derivatives are only its coordinate components. Gradients organize first-order change of scalar functions, while Jacobian matrices describe vector-valued maps. Integration accumulates over regions, curves, or surfaces using the corresponding length, area, or volume element. Coordinate changes require a Jacobian factor because equal coordinate increments need not represent equal physical volume. Orientation controls signs in circulation and flux. Check smoothness, domain geometry, and boundary orientation before applying a global integral theorem.','多元微积分区分改变一个坐标与沿任意方向移动。存在时，导数是近似整体变化的线性映射，偏导只是坐标分量。梯度组织标量函数的一阶变化，雅可比矩阵描述向量值映射。积分沿区域、曲线或曲面累积，需相应长度、面积或体积元。换坐标要乘雅可比因子，因为等坐标增量未必表示等物理体积。方向决定环流和通量符号；使用整体积分定理前要检查光滑性、区域和边界方向。','calculus');
R('M11.01','多元极限与偏导','path independence;partial derivative;differentiability','路径无关;偏导;可微','A multivariable limit must agree along every approach. A partial derivative varies one coordinate while fixing the others.','多元极限须沿所有趋近方式相同；偏导只改变一个坐标，其余固定。','For f=x²y, f_x=2xy and f_y=x². At (2,3), the derivatives are 12 and 4.','f=x²y时f_x=2xy，f_y=x²；在(2,3)分别为12与4。','Matching two paths does not establish a limit; differing paths disprove it.','两条路径一致不能证明极限存在，不一致却能否定。',['Find f_x(2,3) for x²y.','x²y的f_x(2,3)多少？',12],['Find f_y(2,3).','f_y(2,3)多少？',4]);
R('M11.02','梯度、雅可比与链式法则','gradient;Jacobian;directional derivative','梯度;雅可比;方向导数','The gradient collects scalar partial derivatives. For differentiable f, change along unit vector u is ∇f·u; composition derivatives multiply Jacobian matrices.','梯度收集偏导；可微f沿单位u变化率为∇f·u，复合导数对应雅可比矩阵相乘。','For f=x²+y² at (3,4), gradient=(6,8), magnitude 10. Along the x-axis unit direction, the rate is 6.','x²+y²在(3,4)梯度为(6,8)，模10；沿x轴单位方向变化率6。','Normalize a direction before interpreting it as rate per unit distance.','解释单位距离变化率前必须归一方向。',['Find the x-direction rate.','沿x方向变化率多少？',6],['Find the largest unit-direction rate.','最大单位方向变化率多少？',10]);
R('M11.03','约束极值','Lagrange multiplier;constraint gradient;boundary','拉格朗日乘子;约束梯度;边界','At a regular constrained extremum of f with g=c, gradients satisfy ∇f=λ∇g, provided ∇g≠0. Candidates still require comparison.','约束g=c的正则极值处，∇f=λ∇g，要求∇g≠0；候选仍须比较。','Maximize xy under x+y=10 with nonnegative variables. Equations y=λ,x=λ give x=y=5 and product 25; endpoints give zero.','非负x+y=10下最大化xy，方程y=λ、x=λ得x=y=5，积25；端点积零。','Singular constraint points and boundaries can escape multiplier equations.','奇异约束点和边界可能不被乘子方程捕获。',['Find maximizing x.','最大时x多少？',5],['Find the maximum product.','最大乘积多少？',25]);
R('M11.04','重积分与坐标变换','iterated integral;Jacobian determinant;polar area','累次积分;雅可比行列式;极坐标面积元','A coordinate change multiplies volume by the absolute Jacobian determinant. In plane polar coordinates, dA=r dr dθ.','坐标变换使体积元乘雅可比行列式绝对值；平面极坐标dA=r dr dθ。','On rectangle 0≤x≤2,0≤y≤3, integrating constant 4 gives 4×2×3=24. Integrating x gives (2²/2)×3=6.','矩形0≤x≤2、0≤y≤3上，常数4积分为24，x积分为(2²/2)×3=6。','The absolute value matters for volume; oriented forms retain a sign instead.','体积元需要绝对值，有向微分形式则保留符号。',['Find the integral of 4 over this rectangle.','该矩形上4的积分多少？',24],['Find the integral of x.','x的积分多少？',6]);
R('M11.05','曲线积分与曲面积分','circulation;flux;parameterization','环流;通量;参数化','A line integral F·dr accumulates tangential work. A flux integral F·n dS accumulates normal flow across an oriented surface.','曲线积分F·dr累积切向功，通量F·n dS累积穿过有向曲面的法向流。','Constant force (3,0) along displacement (2,1) does work 6. A constant normal field of magnitude 4 through area 5 gives flux 20.','恒力(3,0)沿位移(2,1)做功6；大小4的恒定法向场穿过面积5，通量20。','Reversing orientation reverses signed work or flux; scalar arc-length integrals behave differently.','反转方向使有向功或通量反号，标量弧长积分不同。',['Find the stated work.','所述功多少？',6],['Find the stated flux.','所述通量多少？',20]);
R('M11.06','格林、斯托克斯与散度定理','boundary orientation;curl;divergence','边界方向;旋度;散度','These theorems relate interior derivatives to boundary integrals. Stokes connects curl to circulation; divergence connects volume sources to outward flux.','这些定理连接内部导数与边界积分；斯托克斯联系旋度与环流，散度定理联系体源与向外通量。','For F=(x,y,z), divergence=3. Across the outward boundary of a box with volume 8, total flux is ∫3 dV=24.','F=(x,y,z)散度为3；体积8的盒子外边界总通量为24。','A field singularity inside the region can invalidate direct application.','区域内部场的奇点可能使直接应用无效。',['Find divergence of (x,y,z).','(x,y,z)散度多少？',3],['Find flux through the stated box.','所述盒子外通量多少？',24]);
F('M12','A differential equation specifies how an unknown function and its derivatives are related. An initial condition selects a trajectory from a family, but existence and uniqueness depend on the equation and domain. Derive a model from conservation or a rate law, stating which quantities and parameters have physical meaning. Verify a proposed solution by differentiating and substituting into the original equation as well as checking initial data. Linear equations support superposition for homogeneous solutions; forcing adds a particular response. Numerical integration replaces continuous evolution by finite steps, introducing approximation and possible instability that must be checked by changing the step size.','微分方程规定未知函数与导数之间的关系。初值从解族中选轨道，但存在唯一性依方程和定义域而定。建模应从守恒或速率规律出发，说明量与参数的意义。验证解要对原方程代入并检查初值。线性齐次解可叠加，外力增加特解。数值积分用有限步替代连续演化，会引入误差或不稳定，应改变步长检查。','calculus');
R('M12.01','建模与初值问题','rate law;initial condition;uniqueness','速率定律;初值;唯一性','An initial-value problem combines a differential equation with a function value at a starting point. A rate proportional to amount gives y′=ky.','初值问题结合微分方程与起点函数值；变化率正比于数量时y′=ky。','For y′=2y and y(0)=3, y=3e^(2t). Differentiation gives 6e^(2t)=2y and the initial value is 3.','y′=2y、y(0)=3的解为3e^(2t)，导数6e^(2t)=2y，初值也为3。','A formula matching the initial value alone is not a solution.','仅满足初值的公式不是解。',['Find y′(0).','y′(0)多少？',6],['Find y(0).','y(0)多少？',3]);
R('M12.02','一阶方程','separation;integrating factor;equilibrium','分离变量;积分因子;平衡解','A separable equation y′=g(t)h(y) allows integration after dividing by h(y), with zero cases checked separately. Linear first-order equations use an integrating factor.','可分离方程y′=g(t)h(y)可除h(y)后积分，但零点需另查；一阶线性方程可用积分因子。','For y′=−y with y(0)=4, separation yields log|y|=−t+C, hence y=4e^(−t). The equilibrium y=0 also solves the equation.','y′=−y、y(0)=4分离得log|y|=−t+C，故y=4e^(−t)；y=0也是平衡解。','Dividing by y can hide the equilibrium y=0.','除以y可能隐藏平衡解y=0。',['Find y′(0).','y′(0)多少？',-4],['Find the equilibrium value.','平衡值多少？',0]);
R('M12.03','高阶线性方程','characteristic root;homogeneous response;forcing','特征根;齐次响应;强迫项','Constant-coefficient equations admit exponential trial solutions. Repeated roots require t factors; complex roots lead to sine and cosine combinations.','常系数方程可试指数解；重根需乘t，复根对应正弦余弦组合。','For y″−3y′+2y=0, roots 1 and 2 give y=Ae^t+Be^(2t). With y(0)=3,y′(0)=5, A=1,B=2.','y″−3y′+2y=0根1、2，解Ae^t+Be^(2t)；初值3、5给A=1、B=2。','Particular solutions for forcing must be adjusted when they overlap the homogeneous family.','强迫项的试探特解与齐次解重复时须调整。',['Find A.','求A。',1],['Find B.','求B。',2]);
R('M12.04','方程组与相图','state vector;equilibrium;stability','状态向量;平衡点;稳定性','A first-order system evolves a state vector. For x′=Ax, eigenvalue real parts determine linear growth or decay modes.','一阶系统演化状态向量；x′=Ax中，特征值实部决定线性模态增长或衰减。','For x′=−x,y′=−2y, both coordinates decay toward zero. Initial (3,4) has initial velocity (−3,−8).','x′=−x、y′=−2y时两坐标趋零；初始(3,4)的速度为(−3,−8)。','Linearization at a nonlinear equilibrium can be inconclusive when eigenvalues have zero real parts.','非线性平衡点的线性化在特征值实部零时可能无法判断。',['Find initial x′.','初始x′多少？',-3],['Find initial y′.','初始y′多少？',-8]);
R('M12.05','拉普拉斯变换与外力','Laplace transform;initial term;transfer function','拉普拉斯变换;初值项;传递函数','The Laplace transform integrates e^(−st)y(t) on nonnegative time. Derivatives become algebraic factors plus initial-value terms.','拉普拉斯变换在非负时间积分e^(−st)y(t)；导数变成代数因子加初值项。','For y′+2y=0,y(0)=3, transformation gives sY−3+2Y=0. Thus Y=3/(s+2), corresponding to y=3e^(−2t).','y′+2y=0、y(0)=3变换得sY−3+2Y=0，故Y=3/(s+2)，对应3e^(−2t)。','Do not omit the initial term in the derivative transform. Convergence restricts allowed s.','不可漏掉导数变换中的初值项；收敛限制s范围。',['Find Y at s=1.','s=1时Y多少？',1,'3/(1+2)=1.','3/(1+2)=1。'],['Find y′(0).','y′(0)多少？',-6,'−2y(0)=−6.','−2y(0)=−6。']);
R('M12.06','数值解与稳定性','Euler step;local error;stability region','欧拉步;局部误差;稳定域','Explicit Euler updates y_(n+1)=y_n+h f(t_n,y_n). Accuracy and stability both depend on step size and the equation.','显式欧拉为y_(n+1)=y_n+h f(t_n,y_n)；精度和稳定性都依赖步长与方程。','For y′=−2y,y₀=1,h=0.1, the update multiplies by 0.8: y₁=0.8,y₂=0.64.','y′=−2y、y₀=1、h=0.1时，每步乘0.8，因此y₁=0.8、y₂=0.64。','A decaying exact solution can have a growing numerical approximation if |1−2h|>1.','若|1−2h|>1，精确解衰减时数值解却可能增长。',['Find y₁.','求y₁。',0.8],['Find y₂.','求y₂。',0.64]);
F('M13','Analysis makes the limiting arguments of calculus precise. Definitions usually contain quantifiers whose order controls what must be uniform and what may depend on an earlier choice. To prove convergence, begin with an arbitrary positive tolerance and construct an index or neighborhood that guarantees the required estimate. Completeness supplies limits that rational numbers alone may lack. Compactness turns certain infinite local descriptions into finite control. Interchanging limits, sums, derivatives, and integrals requires a theorem with suitable hypotheses; pointwise agreement by itself is often too weak. Build both proofs and counterexamples to learn which assumptions carry the conclusion.','分析把微积分极限论证精确化。定义中的量词顺序决定什么要一致、什么可依赖先前选择。证明收敛应从任意正容差出发，构造满足估计的下标或邻域。完备性提供有理数可能缺失的极限，紧致性把一些无限局部信息变成有限控制。交换极限、求和、导数和积分必须有适用定理，逐点一致往往不够。证明和反例共同揭示哪些假设支撑结论。','analysis');
R('M13.01','实数完备性','upper bound;supremum;completeness','上界;上确界;完备性','Every nonempty real set bounded above has a least upper bound. The supremum need not belong to the set.','非空有上界实数集有最小上界；上确界未必属于集合。','The interval (0,1) has supremum 1 but no maximum. Any smaller candidate u<1 fails because a point between u and 1 belongs to the interval.','(0,1)上确界1却无最大值；任何u<1都被u与1之间的区间点超过。','Maximum means attained; supremum means least upper bound.','最大值须取到，上确界只要求最小上界。',['Find sup(0,1).','求(0,1)上确界。',1],['Find inf(0,1).','求(0,1)下确界。',0,'Zero is the greatest lower bound, though excluded.','零为最大下界，虽不包含。']);
R('M13.02','数列与实直线拓扑','epsilon definition;Cauchy sequence;open set','ε定义;柯西列;开集','a_n→L means eventually |a_n−L|<ε for every ε>0. A Cauchy sequence has terms eventually close to each other.','a_n→L要求每个ε>0下最终|a_n−L|<ε；柯西列要求尾部项彼此接近。','For a_n=1/n and ε=0.01, every n>100 satisfies |a_n|<ε. This explicitly constructs the required tail.','a_n=1/n、ε=0.01时，n>100均满足|a_n|<ε，明确给出所需尾部。','The chosen index may depend on ε, but not on each later n separately.','起始下标可依赖ε，不能对每个后续n另行选择。',['What is lim 1/n?','1/n极限多少？',0],['What is the smallest integer n with 1/n<0.01?','满足1/n<0.01的最小整数n多少？',101]);
R('M13.03','连续与紧致','open cover;compact set;uniform continuity','开覆盖;紧集;一致连续','Compactness means every open cover has a finite subcover. In Euclidean space, compact sets are exactly closed bounded sets.','紧致指每个开覆盖有有限子覆盖；欧氏空间中等价于闭且有界。','A continuous function on [0,2] attains its extrema. For f(x)=(x−1)², the minimum is 0 and maximum 1.','连续函数在[0,2]取得最值；f=(x−1)²最小0、最大1。','Closed and bounded is not a universal characterization in arbitrary topological spaces.','闭且有界不是任意拓扑空间中通用的紧致刻画。',['Find the minimum in the example.','例中最小值多少？',0],['Find the maximum.','最大值多少？',1]);
R('M13.04','严格的微分与积分','difference quotient;Darboux sums;fundamental theorem','差商;达布和;基本定理','Differentiation requires a difference-quotient limit. Riemann integrability can be characterized by upper and lower sums becoming arbitrarily close.','求导要求差商极限；黎曼可积可由上下和能够任意接近刻画。','For f(x)=x on [0,1] with n equal intervals, upper sum=(n+1)/(2n), lower sum=(n−1)/(2n); their gap is 1/n.','f=x在[0,1]等分n段，上和(n+1)/(2n)，下和(n−1)/(2n)，差1/n。','A bounded function with many discontinuities need not be Riemann integrable.','有界函数若不连续点过多，未必黎曼可积。',['Find the integral of x on [0,1].','x在[0,1]积分多少？',0.5,'Both bounds tend to 1/2.','上下和都趋1/2。'],['For n=20, find the upper-lower gap.','n=20时上下和差多少？',0.05,'1/20=0.05.','1/20=0.05。']);
R('M13.05','函数列与函数项级数','pointwise convergence;uniform convergence;interchange','逐点收敛;一致收敛;交换极限','Uniform convergence requires one index to control the error at every point simultaneously. It preserves continuity when each function is continuous.','一致收敛要求一个下标同时控制所有点误差；连续函数的一致极限连续。','x^n on [0,1] converges to 0 for x<1 and 1 at x=1. The discontinuous limit proves convergence is not uniform.','x^n在[0,1]于x<1趋0，x=1取1；极限不连续，故不一致收敛。','Pointwise convergence alone does not justify swapping limits with derivatives or integrals.','逐点收敛本身不能保证与求导或积分交换。',['Find the pointwise limit at x=1/2.','x=1/2处逐点极限多少？',0],['Find it at x=1.','x=1处呢？',1]);
R('M13.06','度量空间与测度入门','metric;Borel set;countable additivity','度量;博雷尔集;可数可加性','A metric satisfies positivity, symmetry, and the triangle inequality. A measure assigns nonnegative sizes with countable additivity to a specified family of sets.','度量满足正定、对称与三角不等式；测度在指定集合族上赋非负大小并满足可数可加。','On the real line, d(x,y)=|x−y| gives d(2,7)=5. Lebesgue lengths of disjoint intervals (0,2),(3,6) add to 5.','实线距离|x−y|给d(2,7)=5；不交区间(0,2)、(3,6)的勒贝格长度和为5。','Not every subset is automatically measurable under every measure construction.','不是每个子集都在任意测度构造下自动可测。',['Find d(2,7).','求d(2,7)。',5],['Find the length of the stated union.','所述并集长度多少？',5]);
F('M14','Abstract algebra studies operations through their laws instead of the particular appearance of their elements. Begin with a set and a precisely defined operation, then verify closure, associativity, identity, and inverses when claiming a group. A structure-preserving map carries algebraic relationships between structures; its kernel identifies elements indistinguishable from the identity. Quotients turn compatible equivalence classes into new algebraic objects. Counting the sizes of cosets reveals divisibility constraints in finite groups. Rings have two operations, so ideals must respect multiplication as well as addition. Concrete permutations, integers modulo n, and polynomial examples should accompany every abstract definition.','抽象代数通过运算规律研究结构，而不依元素外观。声称群时，要给集合与运算并检查封闭、结合、单位元与逆元。保结构映射在结构之间传递代数关系，核标识与单位元无法区分的元素。商结构把相容等价类变为新对象；陪集计数给有限群整除限制。环有两种运算，所以理想除加法外还须与乘法相容。每个抽象定义都应配合置换、模整数和多项式实例。','abstract');
R('M14.01','群与对称','group axioms;identity;inverse','群公理;单位元;逆元','A group has an associative operation, identity, and inverses for every element. Commutativity is an additional property, not a group axiom.','群的运算结合，有单位元且每个元素有逆；交换律是额外性质，不是群公理。','Integers modulo 5 under addition form a group. Identity is 0, and the inverse of 2 is 3 because 2+3≡0.','模5整数加法构成群，单位元0，2的逆为3，因为2+3≡0。','Positive integers under addition lack both zero and additive inverses, so they do not form a group.','正整数加法缺零与加法逆元，不构成群。',['Find the additive inverse of 2 modulo 5.','模5加法中2的逆多少？',3],['Find the identity.','单位元多少？',0]);
R('M14.02','子群、陪集与拉格朗日定理','subgroup;coset;index','子群;陪集;指数','Cosets of a subgroup partition a group into equal-sized sets. For a finite group, |G|=[G:H]|H|.','子群陪集把群分成等大集合；有限群满足|G|=[G:H]|H|。','In additive integers modulo 12, H={0,4,8} has size 3. Its four cosets each contain three elements, giving index 4.','模12加法群中H={0,4,8}大小3，四个陪集各含三元素，指数4。','A divisor of group order need not always be the order of a subgroup.','群阶的因数不总能作为某子群的阶。',['Find |H|.','|H|多少？',3],['Find the index of H.','H的指数多少？',4]);
R('M14.03','同态与商群','kernel;normal subgroup;quotient','核;正规子群;商群','A homomorphism preserves products. Its kernel is normal, so cosets of the kernel form a quotient group isomorphic to the image.','同态保持乘积，核为正规子群，因此按核取商得到与像同构的群。','Reduction from integers modulo 12 to modulo 4 has kernel {0,4,8}. The image has four elements, equal to 12/3.','模12到模4的约化映射核为{0,4,8}，像有4元素，等于12/3。','A quotient group requires normality; arbitrary left cosets do not support well-defined multiplication.','商群要求正规性，任意左陪集未必能良定义乘法。',['Find the kernel size.','核大小多少？',3],['Find the quotient size.','商群大小多少？',4]);
R('M14.04','群作用与计数','orbit;stabilizer;Burnside lemma','轨道;稳定子;伯恩赛德引理','A group action assigns compatible permutations of a set. Orbit size times stabilizer size equals group size for a finite action.','群作用为集合指定相容置换；有限情形轨道大小乘稳定子大小等于群大小。','The six symmetries of a triangle act transitively on its three vertices. A fixed vertex has stabilizer size 6/3=2.','三角形六个对称在三个顶点上传递作用，一个顶点的稳定子大小6/3=2。','Burnside averages numbers of fixed objects over group elements, not orbit sizes over objects.','伯恩赛德是对群元素的不动对象数取平均，不是对对象轨道大小取平均。',['Find the vertex orbit size.','顶点轨道大小多少？',3],['Find its stabilizer size.','稳定子大小多少？',2]);
R('M14.05','环、理想与商环','ring;ideal;quotient ring','环;理想;商环','A ring has addition forming an abelian group and associative multiplication distributing over addition. An ideal absorbs multiplication by ring elements.','环的加法构成交换群，乘法结合并对加法分配；理想吸收环元素的乘法。','The ideal 5Z identifies integers differing by a multiple of 5. In Z/5Z, [3][4]=[12]=[2].','理想5Z把相差5倍数的整数等同；在Z/5Z中[3][4]=[12]=[2]。','A ring can have zero divisors; cancellation by a nonzero element is not universally valid.','环可能有零因子，非零元不能普遍约去。',['Compute 3×4 modulo 5.','模5计算3×4。',2],['Compute 2×3 modulo 6.','模6计算2×3。',0,'6 is congruent to zero modulo 6, despite nonzero factors.','6模6为零，两个因子却非零。']);
R('M14.06','多项式环与域','field;irreducible polynomial;extension quotient','域;不可约多项式;扩域商结构','A field is a commutative ring where every nonzero element has a multiplicative inverse. Over a field, quotienting by an irreducible polynomial gives a field.','域是每个非零元都可乘法求逆的交换环；域上按不可约多项式取商得到域。','In F₂[x]/(x²+x+1), let α=[x]. Then α²=α+1 and α(α+1)=1. The four elements are 0,1,α,α+1.','F₂[x]/(x²+x+1)中令α=[x]，α²=α+1且α(α+1)=1；元素为0、1、α、α+1。','Irreducibility depends on the coefficient field. A polynomial with no root is irreducible only automatically in degrees two or three.','不可约性依系数域；无根只对二、三次多项式自动推出不可约。',['How many elements are in the example field?','例中域有几个元素？',4],['What is α(α+1)?','α(α+1)是多少？',1]);
F('M15','Structure theory explains which algebraic objects can exist and how smaller pieces fit together. Finite-group counting constrains subgroup sizes but does not replace the group axioms. Modules generalize vector spaces by allowing scalars from a ring, where division may fail. Field extensions treat one field as a vector space over another, making degree a dimension. Automorphisms preserve algebraic relations and reveal symmetries among roots. Galois theory connects intermediate fields to subgroups only under precise normality and separability hypotheses. Keep examples small enough to calculate directly, and distinguish a theorem about all objects from a classification that applies only under its stated assumptions.','结构理论说明代数对象如何存在和拼合。有限群计数限制子群大小，却不取代群公理。模把标量从域推广到环，因此除法可能失败。域扩张把大域视为小域上的向量空间，次数就是维数。自同构保持代数关系，揭示根的对称性。伽罗瓦理论在正规与可分条件下连接中间域与子群。应计算小实例，并区分普遍定理与仅适用于指定假设的分类。','abstract');
R('M15.01','有限群结构与西罗定理','p-subgroup;Sylow subgroup;conjugacy','p子群;西罗子群;共轭','If p^k is the largest p-power dividing |G|, Sylow p-subgroups have size p^k. Their number divides |G|/p^k and is 1 modulo p.','p^k为群阶中最大p幂时，西罗p子群阶p^k；其个数整除剩余因子且模p余1。','For |G|=15, the number of Sylow 5-subgroups divides 3 and is 1 mod 5, forcing 1. Hence that subgroup is normal.','群阶15时，西罗5子群个数整除3且模5余1，只能是1，因此正规。','The congruence and divisibility conditions are both required.','同余与整除条件须同时使用。',['Find the Sylow 5-subgroup order.','西罗5子群阶多少？',5],['Find its number for a group of order 15.','15阶群中这样的子群几个？',1]);
R('M15.02','模与线性算子','module;torsion;operator polynomial','模;挠元;算子多项式','A module allows ring scalars with vector-space-like distributive laws. Torsion occurs when a nonzero scalar annihilates a nonzero element.','模允许环标量并满足类似向量空间的分配规律；非零标量消去非零元素时出现挠。','Z/6Z is a Z-module. Its element [2] is killed by 3, since 3[2]=[6]=0; its additive order is 3.','Z/6Z是Z模，[2]被3消去，因为3[2]=0，其加法阶3。','A module need not have a basis; vector-space dimension arguments do not transfer automatically.','模未必有基，向量空间维数论证不能直接照搬。',['What smallest positive scalar kills [2] modulo 6?','模6中消去[2]的最小正标量多少？',3],['How many elements are in Z/6Z?','Z/6Z有几个元素？',6]);
R('M15.03','域扩张','extension degree;minimal polynomial;tower law','扩张次数;最小多项式;塔式定理','An algebraic element satisfies a polynomial over the base field. Its minimal polynomial degree equals the dimension of the simple extension.','代数元满足基域上的多项式，其最小多项式次数等于简单扩张维数。','Q(√2) has basis 1,√2 over Q, degree 2. Every element is a+b√2; multiplying uses (√2)²=2.','Q(√2)在Q上基为1、√2，次数2；每个元素为a+b√2，乘法用(√2)²=2。','A spanning description requires proving independence as well as closure.','给出张成还需证明无关性与封闭性。',['Find [Q(√2):Q].','[Q(√2):Q]多少？',2],['Find the rational part of (1+√2)².','(1+√2)²的有理部分多少？',3,'Expansion gives 3+2√2.','展开为3+2√2。']);
R('M15.04','有限域','prime power;Frobenius map;cyclic multiplicative group','素数幂;弗罗贝尼乌斯映射;乘法循环群','A finite field has p^n elements for a prime p. Its nonzero elements form a cyclic multiplicative group of size p^n−1.','有限域大小为素数幂p^n；非零元素组成大小p^n−1的乘法循环群。','In F₅, successive powers of 2 are 2,4,3,1, so 2 generates all four nonzero elements.','F₅中2的连续幂为2、4、3、1，生成四个非零元素。','Integers modulo a composite number form a ring, generally not a field.','合数模整数一般只是环而不是域。',['Find the multiplicative order of 2 in F₅.','F₅中2的乘法阶多少？',4],['How many nonzero elements does F₈ have?','F₈有几个非零元素？',7,'8−1=7.','8−1=7。']);
R('M15.05','伽罗瓦对应','automorphism;fixed field;subgroup reversal','自同构;不动域;包含反转','For a finite Galois extension, intermediate fields correspond to automorphism subgroups with inclusion reversed. Larger subgroups fix smaller fields.','有限伽罗瓦扩张的中间域与自同构子群反向对应，较大子群固定较小域。','Q(√2)/Q has two automorphisms: √2↦√2 and √2↦−√2. The full group fixes exactly Q.','Q(√2)/Q有两个自同构，把√2分别送到自身或相反数；全群恰固定Q。','Without normality and separability, the full correspondence need not hold.','缺少正规性与可分性，完整对应未必成立。',['How many automorphisms are in the example group?','例中自同构群几个元素？',2],['What is the image of 2 under either automorphism?','两种自同构都把2映到多少？',2,'Base-field rational numbers are fixed.','基域有理数保持不变。']);
R('M15.06','可解性与应用','solvable group;radicals;constructibility','可解群;根式;可作图性','In characteristic zero, solvability of a polynomial by radicals is controlled by solvability of its Galois group. Straightedge-compass constructions correspond to towers of quadratic extensions.','特征零中多项式根式可解性由伽罗瓦群可解性控制；尺规作图对应二次扩张塔。','√2 has degree 2 over Q and is constructible as the diagonal of a unit square. The real cube root of 2 has degree 3 and is not constructible from a unit segment.','√2次数2，可由单位正方形对角线作出；实立方根2次数3，不能从单位线段尺规作出。','A degree that is a power of two is necessary for constructibility, not sufficient by itself.','次数为2的幂是可作图的必要条件，本身不充分。',['Find the degree of √2 over Q.','√2在Q上的次数多少？',2],['Find the degree of the real cube root of 2 over Q.','实立方根2在Q上的次数多少？',3]);
F('M16','Number theory studies the structure of integers under divisibility. Euclidean division writes a=bq+r with a controlled remainder, and repeated division computes a greatest common divisor. Congruence replaces equality by equality of remainders, so every operation must respect the modulus. Inverses exist only for residue classes coprime to the modulus; cancellation without this condition can fail. Prime factorization converts many divisibility problems into exponent comparisons. Constructive proofs should give an actual integer or algorithm, while impossibility proofs often use modular obstructions or infinite descent. Check zero, negative values, and the modulus-one convention when applying a general formula.','数论研究整数的整除结构。欧氏除法写a=bq+r并控制余数，反复除法求最大公因数。同余以余数相等代替等号，运算须与模相容。逆元仅对与模互素的类存在，否则约分会失败。素因数分解把许多整除问题变成指数比较。构造证明须给实际整数或算法，不可能性常用同余障碍或无限递降。应用公式要检查零、负数与模一约定。','discrete');
R('M16.01','整除与欧几里得算法','divisor;greatest common divisor;Bezout identity','因数;最大公因数;贝祖等式','a divides b when b=ak for an integer k. gcd(a,b)=gcd(b,a mod b) because both pairs have identical common divisors.','b=ak且k为整数时a整除b；gcd(a,b)=gcd(b,a mod b)，因为两对公因数相同。','48=18×2+12,18=12+6,12=6×2, so gcd(48,18)=6. Back substitution gives 6=3×18−48.','48=18×2+12，18=12+6，12=6×2，故最大公因数6；回代得6=3×18−48。','A gcd is chosen nonnegative; divisibility is not ordinary real-number division.','最大公因数取非负；整除不等于一般实数除法。',['Find gcd(48,18).','求gcd(48,18)。',6],['Find lcm(48,18).','求lcm(48,18)。',144,'48×18/6=144.','48×18÷6=144。']);
R('M16.02','同余与模逆元','congruence;unit residue;linear congruence','同余;可逆剩余类;线性同余','a≡b mod m means m divides a−b. An inverse of a exists exactly when gcd(a,m)=1.','a≡b mod m表示m整除a−b；a存在逆元当且仅当gcd(a,m)=1。','Modulo 7, 3×5=15≡1, so 3⁻¹=5. Solving 3x≡4 gives x≡5×4≡6.','模7下3×5≡1，因此3逆为5；3x≡4给x≡5×4≡6。','Dividing a congruence by a nonunit can change the modulus and solution count.','除以不可逆元可能改变模数与解数。',['Find inverse of 3 modulo 7.','3模7的逆多少？',5],['Solve 3x≡4 mod 7 in 0≤x<7.','0≤x<7解3x≡4 mod 7。',6]);
R('M16.03','素数与算术函数','unique factorization;Euler phi;divisor count','唯一分解;欧拉函数;因数个数','Every positive integer above one has a unique prime factorization. For n=∏p_i^a_i, divisor count is ∏(a_i+1), and φ(n)=n∏(1−1/p_i).','大于1的正整数有唯一素分解；约数个数为∏(a_i+1)，φ(n)=n∏(1−1/p_i)。','12=2²×3 gives divisor count (2+1)(1+1)=6 and φ(12)=12×1/2×2/3=4.','12=2²×3，约数数(2+1)(1+1)=6，φ(12)=4。','One is neither prime nor composite; prime-factor products use distinct primes where indicated.','1既非素数也非合数；相关乘积须按要求只取互异素因子。',['Find the number of positive divisors of 12.','12有几个正因数？',6],['Find φ(12).','φ(12)多少？',4]);
R('M16.04','费马、欧拉与中国剩余定理','Euler theorem;coprime moduli;CRT construction','欧拉定理;互素模数;中国剩余构造','If gcd(a,m)=1, a^φ(m)≡1 mod m. Pairwise coprime moduli allow a unique combined residue modulo their product.','gcd(a,m)=1时a^φ(m)≡1；两两互素模数给模乘积下唯一合并剩余类。','x≡2 mod 3 and x≡3 mod 5 combine to x≡8 mod 15: 8 has both required remainders.','x≡2 mod 3与x≡3 mod 5合为x≡8 mod 15，8满足两余数。','For noncoprime moduli, compatibility requires residues agreeing modulo the gcd.','模数不互素时，余数须模最大公因数相同。',['Find the least nonnegative combined solution.','求合并最小非负解。',8],['Find its period.','解的周期多少？',15]);
R('M16.05','丢番图方程','integer solution;gcd obstruction;parameterization','整数解;最大公因数障碍;参数化','ax+by=c has integer solutions exactly when gcd(a,b) divides c. One solution generates a family by adding b/g to x and subtracting a/g from y.','ax+by=c有整数解当且仅当gcd(a,b)整除c；一解可沿(b/g,−a/g)生成解族。','For 3x+5y=1, (x,y)=(2,−1) works. All integer solutions are x=2+5t,y=−1−3t.','3x+5y=1的一解为(2,−1)，全部整数解为x=2+5t、y=−1−3t。','Real solvability says little about integer solvability; a parameter must be integer.','实数可解不代表整数可解，参数须取整数。',['For t=1, find x.','t=1时x多少？',7,'2+5=7.','2+5=7。'],['For t=1, find y.','t=1时y多少？',-4,'−1−3=−4.','−1−3=−4。']);
R('M16.06','阶与二次剩余','multiplicative order;quadratic residue;Euler criterion','乘法阶;二次剩余;欧拉判别','The order of a unit modulo m is the least positive k with a^k≡1. A quadratic residue is a residue represented by a square.','模m单位的阶为使a^k≡1的最小正k；二次剩余是可表示为平方的剩余类。','Modulo 7, powers of 2 are 2,4,1, so its order is 3. Nonzero squares are 1,2,4.','模7下2的幂为2、4、1，所以阶3；非零平方剩余为1、2、4。','Order is defined only for units; Euler criterion assumes an odd prime modulus.','阶仅对可逆元定义；欧拉判别要求奇素数模。',['Find the order of 2 modulo 7.','2模7的阶多少？',3],['How many nonzero quadratic residues modulo 7?','模7非零二次剩余几个？',3]);
F('M17','Combinatorics counts finite structures by explaining how each structure is built or represented. The sum rule requires disjoint cases; the product rule requires a sequence of choices whose available counts are correctly conditioned. A bijection proves two counts equal by giving reversible maps, while double counting describes the same set of incidences in two ways. Recurrences classify objects by their final step or first distinguished part. Generating functions encode choices as exponents and counts as coefficients. Before calculating, specify whether order matters, repetition is allowed, and labels distinguish objects; changing any of these conventions changes the problem.','组合数学通过结构的构造或表示来计数。加法规则要求情况互斥，乘法规则要求正确考虑逐步选择数量。双射以可逆映射证明计数相等，双重计数从两种角度数同一关联集合。递推按最后一步或第一个特殊部分分类；生成函数以指数编码选择、系数编码个数。计算前须说明顺序、重复和标签是否重要，任一约定改变都可能改变问题。','discrete');
R('M17.01','加法与乘法原理','disjoint cases;sequential choice;permutation','互斥情况;逐步选择;排列','Add counts for disjoint alternatives; multiply counts for successive choices with fixed available counts.','互斥选择用加法，逐步且选择数固定时用乘法。','Three shirts and four trousers make 3×4=12 outfits. Choosing two different books in order from five gives 5×4=20.','3件上衣4条裤子有12种搭配；5本书有序选不同两本有20种。','If cases overlap, adding double counts their intersection.','情况重叠时相加会重复计算交集。',['How many outfits in the example?','例中搭配几种？',12],['How many ordered two-book choices?','有序选两书几种？',20]);
R('M17.02','双射与双重计数','bijection;incidence;handshaking','双射;关联;握手定理','A bijection pairs objects uniquely in both directions. Double counting equates two ways to enumerate one collection of incidences.','双射双向唯一配对；双重计数把同一关联集合的两种计数相等。','In a graph, each edge contributes two endpoint incidences. Thus sum of degrees=2E; degree sum 18 implies 9 edges.','图中每边贡献两个端点关联，度数和=2E；度数和18则9条边。','A proposed bijection needs both injectivity and surjectivity, not just a plausible rule.','双射须证单射与满射，不能只给看似合理的规则。',['A graph has degree sum 18. Find its edge count.','度数和18的图几条边？',9],['For 7 edges, find degree sum.','7条边的度数和多少？',14,'Each edge contributes two: 2×7=14.','每边贡献2，2×7=14。']);
R('M17.03','二项式系数与恒等式','combination;Pascal recurrence;binomial theorem','组合数;帕斯卡递推;二项式定理','C(n,k) counts unordered k-subsets. Splitting subsets by whether a fixed element is included gives C(n,k)=C(n−1,k)+C(n−1,k−1).','C(n,k)数无序k子集，按固定元素是否入选得到帕斯卡递推。','Choose two of five people: 5×4 ordered choices count each pair twice, so C(5,2)=10. All subsets number 2⁵=32.','5人选2人，20种有序选择每对重复两次，因此10种；全部子集为2⁵=32。','Binomial coefficients count subsets, not ordered arrangements.','组合数计子集，不计有序排列。',['Find C(5,2).','C(5,2)多少？',10],['How many subsets does a five-element set have?','五元素集合有几个子集？',32]);
R('M17.04','抽屉原理与容斥','pigeonhole;overlap;inclusion-exclusion','抽屉原理;交叠;容斥','More objects than boxes force a shared box. For two sets, union size is |A|+|B|−|A∩B|.','物体多于盒子必有同盒；两集合并大小=两大小之和减交集。','Among 13 people, two share a birth month. If 12 students study French, 9 German, and 4 both, their union has 17 students.','13人中必有两人同出生月；12人学法语、9人德语、4人都学，并集17人。','The pigeonhole conclusion guarantees existence, not which objects collide.','抽屉原理保证存在，不指出具体哪个碰撞。',['Find the language union count.','语言并集人数多少？',17],['What minimum people force a shared birth month?','至少几人必有同出生月？',13]);
R('M17.05','递推、卡特兰数与斯特林数','Catalan decomposition;set partition;initial condition','卡特兰分解;集合划分;初值','Catalan objects split at a first matching pair, giving C_n=ΣC_iC_(n−1−i), C₀=1. Stirling numbers S(n,k) count partitions into k nonempty unlabeled blocks.','卡特兰对象按首个匹配对分解，C_n=ΣC_iC_(n−1−i)，C₀=1；S(n,k)计划成k个非空无标号块。','Balanced parentheses with three pairs number C₃=C₀C₂+C₁C₁+C₂C₀=2+1+2=5. For three labeled objects, S(3,2)=3.','三对合法括号数C₃=2+1+2=5；三个有标号对象分两非空块有3种。','Set-partition blocks are unordered; ordering blocks introduces an extra factor k!.','集合划分的块无序，若给块排序会多k!倍。',['Find C₃.','C₃多少？',5],['Find S(3,2).','S(3,2)多少？',3]);
R('M17.06','生成函数与极值计数','coefficient product;extremal bound;construction','系数乘积;极值界;构造','Multiply generating functions to combine independent contributions to a total size. An extremal result needs both a bound and a construction reaching it when sharpness is claimed.','生成函数相乘组合独立大小贡献；声称极值精确时，既须界也须达到界的构造。','For two choices each in {0,1,2}, (1+x+x²)² has x² coefficient 3, representing (0,2),(1,1),(2,0).','两个选择各为0、1、2，(1+x+x²)²的x²系数3，对应(0,2)、(1,1)、(2,0)。','An upper bound alone does not establish the exact maximum.','只有上界不能确立精确最大值。',['Find that x² coefficient.','该x²系数多少？',3],['How many total ordered choices exist?','全部有序选择共几种？',9,'Three choices for each of two positions gives 3²=9.','两位置各三选择，3²=9。']);
F('M18','Graph theory models relationships with vertices and edges. Specify whether a graph is directed, simple, weighted, or allows repeated edges before applying a theorem. A walk may repeat vertices and edges; paths and cycles impose additional restrictions. Degree counts local connections, while connectivity and cuts describe global structure. Trees provide minimal connected frameworks and support recursive arguments. Existence theorems for trails, matchings, or colorings require their full hypotheses, not just suggestive examples. When translating an applied problem, explain what each vertex and edge represents and verify that the graph property exactly matches the original requirement.','图论以顶点和边建模关系。应用定理前应说明有向、简单、带权或重边等约定。游走可重复点边，路径与圈有额外限制。度数描述局部连接，连通性与割描述整体。树是最小连通框架，便于递归论证。迹、匹配或着色存在定理要求全部假设。应用建模须解释点边含义，并核对图性质是否准确对应原要求。','discrete');
R('M18.01','图、游走与连通','adjacency;path;component','邻接;路径;连通分量','Vertices are adjacent when joined by an edge. Connectivity means every pair can be joined by a path; components are maximal connected pieces.','边相连的顶点邻接；任意两点有路径则连通，连通分量为极大连通部分。','With vertices 1,2,3,4 and edges 12,23, the components are {1,2,3} and {4}. Degrees are 1,2,1,0.','点1、2、3、4，边12、23时，分量为{1,2,3}与{4}，度为1、2、1、0。','An isolated vertex is still a component. Directed reachability differs from undirected connectivity.','孤立点也是分量；有向可达性不同于无向连通。',['How many components are in the example?','例中几个分量？',2],['What is vertex 2 degree?','顶点2度数多少？',2]);
R('M18.02','树与生成结构','tree;spanning tree;leaf','树;生成树;叶子','A tree is connected and acyclic. A finite tree with n vertices has n−1 edges and a unique path between each pair.','树连通且无环；n点有限树有n−1边，任意两点间路径唯一。','A spanning tree of a connected eight-vertex graph uses seven edges. Adding one extra edge creates exactly one cycle.','8点连通图的生成树有7边，加一条边恰形成一个圈。','Having n−1 edges alone does not imply a tree without connectivity or acyclicity.','只有n−1条边而无连通或无环条件不能保证树。',['How many edges in an eight-vertex tree?','8点树几条边？',7],['How many cycles are created by one added edge?','添加一条非树边产生几个圈？',1]);
R('M18.03','欧拉与哈密顿问题','Euler trail;Hamilton cycle;degree parity','欧拉迹;哈密顿圈;度奇偶',
'A Euler trail uses every edge exactly once; a Hamilton cycle visits every vertex exactly once before returning.','欧拉迹恰用每边一次，哈密顿圈返回前恰过每点一次。','A connected graph has an Euler circuit when all degrees are even. A simple cycle on five vertices has five edges and degree 2 at every vertex.','连通图所有度偶时有欧拉回路；五顶点简单圈有五边，各点度2。','Euler conditions do not solve Hamilton existence, which is a different problem.','欧拉条件不能解决哈密顿存在性。',['Find each degree in a five-cycle.','五圈各点度多少？',2],['How many edges must its Euler circuit use?','其欧拉回路用几条边？',5]);
R('M18.04','匹配与霍尔定理','matching;neighbor set;Hall condition','匹配;邻居集;霍尔条件','A matching uses no vertex twice. A bipartite graph matches every left vertex exactly when every left subset S has at least |S| neighbors.','匹配不重复用顶点；二分图能覆盖全部左点，当且仅当每个左子集S的邻居至少|S|个。','If three applicants collectively have only two available jobs, Hall fails for that subset and at most two can be matched.','三名申请者总共只有两个可选岗位，霍尔条件失败，最多匹配两人。','Checking only individual degrees is insufficient; every subset matters.','只检查单点度数不够，必须考虑所有子集。',['Three applicants have only two jobs. Maximum possible matched applicants?','三人只有两岗位，最多匹配几人？',2],['What neighbor count is necessary for a three-person subset?','三人子集至少需几个邻居？',3]);
R('M18.05','着色、平面图与极值界','proper coloring;Euler formula;planar bound','正常着色;欧拉公式;平面界','A proper vertex coloring gives adjacent vertices different colors. A connected plane graph satisfies V−E+F=2, counting the outer face.','正常点着色使邻点异色；连通平面图满足V−E+F=2，包含外面。','A planar drawing of K₄ has V=4,E=6, hence F=4. All four pairwise adjacent vertices need four colors.','K₄的平面画法V=4、E=6，故F=4；四点两两邻接，需要四色。','The bound E≤3V−6 assumes a simple planar graph with V≥3.','E≤3V−6要求V≥3的简单平面图。',['Find K₄ face count.','K₄面数多少？',4],['Find its chromatic number.','其色数多少？',4]);
R('M18.06','图计数与概率构造','random graph;expectation;existence method','随机图;期望;存在性方法','If a nonnegative count has expectation below 1, some outcome has count 0. This can prove existence without constructing the desired graph explicitly.','非负整数计数期望小于1时，某结果计数为0，可不显式构造地证明存在。','In G(4,1/2), each of six possible edges appears with probability 1/2. Expected edge count is 3 by linearity, regardless of how the sum is grouped.','G(4,1/2)六条可能边各以1/2出现，按期望线性性，期望边数3。','Expected structure need not itself occur as an entire graph; expectation is an average.','期望描述平均，不代表整个“平均结构”必然出现。',['Find expected edge count in G(4,1/2).','G(4,1/2)期望边数多少？',3],['How many possible edges does a simple four-vertex graph have?','简单四点图最多几条边？',6,'Choose an unordered vertex pair: C(4,2)=6.','选无序点对C(4,2)=6。']);
F('M19','Probability assigns weights to possible outcomes and adds the weights of disjoint events. Begin by specifying the experiment and sample space; outcomes are not automatically equally likely just because they can be listed. Conditioning restricts attention to an event and renormalizes its probability. Independence is a mathematical relation, not merely the absence of an obvious connection. Random variables convert outcomes into numerical values, allowing expectation and variance to describe averages and spread. Linearity of expectation needs no independence, but many product formulas do. Interpret every result as a statement within the model, and check that probabilities remain between zero and one.','概率为可能结果赋权，并对互斥事件相加。先说明试验与样本空间，列出结果不意味着等可能。条件概率限制到某事件并重新归一。独立是数学关系，不只是看不出联系。随机变量把结果变成数，期望和方差描述平均与波动。期望线性性不要求独立，许多乘积公式却要求。所有结果都在模型之内解释，并检查概率在零与一之间。','stats');
R('M19.01','样本空间与事件','sample space;event;complement','样本空间;事件;补事件','An event is a subset of possible outcomes. Its complement contains all outcomes outside it; their probabilities sum to one.','事件是可能结果的子集；补事件含其余结果，二者概率和为一。','A fair six-sided die has six equal outcomes. Even results {2,4,6} have probability 3/6=1/2; rolling 6 has probability 1/6.','公平六面骰六结果等可能；偶数{2,4,6}概率1/2，掷6概率1/6。','Uniform counting applies only after equal likelihood is justified.','只有确认等可能后才能用均匀计数。',['Find probability of an even result.','偶数结果概率多少？',0.5],['Find probability of a six.','掷6概率多少？',1/6]);
R('M19.02','条件概率与贝叶斯法则','conditioning;Bayes rule;base rate','条件化;贝叶斯公式;基率','P(A|B)=P(A∩B)/P(B) when P(B)>0. Bayes reverses conditioning by combining likelihood with the prior probability.','P(B)>0时P(A|B)=P(A∩B)/P(B)；贝叶斯用似然与先验逆转条件。','Among 100 objects, 20 are red and 10 are both red and large. Given red, probability of large is 10/20=1/2.','100物体中20红，10又红又大；已知红则大概率10/20=1/2。','P(A|B) and P(B|A) generally differ; denominators describe different populations.','P(A|B)与P(B|A)通常不同，分母对应不同总体。',['Find P(large|red).','求已知红时大的概率。',0.5],['Find P(red and large).','又红又大概率多少？',0.1,'Ten of 100 objects: 10/100=0.1.','100个中10个，概率0.1。']);
R('M19.03','独立性与随机变量','independence;distribution;indicator','独立性;分布;指示变量','Independent events satisfy P(A∩B)=P(A)P(B). A random variable assigns a number to each outcome, and its distribution collects probabilities of values.','独立事件满足交概率等于概率乘积；随机变量给每结果赋数，分布收集各值概率。','For two independent fair coins, the number of heads has probabilities 1/4,1/2,1/4 at 0,1,2.','两枚独立公平硬币的正面数在0、1、2处概率为1/4、1/2、1/4。','Disjoint positive-probability events are not independent: their intersection probability is zero.','正概率互斥事件不独立，因为交概率零。',['Find probability of two heads.','两个正面概率多少？',0.25],['Find probability of exactly one head.','恰一个正面概率多少？',0.5]);
R('M19.04','期望与方差','weighted mean;variance;linearity','加权平均;方差;线性性','E[X]=ΣxP(X=x). Variance is E[(X−E[X])²]=E[X²]−E[X]² and measures squared spread.','E[X]=ΣxP(X=x)，方差为E[(X−E[X])²]=E[X²]−E[X]²，衡量平方波动。','A fair Bernoulli variable is 0 or 1 equally likely. Its mean is 1/2, second moment 1/2, and variance 1/2−1/4=1/4.','公平伯努利变量等概率为0或1，均值1/2、二阶矩1/2、方差1/4。','E[X²] is generally not E[X]². Variances add for independent variables, not all variables.','E[X²]通常不等于E[X]²；方差可加要求如独立性等条件。',['Find the Bernoulli mean.','该伯努利均值多少？',0.5],['Find its variance.','方差多少？',0.25]);
R('M19.05','常见离散分布','binomial;geometric;Poisson','二项;几何;泊松','Binomial counts successes in fixed independent equal-probability trials. Geometric counts waiting trials; Poisson models counts with a specified rate under suitable assumptions.','二项计固定次数独立同概率试验成功数，几何计等待次数，泊松在适用假设下按率建模计数。','For Binomial(n=10,p=0.3), mean np=3 and variance np(1−p)=2.1.','二项n=10、p=0.3时均值3，方差2.1。','Define whether geometric waiting includes the successful trial; conventions change the support and mean.','几何等待是否包含成功次须定义，约定改变支撑与均值。',['Find the binomial mean.','该二项均值多少？',3],['Find its variance.','其方差多少？',2.1]);
R('M19.06','集中、随机游走与应用','Markov bound;Chebyshev bound;random walk','马尔可夫界;切比雪夫界;随机游走','For nonnegative X, P(X≥a)≤E[X]/a. Chebyshev bounds deviations by Var(X)/a². A random walk adds successive random increments.','X非负时P(X≥a)≤E[X]/a；切比雪夫以Var(X)/a²界定偏离概率；随机游走累加随机增量。','Ten independent ±1 fair steps have mean displacement 0 and variance 10. Chebyshev gives P(|S|≥5)≤10/25=0.4.','十步独立公平±1游走均值0、方差10，切比雪夫给P(|S|≥5)≤0.4。','A bound may be loose; values above one should be capped by the trivial probability bound.','界可能较松，大于1时应用概率最多1的平凡界。',['Find variance after ten steps.','十步后方差多少？',10],['Find the stated deviation bound.','所述偏离界多少？',0.4]);
F('M20','Continuous probability uses densities whose integrals, rather than point values, give probabilities. A model describes a population or data-generating process; statistics uses observed samples to learn about that model. Sampling variability remains even with careful measurement. Separate parameters, which characterize the model, from estimators, which are functions of the sample. Confidence procedures and hypothesis tests have repeated-sampling interpretations and require their assumptions to be checked. Randomization, representative sampling, and residual diagnostics address different sources of error. State uncertainty alongside an estimate, and distinguish association, predictive usefulness, and causal interpretation instead of treating them as interchangeable.','连续概率用密度的积分而非点值给概率。模型描述总体或数据生成过程，统计从样本了解模型；即使测量仔细，抽样波动仍存在。参数描述模型，估计量是样本函数，须区分。置信程序与检验有重复抽样解释并依赖假设。随机化、代表性抽样、残差诊断处理不同误差。估计应附不确定度，并区分关联、预测用途和因果解释。','stats');
R('M20.01','密度与分布函数','density;CDF;integral probability','密度;累积分布函数;积分概率','A density is nonnegative and integrates to one. F(x)=P(X≤x) is the cumulative distribution; density values themselves can exceed one.','密度非负且积分为一；F(x)=P(X≤x)是累积分布，密度值本身可超过一。','Uniform X on [0,4] has density 1/4. Probability of [1,3] is length 2 times density 1/4, giving 1/2.','[0,4]均匀X密度1/4，[1,3]概率为长度2乘密度1/4，得1/2。','For a continuous density, a single exact point has probability zero, not density f(x).','连续密度下单点概率零，不是密度f(x)。',['Find P(1≤X≤3).','求P(1≤X≤3)。',0.5],['Find F(1).','F(1)多少？',0.25,'Length 1 divided by total length 4.','长度1除总长4。']);
R('M20.02','联合分布与变量变换','joint density;marginal;Jacobian','联合密度;边缘分布;雅可比因子','Marginal densities integrate out unwanted variables. A change of variables requires the absolute inverse Jacobian determinant to preserve total probability.','边缘密度积分消去其他变量；变换要乘逆雅可比行列式绝对值保持总概率。','If X is uniform on [0,1] and Y=2X+3, Y is uniform on [3,5] with density 1/2. Its mean is 4.','X在[0,1]均匀，Y=2X+3则在[3,5]均匀，密度1/2，均值4。','When a transformation is many-to-one, sum contributions from every inverse branch.','变换多对一时需把每个逆分支的贡献相加。',['Find Y density inside its interval.','Y区间内部密度多少？',0.5],['Find E[Y].','E[Y]多少？',4]);
R('M20.03','大数定律与中心极限定理','sample mean;standard error;normal limit','样本均值;标准误;正态极限','For independent identically distributed observations under appropriate moment conditions, the mean stabilizes and standardized fluctuations approach a normal law.','独立同分布观察在适当矩条件下，均值稳定，标准化波动趋近正态。','With population standard deviation 12 and n=36 independent observations, the sample mean has standard error 12/√36=2.','总体标准差12，独立样本n=36时，均值标准误12/√36=2。','The central limit theorem does not say the original observations become normally distributed.','中心极限定理不表示原始观察本身变成正态分布。',['Find that standard error.','标准误多少？',2],['For n=144 with the same deviation, find standard error.','同标准差n=144时标准误多少？',1,'12/√144=1.','12/√144=1。']);
R('M20.04','估计与置信区间','estimator;coverage;margin of error','估计量;覆盖率;误差范围','A confidence interval is generated by a procedure with stated long-run coverage, under assumptions. It is not a posterior probability for a fixed parameter.','置信区间由在假设下具有长期覆盖率的程序生成，不是固定参数的后验概率。','A normal-model estimate 50 with standard error 2 gives approximate 95% interval 50±1.96×2, or [46.08,53.92].','正态模型估计50、标准误2，近似95%区间为50±1.96×2，即[46.08,53.92]。','Unknown variance and small samples may require t rather than normal critical values.','未知方差小样本可能需t临界值而非正态值。',['Find the lower endpoint.','下端点多少？',46.08],['Find the upper endpoint.','上端点多少？',53.92]);
R('M20.05','假设检验与实验设计','null hypothesis;p-value;type I error','零假设;p值;第一类错误','A p-value is the null-model probability of results at least as extreme by a specified statistic. Significance level controls a procedure’s type I error under its assumptions.','p值是在零模型下按指定统计量出现至少同样极端结果的概率；显著性水平在假设下控制第一类错误。','For a z statistic, estimate 14 against null mean 10 with standard error 2 gives z=(14−10)/2=2. Directionality must be chosen in advance.','估计14、零均值10、标准误2时z=2；单侧或双侧须预先确定。','A p-value is not the probability that the null hypothesis is true.','p值不是零假设为真的概率。',['Find the stated z statistic.','所述z统计量多少？',2],['Under nominal 5% error, expected false rejections among 100 true null tests?','100个真零假设检验名义误拒率5%，期望误拒几次？',5,'Linearity gives 100×0.05=5; dependence affects spread.','期望线性性给5，依赖性影响波动。']);
R('M20.06','回归、模型检查与重抽样','regression residual;bootstrap;validation','回归残差;自助法;验证','Regression models a conditional relationship. Residuals expose systematic errors; bootstrap resamples observed data to approximate sampling variability under suitable assumptions.','回归建模条件关系；残差揭示系统误差，自助法在适用假设下重抽观测近似抽样波动。','For prediction y=2x+1, x=3 predicts 7. Observing 9 gives residual 2 and squared error 4.','预测y=2x+1在x=3给7，观察9产生残差2、平方误差4。','Resampling cannot repair an unrepresentative sample. Regression association does not establish causation.','重抽样不能修复不具代表性的样本，回归关联不证明因果。',['Find the residual.','残差多少？',2],['Find squared error.','平方误差多少？',4]);
F('M21','Inequality proofs compare quantities while keeping domains and equality conditions visible. Start by identifying signs, symmetry, homogeneity, and any fixed sum or product. A valid inequality may reverse when multiplied by a negative value, and taking powers may require nonnegative inputs. Standard inequalities compress reusable arguments, but selecting substitutions is part of the proof: every term must satisfy the theorem’s hypotheses. Track equality through every step to see whether a proposed bound can actually be attained. Numerical trials can locate likely extremizers or counterexamples, but they do not establish a bound for all permitted real values.','不等式证明要保留定义域与等号条件。先识别符号、对称性、齐次性和固定和积约束。乘负数可能反向，乘方可能要求非负。经典不等式压缩可复用论证，但替换的每个量须满足条件。逐步跟踪等号才能判断界是否可达。数值试验能寻找极值猜想或反例，却不能证明全部允许实数上的界。','algebra');
R('M21.01','序、等号与基本界','nonnegative square;equality case;sign condition','非负平方;等号条件;符号条件','For real x, x²≥0. Rearranging nonnegative squares yields many inequalities, and equality holds exactly when the squared expression vanishes.','实数平方非负，由此变形得许多不等式；等号恰在平方内表达式为零时成立。','(a−b)²≥0 gives a²+b²≥2ab. At a=3,b=1, the left side is 10, right side 6, and gap 4.','(a−b)²≥0给a²+b²≥2ab；a=3、b=1时左右10与6，差4。','Squaring an inequality with opposite-sign sides can change its meaning.','两边异号时平方不等式可能改变意义。',['Find the stated gap.','所述差多少？',4],['With b=5, what a gives equality?','b=5时a多少取等？',5,'Equality requires a=b.','等号要求a=b。']);
R('M21.02','算术几何平均与加权形式','AM-GM;weights;equality','算术几何平均;权重;等号','For nonnegative a,b, (a+b)/2≥√ab, with equality at a=b. Weighted forms require nonnegative weights summing to one.','非负a、b满足(a+b)/2≥√ab，等号a=b；加权形式要求权重非负且和一。','If a+b=12, then ab≤36 because √ab≤6. Equality is reached at a=b=6.','a+b=12时√ab≤6，因此ab≤36，a=b=6取等。','Negative inputs are outside the real-valued geometric-mean hypothesis.','负输入不满足实几何平均的条件。',['Find the largest product for nonnegative sum 12.','非负数和12时积最大多少？',36],['Find the equality value of each input.','取等时每个数多少？',6]);
R('M21.03','柯西施瓦茨与赫尔德','dot-product bound;proportionality;Holder exponents','内积界;成比例;赫尔德指数','Cauchy-Schwarz states (Σa_ib_i)²≤(Σa_i²)(Σb_i²). Equality requires proportional vectors, including the zero cases.','柯西为(Σa_ib_i)²≤(Σa_i²)(Σb_i²)，等号要求成比例，含零向量情况。','For (1,2),(2,1), dot product 4 has square 16, while squared norms multiply to 5×5=25.','(1,2)、(2,1)内积4，平方16，平方范数乘积25。','Hölder uses conjugate exponents p,q>1 with 1/p+1/q=1; do not choose them independently.','赫尔德的p、q须大于1且倒数和一，不能独立任取。',['Find squared dot product in the example.','例中内积平方多少？',16],['Find the upper bound.','上界多少？',25]);
R('M21.04','凸性与詹森不等式','convex combination;Jensen;second derivative test','凸组合;詹森;二阶导判据','A convex function lies below chords. Jensen says f(Σw_ix_i)≤Σw_if(x_i) for nonnegative weights summing to one.','凸函数位于弦下；非负权重和一时f(Σw_ix_i)≤Σw_if(x_i)。','For f(x)=x², inputs 1,3 with equal weights give f(2)=4≤(1+9)/2=5.','f=x²对1、3等权，得f(2)=4≤5。','Concavity reverses Jensen. Convexity is needed on an interval containing all inputs.','凹函数反向；凸性须在包含全部输入的区间上成立。',['Find f of the mean.','均值代入f是多少？',4],['Find the mean of function values.','函数值平均多少？',5]);
R('M21.05','排序、磨光与代换','rearrangement;smoothing;constraint preservation','排序;磨光;保持约束','Rearrangement maximizes paired sums when two real sequences are similarly sorted. Smoothing replaces variables while preserving a constraint and controlling the objective.','排序不等式中两列同序使配对和最大；磨光替换变量时保留约束并控制目标。','Pair 1,3 with 2,4: same order gives 1×2+3×4=14, opposite order gives 1×4+3×2=10.','1、3与2、4配对，同序14，逆序10。','A smoothing step must prove the objective moves in the claimed direction.','磨光必须证明目标确按声称方向变化。',['Find same-order sum.','同序和多少？',14],['Find opposite-order sum.','逆序和多少？',10]);
R('M21.06','对称与几何不等式','symmetry;homogeneity;triangle constraints','对称性;齐次性;三角约束','A symmetric expression is unchanged by variable permutations. A homogeneous inequality can often be normalized because both sides scale equally.','对称式在变量置换下不变；齐次不等式两边同尺度变化，常可归一化。','For positive a,b,c with sum 3, AM-GM gives abc≤1. Equality is a=b=c=1; arbitrary positive scaling restores the general sum formula.','正a、b、c和3时，算几给abc≤1，等号各为1；缩放可恢复一般和公式。','Side lengths of a triangle obey extra inequalities; arbitrary positive triples need not describe triangles.','三角形边长还有三角不等式，任意正三元组未必可作三角形。',['Find the largest product when sum is 3.','和3时最大积多少？',1],['Find the largest product when sum is 6.','和6时最大积多少？',8,'Equal inputs are 2, giving 2³=8.','等号各2，积2³=8。']);
F('M22','Olympiad problem solving combines proof methods rather than selecting formulas by surface resemblance. Translate the statement into exact constraints, test small or extreme cases, and look for invariants, symmetry, divisibility, or a useful auxiliary object. Exploration may be informal, but the final proof must explain every case and justify that a construction meets the original conditions. When an approach fails, identify the specific obstruction instead of merely trying more algebra. Timed practice should be followed by reconstruction without the solution and by variations that change a hypothesis. A complete argument includes existence, uniqueness, or exhaustiveness whenever the question requests them.','竞赛解题组合证明方法，而非凭表面套公式。先把题意化为精确约束，试小值或极端情况，寻找不变量、对称、整除或辅助对象。探索可以非正式，最终证明必须涵盖全部情况并核对构造满足原条件。方法失败时应指出障碍，而不只是继续堆代数。限时练习之后应脱离答案重建，并改变假设迁移。题目要求存在、唯一或穷尽时，完整论证须分别证明。','discrete');
R('M22.01','代数与函数方程','special substitution;injectivity;regularity','特殊代入;单射性;正则性','A functional equation holds for all inputs in its stated domain. Special values can force identities, but real additive functions need regularity before concluding linearity.','函数方程对指定域所有输入成立；特殊值可迫出关系，但实加性函数需正则性才能推出线性。','On integers, f(m+n)=f(m)+f(n), f(1)=3 implies f(0)=0 and by repeated addition f(n)=3n, including negatives by additive inverses.','整数上加性且f(1)=3，则f(0)=0，重复相加得f(n)=3n，负整数由逆元处理。','The same integer argument does not establish f(x)=3x for every real x without additional assumptions.','整数论证不能无条件推广为所有实数f(x)=3x。',['Find f(4) in the integer example.','整数例中f(4)多少？',12,'Four additions of 3 give 12.','四次加3为12。'],['Find f(−2).','f(−2)多少？',-6,'f(−2)=−f(2)=−6.','f(−2)=−f(2)=−6。']);
R('M22.02','数论构造','modular obstruction;construction;descent','同余障碍;构造;递降','A construction must satisfy every divisibility condition. An impossibility proof can map every candidate to a smaller positive candidate, contradicting minimality.','构造须满足所有整除条件；不可能性可将每候选变成更小正候选，与最小性矛盾。','No square is 2 modulo 4: an integer is even or odd, and its square is respectively 0 or 1 modulo 4. Thus x²=4k+2 has no integer solution.','整数平方模4只能为0或1，因为偶奇两种情况分别平方；所以x²=4k+2无整数解。','A modular obstruction proves impossibility only when all candidate residues are covered.','同余障碍须覆盖全部候选余数才能证不可能。',['What is an odd square modulo 4?','奇数平方模4余多少？',1],['How many integer solutions can x²=4k+2 have for fixed integer k?','固定整数k时x²=4k+2有几个整数解？',0]);
R('M22.03','组合不变量与极值','coloring invariant;extremal choice;descent','染色不变量;极值选择;递降','Coloring can turn a geometric move into a conserved count. An extremal choice forces inequalities that arbitrary objects need not satisfy.','染色可把几何操作化为守恒计数；极值对象具有一般对象未必具备的不等关系。','Remove opposite corners from an 8×8 checkerboard. They have the same color, leaving 30 of one color and 32 of the other. Every domino covers one of each, so tiling is impossible.','8×8棋盘去掉对角两角，两角同色，剩两色30与32；每骨牌盖一黑一白，因此无法铺满。','The invariant must match the allowed tile orientation and shape.','不变量须与允许的铺块形状和方向相容。',['How many squares remain?','剩多少格？',62],['What is the color-count difference?','两色格数差多少？',2]);
R('M22.04','高等几何与反演','inversion;power;circle-line correspondence','反演;幂;圆线对应','Inversion of radius R sends a noncentral point P along its ray to P′ with OP·OP′=R². It is not a distance-preserving transformation.','半径R的反演把非中心点P沿射线映到P′，满足OP·OP′=R²，不保距离。','For R=2 and OP=8, OP′=4/8=1/2. Applying inversion again returns distance 8.','R=2、OP=8时OP′=4/8=1/2，再反演回8。','The center itself has no finite inverse; circles through the center correspond to lines not through it.','中心无有限像；过中心圆对应不过中心直线。',['Find OP′ in the example.','求例中OP′。',0.5],['With R=2 and OP=1, find OP′.','R=2、OP=1时OP′多少？',4,'R²/OP=4.','R²/OP=4。']);
R('M22.05','综合题与证明修复','case completeness;hidden division;counterexample','分类完备;隐含除法;反例','A repair identifies the earliest unsupported step and replaces it with a justified argument, rather than editing only the final answer.','修复证明要找最早无依据步骤并替换，而非只改答案。','From a²=b², concluding a=b misses a=−b. Factor (a−b)(a+b)=0, so both cases are required. For b=3 the possibilities are 3 and −3.','a²=b²直接推出a=b漏掉a=−b；分解(a−b)(a+b)=0须两种情况。b=3时a=±3。','A special counterexample exposes the gap but does not by itself provide a complete repaired theorem.','反例揭示漏洞，却不自动提供完整修正版定理。',['How many real a satisfy a²=9?','a²=9有几个实数a？',2],['Find their sum.','两解之和多少？',0,'3+(−3)=0.','3+(−3)=0。']);
R('M22.06','限时题组与反思重建','time allocation;proof reconstruction;variation','时间分配;证明重建;变式','After a timed attempt, reconstruct the decisive idea without looking, then alter a condition to test whether the argument depended on it.','限时尝试后应不看答案重建关键思想，再改一个条件测试依赖。','A sum of two odd integers is even: write 2r+1 and 2s+1, obtaining 2(r+s+1). Changing one summand to even instead gives an odd sum.','两奇数和为偶：写2r+1、2s+1，和2(r+s+1)；把其中一个改偶，和则为奇。','A remembered answer is weaker evidence than reconstructing the reason and handling a changed problem.','记住答案的证据弱于重建理由并解决变式。',['What is the remainder of an odd-plus-odd sum modulo 2?','奇数加奇数模2余多少？',0],['What is odd plus even modulo 2?','奇数加偶数模2余多少？',1]);
F('M23','Complex differentiability is stronger than differentiability in two real coordinates because the same difference quotient must work from every complex direction. Holomorphic functions are complex differentiable throughout an open neighborhood, and this local requirement creates powerful global consequences under appropriate domain assumptions. Contour integration depends on orientation and on singularities enclosed by a path. Cauchy formulas link values inside a region to boundary information, while Laurent expansions isolate the terms responsible for residues. Always identify the domain, branches of multivalued expressions, and locations of singularities before using a theorem or deforming a contour.','复可导比两个实坐标的可微更强，因为所有复方向差商须有同一极限。全纯要求在开邻域处处复可导，在适当区域假设下会产生强整体结论。围道积分依方向及包围奇点而定；柯西公式连接内部值与边界信息，洛朗展开分离留数相关项。使用定理或变形围道前，须明确区域、多值表达式的分支与奇点位置。','complex');
R('M23.01','复可微','complex derivative;holomorphic;directional test','复导数;全纯;方向检验','The complex derivative is lim[h→0](f(z+h)−f(z))/h with h approaching through all complex directions.','复导数要求h从所有复方向趋零时差商有共同极限。','For f(z)=z², the quotient is 2z+h, so f′(z)=2z. At z=1+i, derivative is 2+2i.','f=z²差商2z+h，故导数2z；z=1+i时为2+2i。','Real differentiability alone does not imply complex differentiability; conjugation fails the direction test.','实可微不推出复可微，共轭映射不满足方向检验。',['Find the real part of f′(1+i).','f′(1+i)实部多少？',2],['Find its imaginary coefficient.','虚部系数多少？',2]);
R('M23.02','柯西黎曼方程','real components;CR equations;sufficient regularity','实分量;柯西黎曼方程;充分正则性','For f=u+iv, complex differentiability implies u_x=v_y and u_y=−v_x. Continuous partial derivatives plus these equations locally are sufficient.','f=u+iv复可导推出u_x=v_y、u_y=−v_x；局部连续偏导加这些关系为充分条件。','For z², u=x²−y²,v=2xy, giving u_x=v_y=2x and u_y=−v_x=−2y.','z²中u=x²−y²、v=2xy，得到u_x=v_y=2x，u_y=−v_x=−2y。','Equations at a single point without adequate regularity need not imply local holomorphicity.','单点方程且缺正则性，未必推出局部全纯。',['For z² at (2,3), find u_x.','z²在(2,3)的u_x多少？',4,'2x=4.','2x=4。'],['Find u_y.','u_y多少？',-6,'−2y=−6.','−2y=−6。']);
R('M23.03','围道积分与柯西定理','parameterized contour;primitive;simply connected domain','参数围道;原函数;单连通域','Integrate f(z(t))z′(t) over a path. A holomorphic function on a simply connected domain has zero integral around closed contours there.','沿路积分f(z(t))z′(t)；单连通域内全纯函数沿域内闭围道积分为零。','For f(z)=z, primitive z²/2 makes the integral from 0 to 2 equal 2 along any path in the plane.','f=z原函数z²/2，使从0到2沿平面任意路径的积分都等于2。','The function 1/z is singular at zero; loops around zero cannot be contracted within its domain.','1/z在零奇异，绕零圈不能在其定义域内缩成点。',['Find ∫ from 0 to 2 of z dz.','求0到2的∫z dz。',2],['Find its integral around a closed circle.','z沿闭圆积分多少？',0,'A global primitive makes every closed integral zero.','存在整体原函数，所以闭积分零。']);
R('M23.04','解析展开','Taylor series;Laurent series;radius to singularity','泰勒级数;洛朗级数;奇点距离','Holomorphic functions have local convergent power series. Laurent series also allow negative powers on an annulus.','全纯函数局部有收敛幂级数，洛朗级数在圆环上还允许负幂。','For |z|<1, 1/(1−z)=1+z+z²+… . The nearest singularity at z=1 limits the expansion radius to 1.','|z|<1时1/(1−z)=1+z+z²+…，最近奇点1使收敛半径为1。','A series centered elsewhere has a different radius; real-axis behavior alone is insufficient.','换中心可能改变半径，仅实轴行为不够。',['Find the z⁴ coefficient.','z⁴系数多少？',1],['Find the convergence radius at zero.','零中心收敛半径多少？',1]);
R('M23.05','奇点与留数','isolated singularity;pole;residue','孤立奇点;极点;留数','The residue is the coefficient of (z−a)⁻¹ in a Laurent expansion. A positively oriented simple contour integral equals 2πi times enclosed residues.','留数是洛朗展开(z−a)⁻¹系数；正向简单围道积分等于2πi乘内部留数和。','For f(z)=3/(z−2)+1, the simple pole at 2 has residue 3. A contour enclosing only that pole has integral 6πi.','f=3/(z−2)+1在2有简单极点，留数3；仅包围它的围道积分6πi。','Residue is not generally the coefficient of the most singular term.','留数不一定是最奇异项的系数。',['Find the residue at 2.','2处留数多少？',3],['For 5/z²+7/z, find the residue at zero.','5/z²+7/z在零留数多少？',7,'The z⁻¹ coefficient is 7.','z⁻¹系数为7。']);
R('M23.06','共形映射与应用','angle preservation;nonzero derivative;Mobius map','保角;非零导数;莫比乌斯变换','A holomorphic map with nonzero derivative locally preserves oriented angles because its first-order action is complex multiplication.','全纯映射导数非零时局部保有向角，因为一阶作用为复数乘法。','Multiplication by 2i rotates by π/2 and scales lengths by 2. It sends 1+3i to −6+2i.','乘2i旋转π/2并放大2倍，将1+3i送到−6+2i。','At a zero derivative, local angle preservation can fail; global injectivity is an additional requirement.','导数为零处保角可能失败，整体单射是额外要求。',['Find the image real part.','像实部多少？',-6],['Find the length scale factor.','长度缩放倍数多少？',2]);
F('M24','Topology studies properties preserved by continuous deformation using open sets rather than a fixed measuring scale. A topology specifies which subsets are open and must satisfy union and finite-intersection axioms. Continuity is naturally phrased using preimages of open sets, allowing the same definition in spaces without a metric. Products combine spaces, while quotients identify points according to a relation. Compactness and connectedness describe different global properties and must not be conflated. Homeomorphisms preserve all topological properties, so finding a property that differs can disprove their existence even when two drawings look similar.','拓扑用开集而非固定尺度研究连续变形保持的性质。拓扑规定开子集并满足并与有限交公理。连续性用开集原像表述，可用于没有度量的空间。积组合空间，商按关系识别点。紧致与连通描述不同整体性质，不能混淆。同胚保持全部拓扑性质，因此找到差异性质即可否定同胚，即使图形看似相近。','topology');
R('M24.01','拓扑空间与基','open-set axioms;basis;discrete topology','开集公理;基;离散拓扑','A topology includes empty and full sets, arbitrary unions, and finite intersections. A basis generates open sets by unions.','拓扑含空集与全集，对任意并、有限交封闭；基通过并生成开集。','On a two-point set {a,b}, the discrete topology contains ∅,{a},{b},{a,b}: all four subsets. The indiscrete topology has only two.','两点集离散拓扑包含空、{a}、{b}、全集共4个；不可分拓扑只有2个。','Arbitrary intersections of open sets need not be open.','任意交未必保持开。',['How many opens in the two-point discrete space?','两点离散空间几个开集？',4],['How many in its indiscrete topology?','不可分拓扑几个开集？',2]);
R('M24.02','连续映射与同胚','open preimage;inverse continuity;topological invariant','开集原像;逆连续;拓扑不变量','A map is continuous when each open-set preimage is open. A homeomorphism is a bijection with both it and its inverse continuous.','开集原像均开定义连续；双射及其逆均连续定义同胚。','f(x)=2x+1 maps R homeomorphically to R. Its inverse is (y−1)/2; both maps carry nearby values to nearby values.','f(x)=2x+1给实线同胚，逆为(y−1)/2，两者都保持邻近关系。','A continuous bijection need not have a continuous inverse without additional hypotheses.','连续双射若无额外条件，逆未必连续。',['Find f(3).','求f(3)。',7],['Find f⁻¹(9).','求f⁻¹(9)。',4,'(9−1)/2=4.','(9−1)/2=4。']);
R('M24.03','积空间与商空间','product basis;identification;quotient map','积基;识别;商映射','Product topology uses products of open sets as basic neighborhoods for finite products. Quotient topology declares a set open exactly when its preimage is open.','有限积拓扑以开集乘积为基本邻域；商拓扑规定集合开当且仅当原像开。','Identifying endpoints 0 and 1 of [0,1] produces a circle. The two endpoints become one equivalence class, while interior points remain distinct.','把[0,1]两端0与1识别得到圆，两端成为同一等价类，内部点仍不同。','Quotients can change separation properties; a picture alone does not define the topology.','商可改变分离性质，图画本身不能定义拓扑。',['How many endpoint classes remain after identifying 0 with 1?','识别0与1后端点剩几个类？',1],['A product of sets with 3 and 4 elements has how many pairs?','3元素集与4元素集的积有几个有序对？',12,'3×4=12.','3×4=12。']);
R('M24.04','紧致与连通','finite subcover;separation;continuous image','有限子覆盖;分离;连续像','Connectedness forbids splitting a space into two disjoint nonempty open pieces. Continuous images preserve both connectedness and compactness.','连通性禁止分成两个不交非空开块；连续像保持连通与紧致。','The interval [0,1] is compact and connected. Its image under x↦2x is [0,2], retaining both properties.','[0,1]紧且连通，x↦2x的像[0,2]保持二者。','A compact space may be disconnected, such as two isolated points.','紧空间也可能不连通，如两个孤立点。',['How many connected components does [0,1] have?','[0,1]几个连通分量？',1],['How many components in {0,1} with the subspace topology from R?','实线子空间{0,1}几个分量？',2,'Each isolated point is a separate component.','每个孤立点各成分量。']);
R('M24.05','分离与度量联系','Hausdorff;disjoint neighborhoods;metrizable','豪斯多夫;不交邻域;可度量化','A Hausdorff space separates distinct points by disjoint neighborhoods. Every metric space is Hausdorff by choosing sufficiently small balls.','豪斯多夫空间中不同点有不交邻域；度量空间可取足够小球，因此都是豪斯多夫。','Points at distance 6 have disjoint open balls of radius 2: a shared point would force their distance below 4 by the triangle inequality.','距离6的两点取半径2开球不交，否则共同点与三角不等式迫使距离小于4。','Hausdorff alone does not imply the topology comes from a metric.','豪斯多夫本身不推出可度量化。',['For distance 6 and radii 2, what is the sum of radii?','距离6、半径各2时半径和多少？',4],['Can a shared point occur? Enter 1 yes, 0 no.','两球可有共同点吗？是填1，否填0。',0]);
R('M24.06','基本群入门','based loop;homotopy;winding number','基点闭路;同伦;绕数','The fundamental group consists of based loops modulo continuous deformation fixing the basepoint. Multiplication concatenates loops.','基本群由固定基点的闭路按保持基点的连续变形分类，乘法为路径连接。','For the circle, winding numbers add: a loop going twice counterclockwise followed by once clockwise has winding number 2−1=1.','圆上绕数相加：逆时针两圈接顺时针一圈，绕数2−1=1。','A loop may contract in a disk but not in its boundary circle; the ambient space matters.','闭路在圆盘内可缩，但在边界圆中未必可缩，环境空间重要。',['Find the combined winding number.','合并绕数多少？',1],['Find winding number of the reverse of a three-turn loop.','三圈闭路反向绕数多少？',-3,'Reversal changes the sign.','反向改变符号。']);
F('M25','Differential geometry studies shapes using local calculus while separating intrinsic properties from the way a shape sits in ambient space. A regular parameterization provides coordinate directions, but different parameters may describe the same geometric object. Derivatives determine tangent vectors and tangent planes; second-order change describes bending. The first fundamental form measures lengths and angles on a surface, while the second records normal bending in space. Curvature can vary by direction. Geodesics locally generalize straight paths, but global shortest paths may require additional comparison. Check regularity and coordinate singularities before attributing a computational failure to the shape itself.','微分几何用局部微积分研究形状，并区分内在性质与空间嵌入方式。正则参数化提供坐标方向，不同参数可表示同一对象。导数确定切向量与切平面，二阶变化描述弯曲。第一基本形式测表面长度与角，第二记录空间法向弯曲。曲率可依方向变化；测地线局部推广直线，整体最短还需比较。应检查正则性与坐标奇点，不能把计算失败都归于形状本身。','geometry');
R('M25.01','参数曲线与曲率','arc length;unit tangent;curvature','弧长;单位切向;曲率','A regular curve has nonzero velocity. Curvature measures the rate of change of unit tangent with respect to arc length.','正则曲线速度非零，曲率度量单位切向量相对弧长的变化率。','A circle of radius R has curvature 1/R: after arc length Rθ its tangent turns by θ. Radius 4 therefore gives curvature 1/4.','半径R圆走弧长Rθ时切向转θ，故曲率1/R；半径4曲率1/4。','Changing traversal speed does not change curvature; reversing orientation may change signed curvature conventions.','改变速度不改变曲率，反向可能改变有向曲率的符号约定。',['Find curvature of radius 4 circle.','半径4圆曲率多少？',0.25],['Find curvature of radius 2 circle.','半径2圆曲率多少？',0.5,'Curvature is reciprocal radius.','曲率为半径倒数。']);
R('M25.02','曲面与切空间','regular patch;tangent plane;normal vector','正则曲面片;切平面;法向量','For a surface patch r(u,v), independent partial derivatives r_u,r_v span the tangent plane. Their cross product provides a normal.','曲面片r(u,v)的独立偏导r_u、r_v张成切平面，叉积给法向。','For graph z=x²+y² at (1,2,5), tangent plane is z−5=2(x−1)+4(y−2).','曲面z=x²+y²在(1,2,5)切平面为z−5=2(x−1)+4(y−2)。','A zero cross product signals a nonregular parameterization, not automatically a singular surface.','叉积零表示参数化不正则，不一定曲面本身奇异。',['Find tangent coefficient of x−1.','x−1的切平面系数多少？',2],['Find coefficient of y−2.','y−2系数多少？',4]);
R('M25.03','第一与第二基本形式','metric coefficients;normal bending;shape operator','度量系数;法向弯曲;形算子','The first form uses dot products of tangent derivatives: E=r_u·r_u,F=r_u·r_v,G=r_v·r_v. The second uses normal components of second derivatives.','第一形式用切导数点积E、F、G；第二形式用二阶导数的法向分量。','For a plane patch r(u,v)=(2u,3v,0), E=4,F=0,G=9. Every second derivative vanishes, so the second form is zero.','平面r=(2u,3v,0)时E=4、F=0、G=9，二阶导全零，第二形式零。','Metric coefficients depend on coordinates even though measured lengths do not.','度量系数依坐标而变，实际长度不变。',['Find E.','E多少？',4],['Find G.','G多少？',9]);
R('M25.04','曲率与测地线','principal curvature;Gaussian curvature;geodesic','主曲率;高斯曲率;测地线','Principal curvatures are extreme normal curvatures. Their product is Gaussian curvature. A geodesic has zero tangential acceleration when parameterized by arc length.','主曲率为法曲率极值，其乘积是高斯曲率；弧长参数测地线切向加速度零。','A sphere of radius 2 has both principal curvature magnitudes 1/2, so Gaussian curvature is 1/4. A cylinder has one zero principal curvature, giving zero Gaussian curvature.','半径2球两个主曲率大小均1/2，高斯曲率1/4；圆柱有一个主曲率零，因此高斯曲率零。','Principal-curvature signs depend on normal orientation; their product does not.','主曲率符号依赖法向选择，乘积不变。',['Find Gaussian curvature of radius 2 sphere.','半径2球高斯曲率多少？',0.25],['Find cylinder Gaussian curvature.','圆柱高斯曲率多少？',0]);
R('M25.05','内在几何','isometry;intrinsic curvature;local versus global','等距;内在曲率;局部与整体','Intrinsic geometry uses lengths measured within the surface. A local isometry preserves those lengths and Gaussian curvature.','内在几何使用表面内测量的长度，局部等距保持长度与高斯曲率。','A cylinder can be unrolled locally into a plane without stretching; both have Gaussian curvature zero. A sphere cannot be flattened this way because its curvature is positive.','圆柱可局部无拉伸展开到平面，两者高斯曲率零；球曲率正，不能这样展平。','Equal curvature at one point does not establish a global isometry.','一点曲率相同不能建立整体等距。',['Find the plane Gaussian curvature.','平面高斯曲率多少？',0],['Can a sphere be locally flattened isometrically? Enter 1 yes, 0 no.','球可局部等距展平吗？是1否0。',0]);
R('M25.06','流形与微分形式入门','chart;differential form;exterior derivative','坐标图;微分形式;外微分','A manifold is locally modeled on Euclidean space through compatible charts. Differential forms encode oriented integration and transform consistently between charts.','流形由相容坐标图局部仿欧氏空间；微分形式编码有向积分并在换图中一致变换。','For f(x,y)=x²+y², df=2x dx+2y dy. At (1,3), coefficients are 2 and 6; applying df to displacement (a,b) gives 2a+6b.','f=x²+y²时df=2x dx+2y dy，在(1,3)系数2、6，作用于位移(a,b)得2a+6b。','A chart is local; one coordinate system need not cover an entire manifold without singularities.','坐标图是局部的，单一坐标未必无奇点覆盖全流形。',['Find dx coefficient at (1,3).','(1,3)处dx系数多少？',2],['Find dy coefficient.','dy系数多少？',6]);
F('M26','Numerical mathematics studies algorithms that approximate mathematical quantities using finite computation. Separate conditioning of the underlying problem from stability of the chosen algorithm: a stable method cannot make an inherently sensitive problem insensitive. Track truncation error, rounding error, and stopping criteria rather than reporting many digits without evidence. Root finding, linear solves, interpolation, and optimization should be verified using residuals, known bounds, and independent changes of resolution. Convexity gives powerful guarantees about global optima, but constraints and domain assumptions remain essential. A numerical result is an approximation with evidence, not automatically an exact proof of existence, uniqueness, or optimality.','数值数学研究有限计算近似数学量。应区分问题条件性与算法稳定性，稳定算法不能消除问题本身的敏感性。须跟踪截断、舍入和停止准则，而非无依据多报数字。求根、线性求解、插值和优化应用残差、已知界及改变分辨率核验。凸性提供整体最优保证，但约束与定义域仍重要。数值结果是有证据的近似，不自动构成存在、唯一或最优的精确证明。','optimization');
R('M26.01','浮点误差与条件数','rounding;cancellation;condition number','舍入;消去;条件数','Floating-point numbers approximate real values with finite precision. Conditioning measures how much output changes relative to input perturbations.','浮点以有限精度近似实数；条件性度量输入扰动引起的相对输出变化。','Subtracting 1.000001−1=0.000001 retains few reliable digits if the inputs were already rounded. Algebraic reformulation can avoid some harmful cancellation.','1.000001−1=0.000001若输入已有舍入，剩余可靠数字很少；代数改写可避免部分消去。','Small residuals do not ensure small solution error for ill-conditioned problems.','病态问题中残差小不保证解误差小。',['Find the exact difference 1.000001−1.','精确差1.000001−1多少？',0.000001],['What is 10⁻⁶ as a decimal?','10⁻⁶的小数多少？',0.000001]);
R('M26.02','求根与收敛','bisection;Newton step;stopping criterion','二分;牛顿步;停止准则','Bisection halves a sign-changing interval for a continuous function. Newton uses x_new=x−f(x)/f′(x), requiring a nonzero derivative.','二分对连续函数异号区间折半；牛顿为x_new=x−f/f′，要求导数非零。','For x²−2 and x=1.5, one Newton step gives 1.5−0.25/3=17/12. Bisection of [1,2] uses midpoint 1.5.','x²−2从1.5牛顿一步为1.5−0.25/3=17/12；[1,2]二分中点1.5。','Newton can diverge or leave the valid domain; a small step alone need not mean a small residual.','牛顿可能发散或离域，小步不必意味着小残差。',['Find the Newton next value.','牛顿下一值多少？',17/12],['After 4 bisections of width 1, what width remains?','宽1二分4次后宽多少？',1/16,'Each step halves: 1/2⁴=1/16.','每次折半，1/2⁴=1/16。']);
R('M26.03','数值线性代数','pivoting;residual;factorization','选主元;残差;分解','Solving Ax=b numerically usually uses a factorization rather than explicitly forming A⁻¹. Pivoting avoids dangerous small divisors in elimination.','数值解Ax=b通常用分解而非显式求逆；选主元避免消元中的危险小除数。','For A=diag(2,5), b=(6,20), solve coordinates separately to get x=(3,4). The residual Ax−b is exactly zero in exact arithmetic.','A=diag(2,5)、b=(6,20)时逐坐标得x=(3,4)，精确算术残差零。','A computed zero residual to displayed precision is not a universal proof of accuracy.','显示精度下残差零并不普遍证明准确。',['Find solution first coordinate.','解第一坐标多少？',3],['Find solution second coordinate.','解第二坐标多少？',4]);
R('M26.04','插值与数值求积','interpolant;trapezoid;error refinement','插值多项式;梯形法;加密误差',
'Quadrature approximates an integral using sampled values and weights. The trapezoid rule replaces a curve by straight segments.','数值求积以采样值加权近似积分，梯形法以线段替代曲线。','For f(x)=x² on [0,1], one trapezoid gives (0+1)/2=0.5. Two equal trapezoids give 0.375, closer to the exact integral 1/3.','x²在[0,1]一梯形得0.5，两等分梯形得0.375，更接近精确1/3。','More nodes do not cure a poor model of singularities or discontinuities automatically.','增加节点不自动修复奇点或不连续的错误建模。',['Find the one-trapezoid estimate.','一个梯形估计多少？',0.5],['Find the two-trapezoid estimate.','两个梯形估计多少？',0.375]);
R('M26.05','凸优化与梯度','convex objective;gradient descent;step size','凸目标;梯度下降;步长','A differentiable convex function lies above every tangent plane. Any zero-gradient point is a global minimum on an unconstrained convex domain.','可微凸函数在所有切平面上方；无约束凸域中零梯度点为全局最小。','For f(x)=(x−3)², gradient is 2(x−3). Starting at zero with step 1/4 gives x_new=0−(1/4)(−6)=1.5.','f=(x−3)²梯度2(x−3)，从0以步长1/4更新得1.5。','Excessive steps can overshoot and diverge even on a simple convex function.','步长过大即使简单凸函数也会过冲发散。',['Find the first gradient step.','第一步更新多少？',1.5],['Find the global minimizing x.','全局最小点x多少？',3,'The nonnegative square vanishes at x=3.','非负平方在3处为零。']);
R('M26.06','约束优化与数值验证','feasibility;KKT conditions;optimality gap','可行性;KKT条件;最优间隙','A candidate must satisfy constraints before its objective can be compared. KKT conditions combine stationarity, feasibility, dual signs, and complementary slackness under suitable assumptions.','候选先须满足约束才比较目标；KKT在适用假设下结合平稳、可行、对偶符号与互补松弛。','Minimize (x−3)² subject to x≤1. The unconstrained minimizer 3 is infeasible, so the constrained optimum is x=1 with objective 4.','最小化(x−3)²且x≤1，无约束点3不可行，约束最优为1，目标4。','Checking stationarity alone ignores active constraints. Report feasibility residuals alongside objective values.','只查平稳忽略活跃约束，目标值应同时附可行残差。',['Find the constrained minimizing x.','约束最小点多少？',1],['Find the minimum objective.','最小目标多少？',4]);
function deepen(id,en,zh,qe,qz,answer,he,hz,ee,ez){const l=lessons.find(x=>x.moduleId===id);l.sections[1]={type:'concept',title:B('Reasoning in detail','深入推理'),body:B(en,zh)};l.exercises[0].hints=[B(l.sections[0].body.en,l.sections[0].body.zh)];l.exercises[1]={id:`module.${id}.transfer-v2`,type:'numeric',prompt:B(qe,qz),answer,tolerance:1e-8,hints:[B(he,hz)],explanation:B(ee,ez)};}
deepen('F01.01','A fraction represents division as well as equal parts: three wholes shared equally among four people gives each person 3/4. To compare fractions, rewrite them using the same whole and denominator; 2/3=8/12 exceeds 3/4=9/12 only if the inequality is reversed, so actually 2/3<3/4. Multiplication by a fraction scales a quantity: half of six is three. Dividing by a fraction asks how many such portions fit: six divided by one half is twelve. Before computing a ratio, convert quantities to compatible units; 50 cm to 2 m is 50:200=1:4.','分数也表示除法：三个整体平均分给四人，每人3/4。比较分数须同整体通分，2/3=8/12而3/4=9/12，所以2/3较小。乘分数表示缩放，六的一半为三；除分数问能装几份，六除一半为十二。列比前要统一单位，50厘米比2米为50:200=1:4。','A ribbon is 3 metres long. How many pieces of length 3/8 metre fit exactly?','3米丝带恰好可分几段3/8米？',8,'Ask how many copies of 3/8 add to 3.','问几个3/8相加得到3。','3 divided by 3/8 equals 3×8/3=8; multiplying 8 by 3/8 checks the full length.','3÷(3/8)=3×8/3=8；8×3/8=3，长度核对正确。');
deepen('F01.02','An expression can be viewed as a sequence of operations on an input. In 2(x+3), first add three and then double; in 2x+3, double first and then add three. Their outputs differ because grouping changes the calculation. To combine like terms, interpret coefficients as counts of the same object: three x quantities plus two x quantities make five x quantities. Powers create different objects, so x+x² cannot be reduced to 2x³. Substitution should preserve brackets around negative numbers and compound expressions. Checking two forms at one input may reveal a mistake, but only algebra establishes an identity for every input.','表达式可看成对输入施行操作：2(x+3)先加三再翻倍，2x+3先翻倍再加三，分组改变计算。同类项系数像同类对象的个数，三个x加两个x是五个x；x²是不同对象，不能把x+x²化成2x³。代入负数或复合式要保留括号。单点验算能发现错误，却只有代数论证能证明对所有输入恒等。','Evaluate 3(a−2)−a when a=−1.','a=−1时计算3(a−2)−a。',-8,'Replace both occurrences with (−1), keeping the subtraction sign.','两处都代入(−1)，保留减号。','3(−1−2)−(−1)=−9+1=−8.','3(−1−2)−(−1)=−9+1=−8。');
deepen('F01.03','The domain answers which inputs are allowed; the codomain answers which outputs are declared possible; the image records which are actually achieved. These sets can differ. For x↦x² from the reals to the reals, negative outputs are never reached and opposite nonzero inputs collide. Restricting the domain to nonnegative reals removes the collision, but surjectivity still requires restricting the codomain to nonnegative reals. This produces a bijection with inverse square root. To test whether a relation is a function, examine each allowed input separately: exactly one assigned output is required, even if other inputs share it.','定义域说明允许输入，陪域说明声明的输出范围，像集记录实际达到的输出。实数到实数的平方映射既到不了负数，也把相反数合并。将定义域限为非负去掉碰撞，还需把陪域限为非负才能满射，得到以平方根为逆的双射。检验函数应逐个看每个允许输入，必须恰有一个输出，但不同输入可共享输出。','For f:{−2,−1,0,1,2}→R given by f(x)=x², how many distinct outputs occur?','f:{−2,−1,0,1,2}→R，f(x)=x²，实际有几个不同输出？',3,'Compute the set of squares and remove repetitions.','计算平方集合，删除重复项。','The outputs are 4,1,0,1,4, whose distinct values are {0,1,4}: three outputs.','输出4、1、0、1、4，互异值为{0,1,4}，共三个。');
deepen('F01.04','A quantified statement is like a challenge with an order of play. In ∀x∃y, an opponent chooses x first and you may respond with a suitable y. In ∃y∀x, you must commit to one y before seeing every possible x. This explains why the two formulas can differ. Negating an implication P⇒Q produces P and not Q: a genuine counterexample must satisfy the hypothesis and violate the conclusion. De Morgan rules negate “and” to “or” and vice versa. Over a specified domain, the negation of “every x has P(x)” is “some x lacks P(x),” including the correct equality boundary for inequalities.','量词可看成按顺序进行的挑战：∀x∃y允许先看x再选y；∃y∀x则须预先固定一个y应对所有x。因此顺序能改变真假。P⇒Q的否定为P且非Q，反例必须满足假设却不满足结论。德摩根法则把且与或互换；否定“所有x有P”是“存在x没有P”，不等式还要正确处理等号边界。','Among integers 1 through 8, how many counterexamples refute “if n is even then n is divisible by 4”?','整数1至8中，有几个反例反驳“若n偶则n被4整除”？',2,'Only even numbers can satisfy the hypothesis; remove multiples of four.','只看满足假设的偶数，再排除4的倍数。','The even numbers are 2,4,6,8. Exactly 2 and 6 violate the conclusion, so there are two counterexamples.','偶数2、4、6、8中，恰2与6不满足结论，共两个反例。');
deepen('F01.05','A graph makes a claim through both the data positions and the chosen scales. On a linear axis from zero to one hundred, equal pixel gaps represent equal numerical differences. On a logarithmic axis, equal gaps represent equal multiplication factors, so ten to one hundred occupies the same gap as one hundred to one thousand. For a line graph, compute slope from actual coordinate changes, not the apparent angle on the screen. Estimate first by rounding while keeping the scale of the result. Then ask whether the approximation is above or below the original quantity; this helps detect errors before detailed arithmetic.','图像同时由点的位置和尺度作出断言。线性轴等距代表等差；对数轴等距代表等倍，所以10到100与100到1000等距。斜率须用实际坐标差，不能靠屏幕倾角判断。先取整保留数量级，再判断估值偏大还是偏小，这能在详细计算前帮助发现错误。','A line passes through (2 hours,14 km) and (5 hours,35 km). What is its slope in km/h?','直线过(2小时,14千米)、(5小时,35千米)，斜率多少千米/时？',7,'Divide the difference in distance by the difference in time.','距离差除时间差。','(35−14)/(5−2)=21/3=7 km/h; using 35/5 happens to agree here but is not the general two-point rule.','(35−14)/(5−2)=21/3=7千米/时；35/5此处碰巧相同，却不是一般两点法。');
deepen('F01.06','A reader should be able to tell which quantities were given, which were introduced, and which were proved. Use “let” to introduce a symbol, but do not choose it in a way that already assumes the desired conclusion. Separate equalities from implications: squaring two equal real numbers preserves equality, while the reverse inference introduces a sign choice. When reporting a solution, state the set of all allowed answers rather than one convenient answer. For an approximation, show the rounding precision. Finally, substitute candidate values into the original problem, because a sequence of algebraic manipulations may have hidden a forbidden denominator or lost a case.','读者应能区分已知、引入和已证的量。用“设”定义符号时，不能暗中假设结论。等号与蕴含须分清：相等实数平方后仍相等，反推则多了符号选择。解题应报告全部允许答案，不是只报方便的一个；近似应说明精度。最后代回原题，因为变形可能隐藏分母限制或丢掉分支。','Solve (x²−9)/(x−3)=8 with its original domain restriction. What is x?','按原定义域解(x²−9)/(x−3)=8，x多少？',5,'Exclude x=3, factor the numerator, then solve the remaining linear equation.','先排除3，再分解分子并解一次方程。','For x≠3 the expression is x+3. Thus x=5, and 5 is permitted; substitution gives (25−9)/2=8.','x≠3时化为x+3，故x=5且合法，代回(25−9)/2=8。');
deepen('F02.01','A definition provides a membership test. For example, an integer n is even exactly when n=2k for some integer k; one cannot declare an unfamiliar number even merely because it looks large or ends in a familiar symbol. A universal claim then makes a promise about every object passing a hypothesis test. To refute it, keep the hypothesis true and make the conclusion false. To repair it, consider whether a missing condition removes every counterexample, then prove the restricted statement. Testing finitely many cases is valuable for discovery but leaves infinitely many unchecked cases when the domain is infinite.','定义提供成员检验，如偶数恰能写成2k且k为整数，不能凭外观判断。全称命题对每个满足假设的对象承诺结论。反驳须保持假设真并令结论假。修复要判断新增条件是否排除全部反例，再证明受限命题。有限检验有助发现，却无法覆盖无限定义域中所有未检情况。','How many of 2,3,4,5 are counterexamples to “every prime exceeds 3”?','2、3、4、5中有几个反例反驳“每个素数都大于3”？',2,'A counterexample must first be prime, then fail to exceed 3.','反例首先必须是素数，然后不大于3。','2 and 3 are prime but not greater than 3. The number 4 fails the premise, and 5 satisfies the conclusion.','2和3为素数却不大于3；4不满足前提，5满足结论。');
deepen('F02.02','A direct proof starts with an arbitrary object satisfying the hypotheses. “Arbitrary” means no extra convenient property may be assumed. Translate each hypothesis into its defining form, then use algebra or an already justified theorem. For parity, two odd integers have forms 2r+1 and 2s+1, so their product is 2(2rs+r+s)+1 and is odd. The integer inside the parentheses supplies the witness required by the definition. An equivalence requires repeating the argument in the opposite direction or using transformations known to be reversible. A one-way implication should never be silently relabeled as an equivalence.','直接证明从任意满足假设的对象开始，不能再附加方便条件。把假设写成定义形式，例如奇数2r+1、2s+1的积为2(2rs+r+s)+1，括号中整数正是定义所需见证。等价证明还需反方向，或证明所有变形可逆；单向蕴含不能默认为等价。','For odd numbers 5 and 7, find integer k such that their product is 2k+1.','奇数5与7的积写成2k+1，k多少？',17,'Compute the product and solve 2k+1=35.','先求积，再解2k+1=35。','5×7=35=2×17+1, so k=17 verifies oddness constructively.','5×7=35=2×17+1，因此k=17构造性地验证奇性。');
deepen('F02.03','Contraposition is often effective when the negated conclusion has a simple description. To show a prime above two is odd, suppose instead that it is even: it equals 2k, and being above two forces k>1, producing a nontrivial factor. A contradiction proof permits assuming the desired statement false, but every later step must follow from that temporary assumption plus the original hypotheses. The resulting contradiction may be an impossible equality, a violated hypothesis, or two opposite inequalities. At the end, explicitly discharge the temporary assumption. Never confuse “I found no example” with a logical contradiction.','当否定结论易描述时逆否有效。欲证大于2的素数为奇，若其偶则写2k；大于2迫使k>1，产生非平凡因子。反证可暂设结论不成立，但后续每步必须从临时假设与原假设推出。矛盾可以是非法等式、违背假设或相反不等关系；结尾要撤销临时假设。没找到例子不等于逻辑矛盾。','How many integers in {3,4,5,6,7} have odd squares?','{3,4,5,6,7}中有几个数平方为奇？',3,'Use the equivalence between an integer’s parity and its square’s parity.','用整数与其平方奇偶性相同。','The odd inputs 3,5,7 have odd squares; 4 and 6 have even squares. Hence three.','奇输入3、5、7平方奇，4、6平方偶，所以三个。');
deepen('F02.04','The logical force of induction is that a valid starting case can travel along every finite chain of successor steps. In the inductive step, assume only the claim at a generic index k, then derive the claim at k+1 using the exact algebra of that index. For a recurrence involving two earlier terms, strong induction or two initial cases may be needed. To prove 2^n≥n+1 for n≥0, start at n=0. If 2^k≥k+1, then 2^(k+1)≥2k+2≥k+2 because k≥0. The last inequality is a separate necessary justification.','归纳的力量在于起点可沿任意有限后继链传递。归纳步只能暂假一般k时结论，再准确推出k+1。涉及前两项的递推可能需要强归纳或两个初值。证明2^n≥n+1，n=0成立；若k成立，则2^(k+1)≥2k+2≥k+2，最后一步用k≥0，不能省略理由。','For the inequality 2^n≥n+1, what is the gap at n=5?','不等式2^n≥n+1在n=5时左右差多少？',26,'Compute 2⁵ and subtract 5+1.','计算2⁵再减6。','32−6=26; this checks one instance, while induction is needed for the universal claim.','32−6=26；这里只检查一个实例，普遍命题仍需要归纳。');
deepen('F02.05','To find an invariant, first write down exactly how a legal move changes the state. If a move adds two to one coordinate and subtracts two from another, both the total sum and each coordinate’s parity remain unchanged. A target violating either property is unreachable. The converse need not hold: preserving known invariants does not prove a path exists. A monovariant supports termination only with a lower or upper bound preventing endless change; a strictly decreasing positive real sequence can continue forever, while a nonnegative integer dropping by at least one cannot. Extremal arguments exploit the contradiction between minimal choice and a constructed smaller object.','寻找不变量先写每步如何改变状态。某坐标加二、另一坐标减二时，总和与各坐标奇偶性都不变，违反任一性质的目标不可达。但满足已知不变量不保证有路径。单调量证终止还需界：正实数严格下降仍可无限，非负整数每步至少减一则不能。极值法利用“最小对象”与构造出的更小对象冲突。','Starting at 11, each move adds or subtracts 6. Can 20 be reached? Enter 1 yes, 0 no.','从11开始每步加减6，能到20吗？能1不能0。',0,'Compare the remainders modulo 6.','比较模6余数。','11≡5 and 20≡2 modulo 6. Every allowed move preserves the remainder, so reaching 20 is impossible.','11模6余5，20余2，每步保持余数，因此不可达。');
deepen('F02.06','Audit a proof in three passes. First check the statement: are all variables quantified, all domains given, and all special cases included? Next inspect each transition: is it an implication, an equivalence, a definition, or an application of a theorem whose assumptions are met? Finally examine the conclusion: has existence been shown, have all solutions been captured, and are equality or boundary cases handled? For x(x−2)=0, splitting into x=0 or x=2 is exhaustive by the zero-product property over the reals. In a ring with zero divisors that inference is unavailable, illustrating why the ambient setting is part of a proof.','证明检查可分三轮：先核命题的量词、定义域与特殊情况；再逐步辨明蕴含、等价、定义或定理应用，并查条件；最后核结论是否证明存在、覆盖全部解并处理边界。实数上x(x−2)=0分成0或2由零乘积性质保证穷尽，但有零因子的环中不能这样推，说明环境也是证明的一部分。','How many real solutions of x²=7x are lost if one divides immediately by x?','x²=7x直接除x会丢几个实数解？',1,'Factor first and identify the excluded divisor value.','先分解并找被除数值排除的情况。','x(x−7)=0 has solutions 0 and 7. Dividing by x excludes exactly the solution 0, losing one.','x(x−7)=0解0与7，除x恰丢0这一个。');
deepen('F03.01','Dimensional analysis treats the dimensions of multiplication and division like algebraic factors. If distance has dimension L and time T, acceleration has dimension L/T². Thus mass times acceleration has dimension ML/T², defining force units. In a proposed equation, all added terms must share a dimension, including constants that may themselves carry units. Conversion factors should be written so unwanted units cancel. For area and volume, raise the entire conversion factor to the second or third power. This prevents the common mistake of converting square metres to square centimetres by only a factor of one hundred.','量纲分析把乘除中的量纲当代数因子，长度L、时间T给加速度L/T²，质量乘加速度为ML/T²，即力。相加项必须同量纲，常数也可能带单位。换算因子应让旧单位消去，面积体积须把整个因子平方或立方，防止平方米只乘100就当平方厘米。','A volume is 0.003 m³. How many cm³ is it?','0.003立方米等于多少立方厘米？',3000,'One metre is 100 cm, so cube 100 for volume.','一米100厘米，体积换算把100立方。','0.003×100³=0.003×1000000=3000 cm³.','0.003×100³=3000立方厘米。');
deepen('F03.02','A measured value is the outcome of a procedure, not an exact view of nature. Resolution limits what changes can be distinguished; calibration compares the instrument against a reference. Repeatability concerns the spread of repeated readings under similar conditions, whereas accuracy concerns agreement with a reference value. An offset error can leave repeatability excellent while shifting every result. If only a stated bound ±δ is available, preserve that interpretation rather than silently treating it as a standard deviation. In independent random-error models, averaging can reduce uncertainty, but shared systematic error is not divided away by increasing the number of readings.','测量值是过程输出，不是对自然的精确读取。分辨率限制可区分变化，校准与参考比较。重复性看相似条件下读数散布，准确性看与参考吻合；偏置可让重复性很好却整体偏离。若只给±δ界，不可默当标准差。独立随机误差下平均可降低不确定度，但共同系统误差不会因增加次数而除掉。','Four readings are all known to be 0.2 g high. Their mean is 8.7 g. What is the corrected mean?','四次读数均已知偏高0.2克，均值8.7克，修正均值多少？',8.5,'The common offset remains in the mean; subtract it once.','共同偏置仍在均值中，减去一次。','8.7−0.2=8.5 g. The correction is not 0.2/4 because every observation carries the same offset.','8.7−0.2=8.5克；不能只减0.2/4，因为每次都带相同偏置。');
deepen('F03.03','A plotted point has two coordinates and both may have uncertainty. Start by identifying what was manipulated, what was measured, and which variable belongs on each axis. A linear trend suggests a constant rate, but residuals can reveal curvature that the main plot hides. An outlier is an observation far from the model or surrounding data, not automatically a mistake. Investigate whether it reflects a transcription problem, a changed condition, or genuine variation. Interpreting an average slope over a time interval does not imply the instantaneous rate stayed constant throughout it. A horizontal position graph means stationary, whereas a horizontal velocity graph means constant velocity.','点的两个坐标都可能有不确定度。先辨操控量、测量量与轴。直线趋势提示恒变化率，但残差可显露主图隐藏的弯曲。离群值是偏离模型或周围数据的观察，不自动是错误，应查抄录、条件变化或真实波动。区间平均斜率不意味瞬时率始终不变；水平位置图表示静止，水平速度图表示匀速。','A position graph changes from 10 m at 2 s to 4 m at 5 s. What is average velocity in m/s?','位置从2秒10米变到5秒4米，平均速度多少米/秒？',-2,'Use signed displacement, not total distance.','使用有符号位移，不是总路程。','(4−10)/(5−2)=−6/3=−2 m/s. Negative means motion in the chosen negative coordinate direction overall.','(4−10)/(5−2)=−2米/秒，负号表示整体朝所选坐标负方向。');
deepen('F03.04','A causal question compares what would happen under different interventions. Because one subject cannot usually be observed simultaneously under both conditions, a control group approximates the missing comparison. Random allocation makes systematic initial differences less likely; controlling light, water, and measurement procedures removes specific alternative explanations. Replication distinguishes a repeatable effect from an isolated fluctuation. Blinding reduces the chance that expectations change treatment or measurement. A confounder is more specific than any uncontrolled variable: it is associated with both the explanatory variable and outcome in a way that can distort their relationship. Observational data need additional reasoning to support causal interpretation.','因果问题比较不同干预下会怎样。单个对象通常不能同时处于两条件，对照组近似缺失比较。随机分配减少系统初始差异，固定光水及测量流程排除特定解释。重复区分稳定效应与偶然波动，盲法减少预期影响处理或测量。混杂不是任意未控制量，而是与解释变量和结果都有关并可能扭曲关系的量。观察数据需额外论证才能支持因果。','A study compares fertilizer outdoors with no fertilizer indoors. How many treatment factors changed: fertilizer and light environment?','实验比较户外施肥与室内不施肥：肥料和光环境共改变几个因素？',2,'List both differences rather than only the intended fertilizer change.','列两组全部差异，不只预期的肥料变化。','Two factors changed, so a growth difference cannot be attributed uniquely to fertilizer by this comparison alone.','两因素同时改变，因此仅此比较不能把生长差唯一归因于肥料。');
deepen('F03.05','Fitting chooses parameters to reduce a specified discrepancy between model and observations. In least squares, squaring residuals prevents positive and negative deviations from canceling and gives larger deviations greater weight. This choice is not universally best: it is sensitive to outliers and depends on what error model is reasonable. Inspect residuals against input and fitted value; a curved pattern suggests a missing nonlinear term, while increasing spread suggests nonconstant noise. A more flexible model can always reduce training error, but may fit accidental details. Keep separate data for prediction checks when possible, and record the range over which the model was tested.','拟合按指定差异准则选参数。最小二乘平方残差，避免正负抵消并更重惩罚大偏差，但对离群敏感，不总是最优选择。应画残差对输入或拟合值：弯曲提示缺非线性项，扩散提示噪声非常数。更灵活模型可降训练误差，却可能拟合偶然细节；尽可能用独立数据检查预测并记录测试范围。','A model predicts 2,5,8 while observations are 3,3,10. What is the sum of squared residuals?','模型预测2、5、8，观测3、3、10，平方残差和多少？',9,'Compute observation minus prediction for each pair, then square before adding.','每对先观测减预测，再平方求和。','Residuals are 1,−2,2, whose squares sum to 1+4+4=9.','残差1、−2、2，平方和1+4+4=9。');
deepen('F03.06','A reproducible record is a chain from the original observation to the reported result. Store the raw value with its unit and identifier, then record every correction, exclusion, conversion, and averaging step separately. A timestamp can matter when conditions drift. Record instrument settings and the reference used for calibration, not only the instrument name. A revised calculation should leave the original readings intact, making it possible to reproduce both versions. For simulated data, record the model and parameters; if randomness is involved, also record the method for reproducing it. An unexpected observation should remain visible with the reason for any exclusion.','可复现记录是从原观察到结果的链条。原值带单位和编号保存，校正、排除、换算、平均各自记录。条件漂移时日期时间很重要；须记仪器设置和校准参考，不只名称。修订计算应保留原读数，便于复现两个版本。模拟数据须记模型参数，随机时还需可复现随机方法。异常应保持可见并附排除理由。','Recorded times are 1200,1500,1800 milliseconds. What is their mean in seconds?','记录时间1200、1500、1800毫秒，均值多少秒？',1.5,'Average in one unit, then convert milliseconds to seconds.','先统一单位求平均，再毫秒转秒。','The mean is 4500/3=1500 ms, which is 1.5 s. Raw millisecond readings should remain in the record.','均值4500/3=1500毫秒，即1.5秒，原始毫秒读数仍保留。');
deepen('F04.01','Retrieval begins with a specific prompt, such as “state the fraction addition rule and explain why.” Attempt an answer before viewing the source so that missing pieces become visible. Self-explanation then connects operations to meanings: common denominators make the parts equally sized, and only then can their counts be added. Check the attempt against the source and repair the first missing or incorrect idea. Later, use a different numerical example so that success requires the principle rather than memorizing an answer. A skipped question and an assisted answer should remain distinguishable from an independent correct response when planning what to review.','提取从具体提示开始，如“说明分数加法规则及理由”。查材料前先尝试，让缺口显现。自我解释把运算连到意义：通分使份等大，再加份数。核对后修复第一个错误或遗漏，之后换数值，以检验原则而非记答案。规划复习时应区分跳过、辅助正确和独立正确。','Without copying the worked fraction example, compute 2/5+1/10.','不复制原例，计算2/5+1/10。',0.5,'Rewrite fifths as tenths before adding.','先把五分之一换成十分之一。','2/5=4/10, so the sum is 5/10=1/2. The same principle transfers to new denominators.','2/5=4/10，和5/10=1/2，同原理迁移到新分母。');
deepen('F04.02','A worked example should expose the decision that selects each operation, not merely display a finished chain. In solving 2x+5=17, subtracting five removes the added constant and dividing by two reverses multiplication. A partially completed example can ask for one missing decision, then two, then the entire solution. Compare two examples whose surface forms differ but use the same reversal principle. Deliberate practice targets the specific weak decision rather than repeating everything indiscriminately. After correcting an error, solve a fresh item without the displayed solution. Keep track of whether a hint supplied the central step, since that changes what the successful attempt demonstrates.','例题应展示选操作的决定，不只成品链。2x+5=17先减五消去加项，再除二逆乘法。撤支架可先缺一步再缺两步直到独立完整解；比较表面不同而逆运算相同的例子。刻意练习针对薄弱决定，不是无差别重做。纠错后应独立做新题，并记录提示是否提供了核心步骤。','Solve 6(x−2)=30 without the worked-example numbers.','独立解6(x−2)=30。',7,'Undo the outer multiplication before the inner subtraction.','先逆外层乘法，再逆内层减法。','Divide by 6 to get x−2=5, then add 2 to obtain x=7.','除6得x−2=5，再加2得x=7。');
deepen('F04.03','An error log is most useful when it preserves the mistaken step rather than only the correct answer. Label the earliest cause: a definition was misunderstood, a condition was ignored, an operation was mishandled, or the question was misread. These causes require different repairs. A sign error in arithmetic may need a brief calculation check, while reversing an implication needs a counterexample and a logical explanation. Write a concise rule for detecting the same mistake next time, then create a changed example that still tests it. Revisit the new item later without reading the repaired solution; otherwise familiarity may be mistaken for a corrected understanding.','错题记录应保留错步而非只有正确答案。标最早原因：定义误解、条件忽略、运算失误或读题错误；不同原因修复不同。算术符号错可用短验算，倒置蕴含需反例与逻辑解释。写下下次识别规则，再造仍测试该问题的新例。之后不看修正解重测，避免把熟悉感当成理解已修复。','A learner writes −3x>12 ⇒ x>−4. What boundary value is correct, even though the inequality direction must reverse?','学习者写−3x>12⇒x>−4，虽方向须反转，正确边界值多少？',-4,'Solve equality −3x=12 separately from choosing the direction.','先解边界等式−3x=12，再处理方向。','The boundary is −4 and the correct set is x<−4. The error is direction reversal, not the boundary calculation.','边界−4，正确范围x<−4；错在方向，不是边界计算。');
deepen('F04.04','Read scientific material at two levels. At the sentence level, define each term and translate every formula into words with units. At the argument level, identify the question, assumptions, evidence, and conclusion. Mark whether a sentence reports observation, defines a quantity, proposes a model, or draws an inference. If an unfamiliar symbol appears, inspect the nearby definition before importing a meaning from another subject. Test a formula with a simple permitted case to confirm its interpretation, then examine a boundary case where its assumptions might fail. A compact summary should preserve conditions, not only the headline equation.','科学阅读分句子与论证两层：句子层定义术语，把公式译成带单位的话；论证层找问题、假设、证据与结论。区分观察、定义、模型与推断。陌生符号先查本地定义，不从其他学科硬套。以简单合法情形测试公式，再看假设失效的边界。简明总结应保留条件，不只留公式。','A formula states q=mt for constant rate m. If q=42 and t=6, what is m?','恒定速率公式q=mt，q=42、t=6，m多少？',7,'Identify m as accumulated quantity divided by elapsed time.','m是累计量除时间。','m=q/t=42/6=7 quantity-units per time-unit, assuming the stated constant-rate model.','m=q/t=7量单位/时间单位，使用题设恒速率模型。');
deepen('F04.05','A useful bilingual entry contains the English term, Chinese term, a definition, the symbol used in context, and one example distinguishing it from a nearby idea. For instance, domain is 定义域 and image is 像集; they are not interchangeable simply because both are sets. Translate a sentence by reconstructing its mathematical relationship, preserving quantifiers and conditions. “At most” means no more than and includes equality; “less than” excludes equality. The phrase “if and only if” requires both implication directions. When a symbol has several conventions, attach a local definition rather than relying on language choice to resolve the ambiguity.','有效双语词条包括两语术语、定义、当前符号和辨近义的例子，如定义域与像集同为集合却不可互换。翻译要重建数学关系，保留量词条件。At most为至多，含等号；less than不含等号；if and only if要求两个蕴含方向。符号多义时应加本地定义，不能靠语言选择解决。','How many nonnegative integers are at most 4?','至多为4的非负整数有几个？',5,'Include both zero and the equality boundary.','包含零与等号边界。','The set is {0,1,2,3,4}, containing five integers.','集合为{0,1,2,3,4}，共五个整数。');
deepen('F04.06','A plan should connect each research question to a measurement that could answer it. Define the outcome before collecting data so that success is not redefined after seeing the results. List controlled conditions, the factor changed, number of repetitions, and a feasible method of recording uncertainty. In the presentation, show the raw pattern before offering a mechanism; the same pattern may support more than one explanation. State whether the conclusion concerns only the tested conditions or a wider population. Finish with a concrete next experiment that could distinguish competing explanations, rather than treating every unresolved issue as a generic request for more data.','计划要把问题连到能回答它的测量，采集前定义结果，避免看完数据再改成功标准。列控制条件、改变因素、重复数和不确定度记录法。展示先给原始规律再解释机制，同一规律可能支持多种解释。说明结论仅针对测试条件还是更广总体。下一实验应能区分竞争解释，而非笼统说需要更多数据。','Four paper-bridge designs each need five trials, with one sheet per trial. How many sheets are required?','四种纸桥各试五次，每次一张纸，共需几张？',20,'Multiply number of designs by independent repetitions per design.','设计数乘每种独立重复数。','4×5=20 sheets. This count should be planned before beginning so that replication is not reduced selectively.','4×5=20张，应预先规划，避免选择性减少重复次数。');
deepen('M01.01','The solution set consists of every value for which the original statement is both defined and true. Adding the same expression to both sides preserves equality; multiplying by a nonzero constant is reversible. Multiplying by an expression involving x may fail to be reversible where that expression vanishes. For inequalities, compare points on a number line: multiplication by a negative reflects the line and reverses order. A factored inequality can be solved by locating zeros, dividing the line into intervals, and checking the sign on each interval. Endpoints are included only when the original inequality allows equality and the expression is defined there.','解集包括原式有定义且为真的全部值。同加保持等价，乘非零常数可逆；乘含x表达式在其为零处可能不可逆。负数乘法像数轴反射，故不等号反向。因式不等式可找零点分区间，再逐区间查符号；只有允许等号且有定义的端点才能包含。','For (x−2)(x−5)≤0, what is the length of the real solution interval?','(x−2)(x−5)≤0的实解区间长度多少？',3,'Find the two zeros and determine where the factors have opposite signs.','找两零点，再看因子何处异号。','The product is nonpositive on [2,5], whose length is 5−2=3.','乘积在[2,5]非正，长度5−2=3。');
deepen('M01.02','Completing the square rewrites a quadratic into a shape that exposes its geometry. Factor out a if necessary, then add and subtract the square of half the linear coefficient. This gives a(x−h)²+k, where h is the axis of symmetry and k is the vertex value. Because the square is nonnegative, the sign of a determines whether k is a minimum or maximum. Zeros are points where the graph meets the horizontal axis; the discriminant tells whether those intersections number zero, one, or two. For a linear function, equal input increments always give equal output increments, unlike a quadratic.','配方把二次式写成揭示几何的形式：必要时提出a，再加减一次项系数一半的平方，得到a(x−h)²+k。h为对称轴，k为顶点值，平方非负使a符号决定最小或最大。零点是横轴交点，判别式决定零、一、两个交点。一次函数等输入增量给等输出增量，二次函数则不同。','What is the maximum value of −2(x−4)²+7 over real x?','实数上−2(x−4)²+7最大值多少？',7,'The squared term is nonnegative and its coefficient is negative.','平方非负且系数为负。','−2(x−4)²≤0, so the expression is at most 7, achieved at x=4.','−2(x−4)²≤0，最多7，在x=4取得。');
deepen('M01.03','Polynomial long division subtracts a multiple of the divisor that cancels the current highest-degree term, repeating until the remainder has lower degree. This establishes P=DQ+R. When D=x−a, substituting x=a leaves P(a)=R because the divisor term vanishes. Hence a root is equivalent to an x−a factor. For rational graphs, examine canceled and uncanceled denominator factors separately: a canceled factor often leaves a removable hole, while an uncanceled zero may produce unbounded behavior. Also compare numerator and denominator degrees for large inputs. These algebraic features determine the graph without requiring a dense table of sampled points.','多项式除法反复减去除式倍数消最高次，直到余式次数更低，得到P=DQ+R。D=x−a时代a，除式项消去，所以余数P(a)，根等价于因子。分析有理图像要区分约掉与未约掉分母因子，前者常留空点，后者零处可无界；再比较次数判断远处行为。这些特征无需密集采样就能确定图像。','What is the remainder when x³−2x+4 is divided by x−2?','x³−2x+4除x−2余数多少？',8,'The remainder theorem asks for the value at x=2.','余数定理要求代入x=2。','P(2)=8−4+4=8.','P(2)=8−4+4=8。');
deepen('M01.04','The exponent laws explain logarithm laws. If u=a^r and v=a^s, then uv=a^(r+s), so taking logarithms gives log_a(uv)=r+s. Similarly, division subtracts exponents and a power multiplies them. These derivations require positive u and v in real logarithms. Exponential growth is multiplicative: a five-percent increase multiplies by 1.05, so two increases produce 1.05² rather than adding ten percent exactly. A decay factor lies between zero and one. To solve an exponential equation, isolate the exponential term before taking logarithms, and check that every logarithm argument is positive.','指数规律解释对数规律：u=a^r、v=a^s，则uv=a^(r+s)，取对数就是相加；除法变相减，乘方变相乘。实对数推导要求u、v正。指数增长是乘法，增长5%乘1.05，两次为1.05²，不恰好加10%。衰减因子介于零一。解方程先孤立指数项再取对数，并查真数正。','A population starts at 200 and retains 80% each period. What remains after three periods?','初始200，每期保留80%，三期后多少？',102.4,'Use the repeated multiplicative factor 0.8.','使用重复乘数0.8。','200×0.8³=200×0.512=102.4.','200×0.8³=102.4。');
deepen('M01.05','Function composition must respect both domains. In f(g(x)), the input x must belong to the domain of g and the intermediate value g(x) must belong to the domain of f. Reversing the order can therefore change both the formula and allowed inputs. To construct an inverse, write y=f(x), solve uniquely for x, and exchange the roles of input and output. The graph of an inverse reflects across y=x because each pair (x,y) becomes (y,x). If several inputs share an output, a unique inverse is impossible until an appropriate domain restriction removes the ambiguity.','复合必须同时满足两个定义域：x可输入g，中间值g(x)可输入f。反序可能同时改变公式与范围。求反函数写y=f(x)，唯一解出x，再交换输入输出。图像关于y=x反射，因为(x,y)换成(y,x)。若多个输入共享输出，就必须限制域消除歧义后才能有唯一逆。','Let f(x)=√x and g(x)=x−4. What is the smallest real input allowed for f(g(x))?','f(x)=√x，g(x)=x−4，f(g(x))允许的最小实输入多少？',4,'The square-root input must be nonnegative.','平方根内必须非负。','f(g(x))=√(x−4) requires x−4≥0, so the domain begins at 4.','√(x−4)要求x−4≥0，定义域从4开始。');
deepen('M01.06','A model is chosen by the mechanism and by observed relationships, not solely by its ability to pass through points. Constant additive change suggests a line; constant proportional change suggests an exponential. Parameters carry meanings and units: in distance=vt+d₀, v is a rate and d₀ an initial position. Solve for parameters using enough independent observations, then use additional observations to challenge the model. If conditions change after a threshold, define a piecewise function and check how the pieces meet. Every prediction should name the range and circumstances for which the chosen relationship is defensible.','模型应依据机制与观察关系，不只凭穿过数据点。恒定加性变化提示直线，恒定比例变化提示指数。参数有意义与单位，如距离=vt+d₀中v为速率、d₀为初位置。用足够独立观察定参数，再用额外观察挑战模型。阈值后条件改变时须分段并检查连接；预测应说明适用范围与情境。','A linear cost is 14 at 2 units and 26 at 5 units. What is the fixed cost?','线性成本2单位14，5单位26，固定成本多少？',6,'First find the per-unit slope, then subtract variable cost from one observation.','先求单位斜率，再从一次总价减变动成本。','Slope=(26−14)/(5−2)=4. The fixed cost is 14−4×2=6.','斜率12/3=4，固定成本14−4×2=6。');
deepen('M02.01','Radian measure is dimensionless because it is a ratio of two lengths, but recording the angle unit still prevents confusion. Equal central angles cut arc lengths proportional to radius, so s/r depends only on the angle. The circumference 2πr therefore corresponds to 2π radians. A negative angle describes rotation in the opposite orientation; adding full turns changes the numerical angle without changing the terminal ray. To convert degrees to radians, multiply by π/180; to reverse, multiply by 180/π. Sector area follows from the same fraction of a full disk: angle θ radians gives area r²θ/2 for a nonnegative sector angle.','弧度是两长度之比，因此无量纲，但注明角单位仍能防混淆。同中心角弧长正比半径，所以s/r只依角；周长2πr对应2π弧度。负角反向旋转，加整周不改终边。度转弧度乘π/180，反向乘180/π。扇形面积取整圆相同份额，为r²θ/2。','A sector has radius 6 and angle 0.5 radians. What is its area?','扇形半径6、角0.5弧度，面积多少？',9,'Use area equal to one half radius squared times the radian angle.','面积为半径平方乘弧度角的一半。','6²×0.5/2=36/4=9.','6²×0.5÷2=9。');
deepen('M02.02','The unit-circle definition extends right-triangle ratios to all real angles. At angle θ the radius is one, so the point coordinates directly give cosine and sine. On a circle of radius r, the same direction has coordinates r cosθ and r sinθ. The signs follow the coordinate axes: sine is positive above the horizontal axis, cosine positive to the right. Tangent divides vertical by horizontal coordinate and is undefined where the horizontal coordinate is zero. The relation cos²θ+sin²θ=1 is simply the equation of the unit circle, providing a way to recover a magnitude when one coordinate is known.','单位圆把直角三角形比推广到所有实角。半径一时坐标直接给余弦与正弦，半径r时为r cosθ、r sinθ。正弦上半平面正，余弦右半平面正。正切为纵坐标除横坐标，横坐标零时无定义。平方和为一就是单位圆方程，可由一个坐标恢复另一坐标的大小。','An angle is in quadrant II with sin θ=3/5. What is cos θ?','θ在第二象限，sin θ=3/5，cos θ多少？',-0.8,'Use the unit-circle identity and the quadrant sign.','用平方和恒等式及象限符号。','|cosθ|=√(1−9/25)=4/5; quadrant II has negative cosine, so −4/5.','余弦大小4/5，第二象限余弦负，所以−4/5。');
deepen('M02.03','An identity must be valid for every angle in its common domain. One method is to rewrite all terms using sine and cosine, then use the circle identity and ordinary algebra. Avoid multiplying by a denominator that might vanish without tracking the excluded cases. Angle addition formulas can be understood by composing planar rotations: the rotated horizontal and vertical components combine to produce the familiar products. Setting the two angles equal gives double-angle formulas, and replacing one angle by its negative gives difference formulas. Graph transformations are a separate application: changing the argument translates or rescales horizontal position, while changing the output rescales or shifts height.','恒等式须在共同定义域对所有角成立。可把各项改成正弦余弦，再用平方和与代数。乘可能为零的分母须追踪排除情况。和角公式可由平面旋转复合解释，分量组合产生乘积；两角相同得倍角，一角取负得差角。图像变换则区分输入改变的横向效果与输出改变的纵向效果。','For acute θ with sin θ=5/13 and cos θ=12/13, find sin 2θ.','锐角θ的正弦5/13、余弦12/13，求sin 2θ。',120/169,'Use the double-angle product 2 sinθ cosθ.','用2 sinθ cosθ。','2×(5/13)×(12/13)=120/169.','2×5/13×12/13=120/169。');
deepen('M02.04','A trigonometric equation asks for an entire solution set, often over a specified interval. First reduce it to a basic sine, cosine, or tangent equation while recording divisions and squaring steps. Find reference angles, then use the unit circle to locate every compatible quadrant. Add the correct period to describe all real solutions. Finally intersect those families with the required interval, paying attention to whether endpoints are included. For sinθ=c with |c|<1, two distinct angles generally appear per full turn; at c=±1 they merge into one. When |c|>1 there are no real solutions because sine is bounded.','三角方程要完整解集。先化为基本方程并记录除法平方，再求参考角，用单位圆找所有合适象限，加正确周期，最后与指定区间相交并查端点。sinθ=c在|c|<1时通常每周两解，c=±1时合为一解；|c|>1时因正弦有界而无实解。','How many solutions does sin θ=1 have on the closed interval [0,4π]?','sin θ=1在闭区间[0,4π]有几个解？',2,'List π/2+2kπ inside the interval.','列区间内π/2+2kπ。','The values are π/2 and 5π/2. Neither endpoint adds a solution, so two.','解为π/2、5π/2，两端不增加解，共两个。');
deepen('M02.05','Choose a triangle law according to the known information. Two sides and their included angle directly determine the third side by the cosine law. A known side-angle opposite pair allows the sine law to connect another opposite pair. If the sine law yields a sine value, both an acute angle and its supplementary obtuse angle may be candidates; the remaining angle sum decides whether either fits. For area, one half the product of two sides times the sine of their included angle comes from base times perpendicular height. Before numerical work, label each side opposite its angle to prevent mixing a side with a noncorresponding angle.','按已知选择定理。两边及夹角用余弦定理定第三边；已知一组对边对角可用正弦定理连接另一组。若解出正弦值，锐角与补角都可能，须用剩余角和判断。两边夹角面积公式来自底乘垂高的一半。计算前把每边与其对角配好，避免错配。','Two sides of lengths 8 and 5 include a 30-degree angle. What is the area?','两边8、5夹30度，面积多少？',10,'Use one half times both sides times sine of the included angle.','两边乘夹角正弦的一半。','Area=8×5×(1/2)/2=10.','面积8×5×1/2÷2=10。');
deepen('M02.06','A sinusoid separates amplitude, midline, period, and phase because each parameter changes a different feature. The period is the input increase needed to advance the internal angle by 2π. Thus ωT=2π in magnitude. A phase φ shifts where the cycle begins, and its horizontal displacement is −φ/ω when ω is nonzero. Inverse trigonometric functions recover a unique angle only after a principal range is chosen. To solve a physical oscillation problem, interpret amplitude as distance from the midline rather than the peak-to-peak range, which is twice as large. Initial position and direction of motion can distinguish phases giving the same instantaneous value.','正弦模型把振幅、中线、周期、相位分开，因为各参数改不同特征。周期是内角增加2π所需输入增量，故|ω|T=2π；相位对应水平位移−φ/ω。反三角函数选主值范围后才唯一。物理振幅是到中线距离，不是两倍大的峰峰值；同一位置时运动方向可区分相位。','For y=−3cos(2t)+4, what is the peak-to-peak range?','y=−3cos(2t)+4的峰峰范围多少？',6,'Find maximum minus minimum, not distance from the midline.','求最大减最小，不是到中线距离。','The amplitude is 3, so minimum is 1 and maximum 7; peak-to-peak range is 6.','振幅3，最小1、最大7，峰峰范围6。');
deepen('M03.01','Congruence means a rigid motion can make two figures coincide, so corresponding lengths and angles agree. Similarity also permits a uniform scale factor. For triangles, angle sum explains why two corresponding equal angles force the third equal. The remaining shape then fixes all side ratios. A scale factor k multiplies every altitude and every base by k, so area multiplies by k² through the triangle-area formula. To use a ratio, write vertices in corresponding order and check the side pairings against the equal angles. A congruence criterion needs its full data: two sides and a nonincluded angle generally do not determine one triangle.','全等可由刚体运动重合，保对应边角；相似还允许统一缩放。三角形两角相等由角和迫使第三角等，形状固定后边比一致。缩放k使底与高都乘k，面积按k²变。列比时应按对应顶点顺序并用角核对边。全等判据数据须完整，两边与非夹角一般不能唯一确定三角形。','Two similar triangles have area ratio 25:9. A side in the smaller triangle is 12. What is the corresponding larger side?','相似三角形面积比25:9，小三角形一边12，对应大边多少？',20,'Length ratio is the positive square root of area ratio.','长度比为面积比的正平方根。','The length ratio is 5:3, so 12×5/3=20.','边比5:3，12×5/3=20。');
deepen('M03.02','Each triangle center comes from a locus. Points on a perpendicular bisector are equally distant from its segment endpoints, so the intersection of two such bisectors is equidistant from all three vertices and defines the circumcircle center. Points on an internal angle bisector are equally distant from its two side lines, giving the incenter and an inscribed circle. A median joins a vertex to the opposite midpoint; using coordinates or area ratios shows the three medians meet at the average of the vertex coordinates. In an equilateral triangle these constructions coincide by symmetry, but in a general triangle they produce different points.','每种中心来自轨迹。垂直平分线点到两端等距，两条交点遂到三顶点等距，定义外心。内角平分线点到两边直线等距，产生内心与内切圆。中线连顶点与对边中点，坐标或面积比可证三中线交于顶点坐标平均。等边三角形因对称这些点重合，一般三角形则不同。','A triangle has vertices (0,0),(6,0),(0,9). What is the centroid y-coordinate?','三角形顶点(0,0)、(6,0)、(0,9)，重心y坐标多少？',3,'Average the three vertex y-coordinates.','三个顶点y坐标取平均。','(0+0+9)/3=3. The centroid is (2,3).','(0+0+9)/3=3，重心为(2,3)。');
deepen('M03.03','Circle theorems connect angles to arcs and products to distances along lines. The inscribed-angle theorem can be proved by joining the center to the angle vertex and arc endpoints, then using equal radii to create isosceles triangles. Two opposite angles of a cyclic quadrilateral intercept complementary arcs whose measures total a full turn, so their half-arc angles total a half-turn. For intersecting chords, similar triangles give a ratio that rearranges to equal segment products. A tangent is perpendicular to the radius at the contact point. Label which arc is intercepted, because switching to the other arc changes the associated angle.','圆定理把角连到弧，把乘积连到共线距离。连接圆心与角顶点、弧端点，用等半径形成等腰三角形可证圆周角定理。内接四边形对角截互补弧，总弧整周，半弧角和半周。交弦可由相似三角形比值改写成乘积相等。切线垂直切点半径，必须标清所截弧，换弧会改角。','Two intersecting chords have segments 2 and 15 on one chord, 5 and x on the other. Find x.','两相交弦一条分段2、15，另一条5、x，x多少？',6,'Use equality of the two segment products.','令两条弦分段乘积相等。','2×15=5x, so x=30/5=6.','2×15=5x，x=6。');
deepen('M03.04','Area is often a bridge between unrelated-looking lengths. If two triangles have the same base, their area ratio equals their altitude ratio; if they share an altitude, it equals their base ratio. Splitting a larger figure into nonoverlapping pieces makes total area the sum of piece areas. An altitude may lie outside an obtuse triangle, but the perpendicular distance to the extended base line still gives the area. Triangle inequality can be understood as the shortest path between two points being a straight segment. A strict inequality is required for three positive lengths to form a nondegenerate triangle; equality collapses its area to zero.','面积常连接看似无关的长度。同底三角形面积比等于高比，同高则等于底比。分成不交部分时总面积相加。钝角三角形高脚可在外部，但到延长底线的垂距仍用于面积。三角不等式来自两点间直线最短，三正边成非退化三角形需严格不等，取等面积零。','Triangles sharing a base have heights 4 and 10. The smaller area is 18. What is the larger area?','同底三角形高4与10，小面积18，大面积多少？',45,'Use the ratio of heights because the base is shared.','同底所以用高比。','Larger area=18×10/4=45.','大面积18×10/4=45。');
deepen('M03.05','A transformation gives a systematic way to compare figures. A translation adds one fixed displacement to every point. A rotation fixes a center and changes each point’s direction by the same angle. A reflection reverses the perpendicular coordinate relative to its mirror line, keeping points on the mirror fixed. Their compositions preserve distances, so they can prove congruence. In a construction, separate the recipe from the proof: drawing two equal circles creates candidate intersections, while their equal-distance properties establish the perpendicular bisector. Existence must also be checked; two circles with insufficient radius may fail to intersect, so the construction requires an appropriate radius choice.','变换系统比较图形。平移给每点加同位移，旋转绕中心统一转角，反射改变到镜线的垂直有向坐标，镜线上点固定。它们复合保距，可证全等。作图应分流程与证明：等圆交点是候选，等距性质才证明垂直平分线。还须查存在性，半径太小两圆不交，因此半径选择有条件。','Rotate point (2,5) by 90 degrees counterclockwise about the origin. What is the new x-coordinate?','点(2,5)绕原点逆时针90度，新x坐标多少？',-5,'The rotation sends (x,y) to (−y,x).','旋转规则为(x,y)→(−y,x)。','The image is (−5,2), so its x-coordinate is −5.','像为(−5,2)，x坐标−5。');
deepen('M03.06','A three-dimensional diagram compresses depth, so apparent lengths and angles on the page need not be true lengths and angles. Introduce perpendicular coordinate directions or choose a useful cross-section to reduce the problem to a plane. For a cuboid, first find a base diagonal with the Pythagorean theorem, then combine that diagonal with the perpendicular height. Volumes of prisms equal base area times height, whereas pyramids with the same base and height have one third that volume. Surface area requires adding exposed faces, not multiplying three lengths. Scaling every dimension by k explains why areas and volumes have different power laws.','立体图压缩深度，纸面长角不一定真实。可引入垂直坐标或取有用截面化为平面。长方体先求底面对角线，再与垂直高用勾股。棱柱体积底面积乘高，同底同高棱锥为三分之一。表面积加外露面，不是三长度相乘。所有尺寸放大k解释面积与体积的不同幂律。','A pyramid has base area 30 and perpendicular height 9. What is its volume?','棱锥底面积30、垂直高9，体积多少？',90,'A pyramid occupies one third of the corresponding prism volume.','棱锥为同底同高棱柱体积三分之一。','Volume=30×9/3=90.','体积30×9/3=90。');
deepen('M04.01','The distance formula comes from a right triangle formed by horizontal and vertical coordinate differences. The signs of those differences determine displacement direction, but squaring removes sign for length. A midpoint is obtained by taking half of the displacement from the first endpoint, yielding the average-coordinate formula. More generally, a point dividing a segment in a given ratio is a weighted average of endpoints. Translating the coordinate origin changes both endpoint coordinates by the same amount, so their difference and distance stay unchanged. This provides an algebraic check that the formula describes geometry rather than a special choice of axes.','距离公式来自横纵坐标差组成的直角三角形。差的符号决定位移方向，平方后得到无向长度。中点从首端沿位移走一半，因此坐标平均；一般分点是端点的加权平均。平移原点使两端坐标同改，差与距离不变，说明公式描述几何而非特殊坐标选择。','Point P is one quarter of the way from A=(2,4) to B=(10,12). What is P y-coordinate?','P从A=(2,4)向B=(10,12)走四分之一路程，y坐标多少？',6,'Add one quarter of the y-displacement to the starting y-coordinate.','起始y加四分之一y位移。','P_y=4+(12−4)/4=6.','P_y=4+(12−4)/4=6。');
deepen('M04.02','A line equation describes every point whose displacement from a fixed point is perpendicular to a chosen normal. Writing n·(x−p)=0 makes this geometric meaning explicit. Two nonparallel planar lines produce two independent linear constraints and generally meet at one point. Parallel normals make the equations dependent or inconsistent, corresponding to the same line or separate parallel lines. In three dimensions, one plane equation leaves two free directions, and two nonparallel planes generally intersect in a line. To determine whether a computed intersection belongs to a segment or ray, check its parameter range rather than relying only on the infinite-line equation.','直线方程描述从定点位移垂直法向量的全部点，n·(x−p)=0直接体现意义。平面两非平行线给两独立约束，一般一交点；法向平行时方程依赖或矛盾，对应重合或平行。三维一个平面方程留两自由方向，两非平行平面一般交成线。线段射线还须核参数范围，不能只看无限直线方程。','Lines 2x+y=11 and x−y=1 intersect. What is x?','2x+y=11与x−y=1交点x多少？',4,'Add the equations to eliminate y.','两式相加消y。','3x=12 gives x=4, then y=3 satisfies both lines.','3x=12得4，y=3同时满足两线。');
deepen('M04.03','Vector addition models consecutive displacements because the intermediate position cancels when endpoint differences are added. Scalar multiplication changes magnitude and may reverse direction. The dot product formula follows from the cosine law applied to the triangle formed by two vectors: expanding ||u−v||² gives the coordinate products, while the geometric version gives the cosine of the included angle. This connects algebra and geometry. Projection onto a nonzero vector v is ((u·v)/(v·v))v, because the remainder must be perpendicular to v. The scalar coefficient can be negative, indicating that the projected component points opposite v.','向量相加表示连续位移，因为端点差相加时中间点抵消。数乘改变长度并可能反向。把余弦定理用于两向量形成的三角形，展开||u−v||²即可连接坐标点积与夹角。投影到非零v为((u·v)/(v·v))v，因为余项须垂直v；系数可负，表示反向分量。','Project u=(4,7) onto v=(0,2). What is the projection y-coordinate?','把u=(4,7)投影到v=(0,2)，投影y坐标多少？',7,'Use ((u·v)/(v·v))v or recognize the vertical axis.','用投影公式，或识别竖轴。','u·v=14 and v·v=4, giving (14/4)(0,2)=(0,7).','点积14，v平方长4，投影(14/4)(0,2)=(0,7)。');
deepen('M04.04','Each conic also has a distance-based definition. An ellipse has a fixed sum of distances to two foci, a hyperbola a fixed absolute difference, and a parabola equal distance to a focus and a directrix line. Squaring these distance equations produces standard quadratic equations after appropriate coordinates are chosen. Completing squares reveals translations and axis scales. For an axis-aligned ellipse, the larger semiaxis determines the major direction and focal distance satisfies c²=a²−b² when a≥b. A hyperbola instead satisfies c²=a²+b². These distinct signs reflect different geometric definitions, so they should not be memorized without context.','圆锥曲线也有距离定义：椭圆到两焦点距离和固定，双曲线绝对差固定，抛物线到焦点与准线等距。选坐标后平方距离式得到二次标准式，配方揭示平移与轴尺度。轴向椭圆a≥b时c²=a²−b²，双曲线则c²=a²+b²；符号差来自几何定义，不宜脱离背景硬记。','Ellipse x²/25+y²/16=1 has foci on the x-axis. What is each focus distance from the center?','椭圆x²/25+y²/16=1焦点在x轴，焦距中心多少？',3,'Use c²=a²−b² for an ellipse.','椭圆使用c²=a²−b²。','c=√(25−16)=3, so foci are (±3,0).','c=√9=3，焦点(±3,0)。');
deepen('M04.05','A parameter is not necessarily time, but when it is time the parameterization contains motion information that the geometric curve alone lacks. Two parameterizations can trace the same circle at different speeds or in opposite directions. Cartesian elimination often loses this distinction. Polar coordinates describe a point using a ray and distance along it; adding 2π to the angle gives the same ray. With conventions allowing negative r, reversing the radial sign and adding π can also describe the same point. To transform equations, substitute x=r cosθ and y=r sinθ and then check whether special cases such as r=0 were lost through division.','参数未必是时间，但当它是时间时，参数式含曲线本身没有的运动信息。不同参数可沿同圆以不同速率或反向走，消参常丢此区别。极坐标用射线与沿线距离表示点，角加2π同射线；允许负r时，r反号并角加π也同点。换式后须查如除r可能丢掉原点的特殊情形。','For x=1+2t,y=5−t with 0≤t≤3, what is the largest x on the traced segment?','x=1+2t、y=5−t，0≤t≤3，所描线段最大x多少？',7,'x increases with t, so inspect the final parameter endpoint.','x随t增，在末端参数取最大。','At t=3, x=1+6=7. The unrestricted line extends farther, but the segment does not.','t=3时x=7，无限直线还能延伸，指定线段不能。');
deepen('M04.06','The cross product packages the area and orientation of a parallelogram. Its components can be computed by the determinant pattern, but the geometric checks are equally important: it must be perpendicular to both input vectors, reverse under swapping them, and scale appropriately when an input is multiplied by a scalar. The magnitude is area, so the associated triangle has half that magnitude. Dotting a third vector with the cross product measures signed height times base area, giving oriented volume. A zero scalar triple product means the three vectors are coplanar or dependent, whereas its absolute value gives ordinary nonnegative volume.','叉积编码平行四边形面积与方向。分量可按行列式模式算，但须核垂直两个输入、交换反号、数乘相应缩放。其模是面积，三角形取一半。再与第三向量点乘就是有向高乘底面积，得有向体积；三重积零表示共面或相关，绝对值给普通非负体积。','Vectors (3,0,0) and (0,4,0) form two sides of a triangle. What is its area?','(3,0,0)与(0,4,0)作三角形两边，面积多少？',6,'Take half the cross-product magnitude.','叉积模取一半。','The cross-product magnitude is 3×4=12, so triangle area is 6.','叉积模12，三角形面积6。');
